INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "终止是不再往下做了，停下来。", "primary_collocate": null, "pronunciation": "zhōng zhǐ", "ipa": "tʂʊŋ˥ tʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "听到警报声，工人立刻终止了工作。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开到一半，经理终止了讨论。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人作弊，老师马上终止了考试。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器出了故障，必须终止运行。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药有副作用，医生让她终止用药。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发生地震，音乐会只好终止。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的谈话因为一个电话而终止了。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大家劝说下，他终止了这次危险的行动。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，学校终止了今天的户外活动。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络断了，视频通话只好终止。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "终止了", "label": "体标（了）"}, {"form": "终止过", "label": "体标（过）"}, {"form": "終止", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "正在进行的活动或过程中途停下来，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、希望等，不能与“工作”搭配。"}, {"text": "终止", "is_correct": true, "explanation": "终止：中途停下，与“听到警报声”和“立刻”的情境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能用来指停下工作。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄碎东西，不能表示停止工作。"}], "explanations": {"点燃": "搭配：“点燃”的对象是火、希望等，不能与“工作”搭配。", "终止": "终止：中途停下，与“听到警报声”和“立刻”的情境相符。", "唱": "语义：“唱”的对象是歌曲，不能用来指停下工作。", "打碎": "语义：“打碎”指弄碎东西，不能表示停止工作。"}, "sentence_index": 0, "correct_answer": "终止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作业全部做完后，他终止了作业。", "explanation": "这里应该用〈完成〉。终止表示中途停下，不是做完；作业已经做完时要说“完成”。"}, {"text": "他说到一半终止了一下，然后又接着说。", "explanation": "这里应该用〈停顿〉。终止是停下后不再继续，说话中间短暂停一下再接着说要用“停顿”。"}, {"text": "会议中途终止了十分钟。", "explanation": "这里应该用〈暂停〉。终止是不再继续，中途暂停十分钟应该用“暂停”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放大", "is_correct": false, "explanation": "语义：“放大”指变大，不表示谈话停下来。"}, {"text": "消失", "is_correct": false, "explanation": "搭配：“消失”一般不与“谈话”搭配，不说谈话消失了。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：谈话不会腐烂，这个词与情境完全不符。"}, {"text": "终止", "is_correct": true, "explanation": "终止：中途停下，与“因为一个电话”的原因相符。"}], "explanations": {"放大": "语义：“放大”指变大，不表示谈话停下来。", "消失": "搭配：“消失”一般不与“谈话”搭配，不说谈话消失了。", "腐烂": "语义：谈话不会腐烂，这个词与情境完全不符。", "终止": "终止：中途停下，与“因为一个电话”的原因相符。"}, "sentence_index": 6, "correct_answer": "终止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议顺利终止了，大家都很满意。", "explanation": "这里应该用〈结束〉。终止强调中途停下，不用于顺利做完的情况。"}, {"text": "他终止了手机，然后去吃饭了。", "explanation": "这里应该用〈关机〉。终止指中途停下正在进行的过程，手机关掉要说“关机”。"}, {"text": "孩子终于终止了长高。", "explanation": "这里应该用〈停止〉。终止指中途停下正在做的事，长高是持续的变化，不能说“终止长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议开到一半，经理很终止了讨论。", "corrected_sentence": "会议开到一半，经理马上终止了讨论。", "error_description": "“很”是程度副词，一般不修饰“终止”这类动作动词，应改用“马上”表示时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "断网以后，我们的聊天只好终止着。", "corrected_sentence": "断网以后，我们的聊天只好终止了。", "error_description": "“终止”是一次性结束的动作，不能用“着”表示持续，应该用“了”表示已经结束。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "开始：指使某事开始进行，与“终止”意思相反，与“终止谈判”构成对立。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：指交换意见、研究问题，与“终止”并不构成反义关系。"}, {"text": "记录", "is_correct": false, "explanation": "记录：指把信息写下来，与“终止”并不构成反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运：指把东西从一处搬到另一处，与“终止”并不构成反义关系。"}], "correct_answer": "开始", "explanations": {"开始": "开始：指使某事开始进行，与“终止”意思相反，与“终止谈判”构成对立。", "讨论": "讨论：指交换意见、研究问题，与“终止”并不构成反义关系。", "记录": "记录：指把信息写下来，与“终止”并不构成反义关系。", "搬运": "搬运：指把东西从一处搬到另一处，与“终止”并不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结束，停止。", "primary_collocate": null, "pronunciation": "zhōng zhǐ", "ipa": "tʂʊŋ˥ tʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司决定终止和他的合同。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队决定终止和这名球员的合同。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司终止了合作。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方不同意，我们只好终止谈判。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行已经终止了这项服务。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们明年一月会终止这份协议。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师决定终止这次实验，因为机器坏了。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这个计划今天必须终止。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房合同到月底就终止了。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，不得不终止学业。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "终止了", "label": "体标（了）"}, {"form": "终止过", "label": "体标（过）"}, {"form": "終止", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "正式地结束合同、合作、谈判等事情，使其不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的宾语是人或活动，不能带“合同”作宾语。"}, {"text": "终止", "is_correct": true, "explanation": "终止：正式结束已签订的合同，与“合同”搭配自然。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是随便走走，不能带“合同”，与结束合同无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不是合同，这句话讲的是结束合同。"}], "explanations": {"欢迎": "搭配：“欢迎”的宾语是人或活动，不能带“合同”作宾语。", "终止": "终止：正式结束已签订的合同，与“合同”搭配自然。", "散步": "语义：“散步”是随便走走，不能带“合同”，与结束合同无关。", "唱": "语义：“唱”的对象不是合同，这句话讲的是结束合同。"}, "sentence_index": 0, "correct_answer": "终止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的眼泪突然终止了，大家都松了口气。", "explanation": "这里应该用〈止住〉。终止指正式或整体的结束，眼泪停下来要说“止住”，不能用“终止”。"}, {"text": "他终止了那个苹果，然后吃掉了。", "explanation": "这里应该用〈吃掉〉。终止用于活动、合同等过程，苹果是具体东西，不能被终止。"}, {"text": "他的讲话终止了一会儿。", "explanation": "这里应该用〈停顿〉。终止是正式、彻底地结束，讲话中短暂停一会儿要说“停顿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆祝", "is_correct": false, "explanation": "语义：机器坏了，实验无法进行，不宜“庆祝”。"}, {"text": "终止", "is_correct": true, "explanation": "终止：结束这次实验，与“因为机器坏了”的原因相符。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”的宾语是东西或能力，不能说“拥有实验”。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”多用于视频、音乐等，不能用于“实验”。"}], "explanations": {"庆祝": "语义：机器坏了，实验无法进行，不宜“庆祝”。", "终止": "终止：结束这次实验，与“因为机器坏了”的原因相符。", "拥有": "搭配：“拥有”的宾语是东西或能力，不能说“拥有实验”。", "播放": "搭配：“播放”多用于视频、音乐等，不能用于“实验”。"}, "sentence_index": 6, "correct_answer": "终止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终止了篮球队，不再参加比赛。", "explanation": "这里应该用〈解散〉。终止多用于合同、合作、学业等事务的结束，球队这类组织的撤销要说“解散”。"}, {"text": "他一进屋就终止了所有的灯。", "explanation": "这里应该用〈关〉。终止指结束正式或较大的事务，关灯这类小动作要说“关”。"}, {"text": "这次实验的结果终止了，大家都很惊讶。", "explanation": "这里应该用〈得出〉。终止指正在进行的过程被结束，实验结果是得出的，不能说“终止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在终止了合作。", "corrected_sentence": "我们正在终止合作。", "error_description": "“正在”表示动作正在进行，“了”表示动作已经完成，二者不能同时用在同一个动作上，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项协议到年底就终止着。", "corrected_sentence": "这项协议到年底就终止了。", "error_description": "“终止”表示结束这一瞬间的动作，不能用“着”表示持续状态，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
