INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94567, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听起来是用耳朵听了以后，觉得是这样。", "primary_collocate": null, "pronunciation": "tīng qǐ lái", "ipa": "tʰiŋ˥ tɕʰi˨˩ lai˧˥", "syllable_count": 3, "sentences": [{"text": "这首歌听起来很舒服。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音听起来很累。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种语言听起来像唱歌。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的声音听起来像有人在跳舞。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段音乐听起来很安静。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的汉语听起来很自然。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里他的声音听起来很远。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那种鸟叫听起来像小孩在哭。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首外国歌听起来有点快。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风声听起来很吓人。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用耳朵听到声音后得到的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听起来", "is_correct": true, "explanation": "「听起来」表示用耳朵听到声音后的感觉，「很舒服」描述的正是听感，句意通顺。"}, {"text": "闻起来", "is_correct": false, "explanation": "语义：「闻」要用鼻子嗅气味，不能用来描述歌曲的听感。"}, {"text": "摸起来", "is_correct": false, "explanation": "语义：「摸」要用手触碰，与听歌后的感觉无关。"}, {"text": "吃起来", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，「这首歌」不能与「吃起来」搭配。"}], "explanations": {"听起来": "「听起来」表示用耳朵听到声音后的感觉，「很舒服」描述的正是听感，句意通顺。", "闻起来": "语义：「闻」要用鼻子嗅气味，不能用来描述歌曲的听感。", "摸起来": "语义：「摸」要用手触碰，与听歌后的感觉无关。", "吃起来": "搭配：「吃」的对象是食物，「这首歌」不能与「吃起来」搭配。"}, "sentence_index": 0, "correct_answer": "听起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画听起来很美。", "explanation": "这里应该用〈看起来〉。画要用眼睛看，「听起来」只指耳朵听到声音后的感觉，判断画面要用〈看起来〉。"}, {"text": "这杯咖啡听起来很甜。", "explanation": "这里应该用〈尝起来〉。耳朵听不到味道，判断甜味要用〈尝起来〉。"}, {"text": "这锅汤听起来很香。", "explanation": "这里应该用〈闻起来〉。耳朵听不到气味，判断香味要用〈闻起来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听起来", "is_correct": true, "explanation": "「听起来」表示用耳朵听到的感觉，「电话里他的声音」「很远」描述的是听感，句意通顺。"}, {"text": "尝起来", "is_correct": false, "explanation": "语义：「尝」要用舌头辨别味道，不能用来描述声音的远近。"}, {"text": "数起来", "is_correct": false, "explanation": "语义：「数」指计数，与「声音很远」的描述不相符。"}, {"text": "写起来", "is_correct": false, "explanation": "搭配：「写起来」说的是书写的难易，不能与「他的声音」「很远」搭配。"}], "explanations": {"听起来": "「听起来」表示用耳朵听到的感觉，「电话里他的声音」「很远」描述的是听感，句意通顺。", "尝起来": "语义：「尝」要用舌头辨别味道，不能用来描述声音的远近。", "数起来": "语义：「数」指计数，与「声音很远」的描述不相符。", "写起来": "搭配：「写起来」说的是书写的难易，不能与「他的声音」「很远」搭配。"}, "sentence_index": 6, "correct_answer": "听起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布听起来很粗糙。", "explanation": "这里应该用〈摸起来〉。粗糙与否要用手感受，耳朵听不到质地，应说〈摸起来很粗糙〉。"}, {"text": "这杯水听起来很烫。", "explanation": "这里应该用〈摸起来〉。烫不烫要靠接触，耳朵听不到温度，应说〈摸起来很烫〉。"}, {"text": "这床被子听起来很暖和。", "explanation": "这里应该用〈摸起来〉。暖和与否要靠接触，耳朵听不到温度，应说〈摸起来很暖和〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首曲子听起来着很温柔。", "corrected_sentence": "这首曲子听起来很温柔。", "error_description": "错误：「着」不能放在「听起来」后面。「听起来」不带体标「着」，应改为「听起来很温柔」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远处的鸟叫声听起来的很清脆。", "corrected_sentence": "远处的鸟叫声听起来很清脆。", "error_description": "错误：「听起来」作状语，后面不能加结构助词「的」，应删去「的」，说「听起来很清脆」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
