INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94568, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "就听到的内容来判断、感觉。", "primary_collocate": null, "pronunciation": "tīng qǐ lái", "ipa": "tʰiŋ˥ tɕʰi˨˩ lai˧˥", "syllable_count": 3, "sentences": [{"text": "你说的话听起来很有道理。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划听起来不太难。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的借口听起来不像真的。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听起来，你们昨天玩得很开心。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息听起来有点奇怪。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的那家饭馆听起来不错。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的故事听起来很可怕。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法听起来简单，做起来很难。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的计划听起来比我的好。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事听起来太好了，我不太相信。", "target_word": "听起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "根据听到的话或消息的内容来判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听起来", "is_correct": true, "explanation": "「听起来」表示根据听到的话作出判断，与「你说的话」「很有道理」相符。"}, {"text": "尝起来", "is_correct": false, "explanation": "语义：「尝」要用舌头辨别味道，不能用来评判道理。"}, {"text": "写起来", "is_correct": false, "explanation": "搭配：「写起来」说的是书写的难易，不能用来评价说话内容是否有道理。"}, {"text": "闻起来", "is_correct": false, "explanation": "语义：「闻」要用鼻子嗅气味，与判断话语是否有道理无关。"}], "explanations": {"听起来": "「听起来」表示根据听到的话作出判断，与「你说的话」「很有道理」相符。", "尝起来": "语义：「尝」要用舌头辨别味道，不能用来评判道理。", "写起来": "搭配：「写起来」说的是书写的难易，不能用来评价说话内容是否有道理。", "闻起来": "语义：「闻」要用鼻子嗅气味，与判断话语是否有道理无关。"}, "sentence_index": 0, "correct_answer": "听起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脸听起来很红。", "explanation": "这里应该用〈看起来〉。脸红是看到的颜色，耳朵听不到，判断颜色要用〈看起来〉。"}, {"text": "这道菜听起来很咸。", "explanation": "这里应该用〈尝起来〉。耳朵听不到味道，判断咸淡要用〈尝起来〉。"}, {"text": "这瓶酒听起来很香。", "explanation": "这里应该用〈闻起来〉。耳朵听不到气味，判断香味要用〈闻起来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听起来", "is_correct": true, "explanation": "「听起来」表示根据听到的内容判断「他讲的故事很可怕」，句意通顺。"}, {"text": "摸起来", "is_correct": false, "explanation": "语义：「摸」要用手触碰，不能用来评价故事让人害怕与否。"}, {"text": "吃起来", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，「故事」不能与「吃起来」搭配。"}, {"text": "数起来", "is_correct": false, "explanation": "语义：「数」指计数，与「很可怕」的评价不相符。"}], "explanations": {"听起来": "「听起来」表示根据听到的内容判断「他讲的故事很可怕」，句意通顺。", "摸起来": "语义：「摸」要用手触碰，不能用来评价故事让人害怕与否。", "吃起来": "搭配：「吃」的对象是食物，「故事」不能与「吃起来」搭配。", "数起来": "语义：「数」指计数，与「很可怕」的评价不相符。"}, "sentence_index": 6, "correct_answer": "听起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头听起来很凉。", "explanation": "这里应该用〈摸起来〉。凉热要靠接触感受，耳朵听不到温度，应说〈摸起来很凉〉。"}, {"text": "这件毛衣听起来很暖和。", "explanation": "这里应该用〈摸起来〉。暖和与否要靠接触，耳朵听不到温度，应说〈摸起来很暖和〉。"}, {"text": "这碗汤听起来很烫。", "explanation": "这里应该用〈摸起来〉。烫不烫要靠接触感受，耳朵听不到温度，应说〈摸起来很烫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你说的那个方案听起来了很合理。", "corrected_sentence": "你说的那个方案听起来很合理。", "error_description": "错误：「听起来」后面不能直接加「了」。正确形式为「听起来很合理」，「听起来」是表示判断的独立成分，不带体标「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个说法听起来过很有意思。", "corrected_sentence": "这个说法听起来很有意思。", "error_description": "错误：「过」不能放在「听起来」后面。「听起来」是判断性的独立成分，不带体标「过」，应改为「听起来很有意思」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94569, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "节省", "is_correct": true, "explanation": "节省：不用掉力气，与“花费”构成反义关系。"}, {"text": "开始", "is_correct": false, "explanation": "开始是起始，与花费的用掉之义无关。"}, {"text": "保持", "is_correct": false, "explanation": "保持是维持原状，与花费的用掉之义无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏是赏识，与花费不是反义关系。"}], "correct_answer": "节省", "explanations": {"节省": "节省：不用掉力气，与“花费”构成反义关系。", "开始": "开始是起始，与花费的用掉之义无关。", "保持": "保持是维持原状，与花费的用掉之义无关。", "欣赏": "欣赏是赏识，与花费不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94569, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "节省", "is_correct": true, "explanation": "节省：不用掉时间，与“每个星期花费三个小时”构成反义关系。"}, {"text": "赢得", "is_correct": false, "explanation": "赢得是取得，与花费不构成反义关系。"}, {"text": "离开", "is_correct": false, "explanation": "离开是动身或走开，与花费不构成反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看是注视，与花费不是反义关系。"}], "correct_answer": "节省", "explanations": {"节省": "节省：不用掉时间，与“每个星期花费三个小时”构成反义关系。", "赢得": "赢得是取得，与花费不构成反义关系。", "离开": "离开是动身或走开，与花费不构成反义关系。", "观看": "观看是注视，与花费不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花费是用掉钱、时间或力气。", "primary_collocate": null, "pronunciation": "huā fèi", "ipa": "xwa˥ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "搬这个大柜子花费了我们很大力气。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学花费多少钱，你算过吗？", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们花费两个小时才走到山顶。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花费一整天整理房间。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我花费了五百元买菜。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了找工作花费了很多时间。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做会花费太多钱，我们换个办法吧。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师花费了很多力气教我们读课文。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别花费时间在没用的事上。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期花费三个小时练习写字。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花费了", "label": "完成体"}, {"form": "花费过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动作：用掉钱、时间或力气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94569, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花费", "is_correct": true, "explanation": "花费：用掉钱、时间或力气，是本义。"}, {"text": "化肥", "is_correct": false, "explanation": "huàféi 与 huāfèi 两个音节声调都不同，意思是化学肥料。"}, {"text": "话费", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，意思是电话费用。"}, {"text": "花肥", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，意思是花用的肥料。"}], "explanations": {"花费": "花费：用掉钱、时间或力气，是本义。", "化肥": "huàféi 与 huāfèi 两个音节声调都不同，意思是化学肥料。", "话费": "huà（第四声）与 huā（第一声）声调不同，意思是电话费用。", "花肥": "féi（第二声）与 fèi（第四声）声调不同，意思是花用的肥料。"}, "sentence_index": null, "correct_answer": "花费"}, "level_3": {"options": [{"text": "花费", "is_correct": true, "explanation": "花费：用掉力气，与“很大力气”搭配，符合句意。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：挂是悬挂，不能说“挂了很大力气”。"}, {"text": "送", "is_correct": false, "explanation": "搭配：送的对象是物品，不能说“送了我们很大力气”。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：盖是建造或覆盖，不能与“力气”搭配。"}], "explanations": {"花费": "花费：用掉力气，与“很大力气”搭配，符合句意。", "挂": "搭配：挂是悬挂，不能说“挂了很大力气”。", "送": "搭配：送的对象是物品，不能说“送了我们很大力气”。", "盖": "搭配：盖是建造或覆盖，不能与“力气”搭配。"}, "sentence_index": 0, "correct_answer": "花费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她花费了一整天的歌。", "explanation": "这里应该用〈唱〉。花费指用掉时间，歌是唱出来的，不能被花费。"}, {"text": "他花费了一个好朋友。", "explanation": "这里应该用〈交到〉。花费的对象是钱、时间、精力，不能用于结交朋友。"}, {"text": "我花费了一张旧照片。", "explanation": "这里应该用〈丢〉。花费是主动用掉东西，弄丢照片要用丢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花费", "is_correct": true, "explanation": "花费：用掉太多钱，与“这样做会”的语境搭配，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是撕裂，与“换个办法”的节约语境不符。"}, {"text": "播", "is_correct": false, "explanation": "搭配：播是播放或播种，不能用于“钱”。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：扛是用肩负重，不能用于“钱”。"}], "explanations": {"花费": "花费：用掉太多钱，与“这样做会”的语境搭配，符合句意。", "撕": "语义：撕是撕裂，与“换个办法”的节约语境不符。", "播": "搭配：播是播放或播种，不能用于“钱”。", "扛": "搭配：扛是用肩负重，不能用于“钱”。"}, "sentence_index": 6, "correct_answer": "花费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我花费了一下午的音乐。", "explanation": "这里应该用〈听〉。花费指用掉钱、时间或力气，音乐是用来听的，不能说花费音乐。"}, {"text": "他花费了一幅画。", "explanation": "这里应该表达〈创作〉的意思。花费指用掉钱、时间或力气，不能用来说创作一幅作品。"}, {"text": "我花费了一本书。", "explanation": "这里应该用〈买〉。花费指用掉钱，买下书要用买，“花费一本书”不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他花费了很多时间手机上。", "corrected_sentence": "他花费了很多时间在手机上。", "error_description": "错误：介词“在”漏掉了。正确：花费+时间+在+某事+上，表示时间用在哪里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
