INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "耗费，用掉（钱、时间、精力等）。", "primary_collocate": null, "pronunciation": "huā fèi", "ipa": "xwa˥ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行我们花费了一万多元。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这辆车花费了两个星期。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花费很多精力照顾孩子。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子要花费不少钱。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想花费太多时间在手机上。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花费三年写完了这本书。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这顿饭，妈妈花费了一下午。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事花费了公司很多钱。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花费了所有的积蓄买了这台电脑。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习汉语需要花费很多时间。", "target_word": "花费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花费了", "label": "完成体"}, {"form": "花费过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动作：耗费钱、时间或精力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "花费", "is_correct": true, "explanation": "花费：耗费钱、时间或精力，是本义。"}, {"text": "化肥", "is_correct": false, "explanation": "huàféi 与 huāfèi 两个音节声调都不同，意思是化学肥料。"}, {"text": "话费", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，意思是电话费用。"}, {"text": "花肥", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，意思是花用的肥料。"}], "explanations": {"花费": "花费：耗费钱、时间或精力，是本义。", "化肥": "huàféi 与 huāfèi 两个音节声调都不同，意思是化学肥料。", "话费": "huà（第四声）与 huā（第一声）声调不同，意思是电话费用。", "花肥": "féi（第二声）与 fèi（第四声）声调不同，意思是花用的肥料。"}, "sentence_index": null, "correct_answer": "花费"}, "level_3": {"options": [{"text": "花费", "is_correct": true, "explanation": "花费：耗费钱，与“一万多元”搭配，符合句意。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：盖是建造或覆盖，不能与“一万多元”这种钱搭配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗的对象是衣服、碗等，不能说“洗了一万多元”。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，不能与“一万多元”搭配表示用钱。"}], "explanations": {"花费": "花费：耗费钱，与“一万多元”搭配，符合句意。", "盖": "搭配：盖是建造或覆盖，不能与“一万多元”这种钱搭配。", "洗": "搭配：洗的对象是衣服、碗等，不能说“洗了一万多元”。", "踢": "语义：踢是用脚击打，不能与“一万多元”搭配表示用钱。"}, "sentence_index": 0, "correct_answer": "花费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大火让他花费了一套房子。", "explanation": "这里应该用〈损失〉。花费是主动用掉钱、时间等，火灾造成的财产损失要用损失。"}, {"text": "他花费了一个好主意。", "explanation": "这里应该用〈想出〉。花费的对象是钱、时间、精力，不能说“花费一个主意”。"}, {"text": "小偷花费了我的钱包。", "explanation": "这里应该表达〈夺取、拿走〉的意思。花费指主动用掉钱、时间或力气，别人拿走我的钱包不能说花费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花费", "is_correct": true, "explanation": "花费：用掉时间，与“做这顿饭”和“一下午”搭配，符合句意。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：挂是悬挂，不能用来表示做饭所用的时间。"}, {"text": "播", "is_correct": false, "explanation": "语义：播是播放或播种，与做饭的语境不相干。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，与做饭的语境不相干。"}], "explanations": {"花费": "花费：用掉时间，与“做这顿饭”和“一下午”搭配，符合句意。", "挂": "搭配：挂是悬挂，不能用来表示做饭所用的时间。", "播": "语义：播是播放或播种，与做饭的语境不相干。", "踢": "语义：踢是用脚击打，与做饭的语境不相干。"}, "sentence_index": 6, "correct_answer": "花费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中花费了冠军。", "explanation": "这里应该用〈赢得〉。花费用于钱、时间、力气，比赛的冠军要用赢得。"}, {"text": "我想花费这些旧信件。", "explanation": "这里应该用〈保留〉。花费是用掉东西，珍藏旧信件要用保留。"}, {"text": "我花费了她的生日。", "explanation": "这里应该用〈忘记〉。花费不能支配生日这类日期信息，忘记的对象不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我花费很多时间工作上。", "corrected_sentence": "我花费很多时间在工作上。", "error_description": "错误：介词“在”漏掉了。正确：花费+时间+在+某事+上，表示时间用在哪里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们花费着两天才到北京。", "corrected_sentence": "我们花费了两天才到北京。", "error_description": "错误：“花费”表示用掉时间，不能接“着”。正确：花费了两天才到北京。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
