INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赔偿是弄坏别人的东西，就给他钱或新东西。", "primary_collocate": null, "pronunciation": "péi cháng", "ipa": "pʰeɪ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小明打破了窗户，要赔偿。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你弄坏了我的书，要赔偿我。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心摔碎了杯子，赔偿了五块钱。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子踢坏了邻居的门，爸爸去赔偿。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车被他弄坏了，他赔偿了一辆新的。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弄丢了图书馆的书，要赔偿。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗咬坏了他的鞋，主人赔偿了他。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车撞坏了路灯，得赔偿很多钱。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁打碎了东西，谁就要赔偿。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟弄脏了同学的衣服，只好赔偿。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赔偿了", "label": "体标"}, {"form": "赔偿过", "label": "体标"}, {"form": "赔偿金", "label": "复合"}, {"form": "赔偿费", "label": "复合"}], "register": "中性", "sense_fingerprint": "弄坏别人的东西后给钱或给新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赔偿", "is_correct": true, "explanation": "「赔偿」指弄坏别人的东西后给钱或给新的，「打破了窗户，要赔偿」语义完整。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」指称赞好的行为，「小明打破了窗户，要表扬」与弄坏东西后的处理相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "语义：「参观」指去某地观看，与打破窗户后的处理无关。"}, {"text": "举报", "is_correct": false, "explanation": "搭配：「举报」的对象是违法行为或违法者，不能用来处理打破窗户的事。"}], "explanations": {"赔偿": "「赔偿」指弄坏别人的东西后给钱或给新的，「打破了窗户，要赔偿」语义完整。", "表扬": "语义：「表扬」指称赞好的行为，「小明打破了窗户，要表扬」与弄坏东西后的处理相矛盾。", "参观": "语义：「参观」指去某地观看，与打破窗户后的处理无关。", "举报": "搭配：「举报」的对象是违法行为或违法者，不能用来处理打破窗户的事。"}, "sentence_index": 0, "correct_answer": "赔偿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子踢坏了邻居的门，爸爸先赔偿了错误。", "explanation": "这里应该用〈认错〉。「赔偿」针对弄坏东西造成的损失，错误不能用它来补偿，应说〈认错〉。"}, {"text": "孩子踢坏了邻居的门，爸爸后来赔偿了邻居的谅解。", "explanation": "这里应该用〈得到〉。谅解是别人给予的，不能用「赔偿」，应说〈得到邻居的谅解〉。"}, {"text": "孩子踢坏了邻居的门，爸爸赔偿了邻居的帮助。", "explanation": "这里应该用〈感谢〉。帮助不是损失，不能用「赔偿」，应说〈感谢邻居的帮助〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赔偿", "is_correct": true, "explanation": "「赔偿」指弄坏别人的东西后给钱或给新的，「狗咬坏了他的鞋」后主人应该赔偿，句意通顺。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：「表扬」指称赞好的行为，与狗咬坏鞋后的处理相矛盾。"}, {"text": "款待", "is_correct": false, "explanation": "语义：「款待」指热情招待客人，与狗咬坏鞋的情形不相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：「欢迎」多用于迎接人或活动，不能与「狗咬坏了鞋」这样的损失搭配。"}], "explanations": {"赔偿": "「赔偿」指弄坏别人的东西后给钱或给新的，「狗咬坏了他的鞋」后主人应该赔偿，句意通顺。", "表扬": "语义：「表扬」指称赞好的行为，与狗咬坏鞋后的处理相矛盾。", "款待": "语义：「款待」指热情招待客人，与狗咬坏鞋的情形不相符。", "欢迎": "搭配：「欢迎」多用于迎接人或活动，不能与「狗咬坏了鞋」这样的损失搭配。"}, "sentence_index": 6, "correct_answer": "赔偿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师赔偿了他的努力。", "explanation": "这里应该用〈表扬〉。努力是值得称赞的品质，不是损失，不能用「赔偿」，应说〈表扬他的努力〉。"}, {"text": "我们赔偿了他的计划。", "explanation": "这里应该用〈支持〉。计划不是可以补偿的损失，不能用「赔偿」，应说〈支持他的计划〉。"}, {"text": "我们赔偿了他的生日。", "explanation": "这里应该用〈庆祝〉。生日不是损失，不能用「赔偿」，应说〈庆祝他的生日〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他踢坏了别人的自行车，赔偿的一百块钱。", "corrected_sentence": "他踢坏了别人的自行车，赔偿了一百块钱。", "error_description": "错误：「了」误用为「的」，「赔偿的一百块钱」是名词性短语，不能作谓语。已完成的赔偿应使用体标「了」，正确形式为「赔偿了一百块钱」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他弄丢了朋友的书，赔偿着新的。", "corrected_sentence": "他弄丢了朋友的书，赔偿了新的。", "error_description": "错误：「着」表示动作正在进行，而此处是已完成的赔偿，应使用体标「了」。正确形式为「赔偿了新的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
