INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对损失给予补偿。", "primary_collocate": null, "pronunciation": "péi cháng", "ipa": "pʰeɪ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "公司应该赔偿客人的损失。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保险公司赔偿了客户的全部损失。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院赔偿了病人一大笔钱。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为飞机晚点，航空公司赔偿了乘客。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂赔偿了村民的损失。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意赔偿朋友的损失。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于施工事故，该公司赔偿了周边居民的经济损失。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院让他赔偿对方的损失。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店弄丢了行李，赔偿过我们一次。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故造成的损失，由责任方全部赔偿。", "target_word": "赔偿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赔偿了", "label": "体标"}, {"form": "赔偿过", "label": "体标"}, {"form": "赔偿金", "label": "复合"}, {"form": "赔偿费", "label": "复合"}], "register": "书面", "sense_fingerprint": "对造成的损失给予补偿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赔偿", "is_correct": true, "explanation": "「赔偿」指对损失给予补偿，「公司应该」「客人的损失」正好是补偿损失的语境。"}, {"text": "道歉", "is_correct": false, "explanation": "搭配：「道歉」不能直接带「损失」作宾语，「道歉客人的损失」不成立。"}, {"text": "参观", "is_correct": false, "explanation": "语义：「参观」指去某地观看，与补偿客人的损失无关。"}, {"text": "举报", "is_correct": false, "explanation": "语义：「举报」是向有关部门检举违法行为，与补偿客人的损失不符。"}], "explanations": {"赔偿": "「赔偿」指对损失给予补偿，「公司应该」「客人的损失」正好是补偿损失的语境。", "道歉": "搭配：「道歉」不能直接带「损失」作宾语，「道歉客人的损失」不成立。", "参观": "语义：「参观」指去某地观看，与补偿客人的损失无关。", "举报": "语义：「举报」是向有关部门检举违法行为，与补偿客人的损失不符。"}, "sentence_index": 0, "correct_answer": "赔偿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按时赔偿了欠款。", "explanation": "这里应该用〈偿还〉。「赔偿」针对的是造成的损失，欠款要用〈偿还〉。"}, {"text": "他勇敢地赔偿了错误。", "explanation": "这里应该用〈承认〉。错误是人的行为，不能用「赔偿」去补偿，应说〈承认错误〉。"}, {"text": "我感谢他的帮助，并赔偿他的帮助。", "explanation": "这里应该用〈报答〉。「赔偿」补偿的是损失，要还别人的人情要用〈报答〉，应说〈报答他的帮助〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赔偿", "is_correct": true, "explanation": "「赔偿」指对损失给予补偿，「周边居民的经济损失」与施工事故造成的损失相对应。"}, {"text": "参观", "is_correct": false, "explanation": "语义：「参观」指去某地观看，与对经济损失的处理无关。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：「拒绝」多用于请求、邀请等，不能与「经济损失」搭配。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」表示喜爱或赞美，与补偿居民的经济损失相矛盾。"}], "explanations": {"赔偿": "「赔偿」指对损失给予补偿，「周边居民的经济损失」与施工事故造成的损失相对应。", "参观": "语义：「参观」指去某地观看，与对经济损失的处理无关。", "拒绝": "搭配：「拒绝」多用于请求、邀请等，不能与「经济损失」搭配。", "欣赏": "语义：「欣赏」表示喜爱或赞美，与补偿居民的经济损失相矛盾。"}, "sentence_index": 6, "correct_answer": "赔偿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师赔偿了他的成绩。", "explanation": "这里应该用〈夸奖〉。成绩是值得称赞的事，不是损失，不能用「赔偿」，应说〈夸奖他的成绩〉。"}, {"text": "大家赔偿了他的生日。", "explanation": "这里应该用〈庆祝〉。生日不能用「赔偿」补偿，应说〈庆祝他的生日〉。"}, {"text": "妈妈赔偿了我的任性。", "explanation": "这里应该用〈原谅〉。任性是性格或行为，不是可以补偿的物质或经济损失，应说〈原谅我的任性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅把顾客的损失赔偿。", "corrected_sentence": "这家餐厅把顾客的损失赔偿了。", "error_description": "错误：「把」字句中动词后要有补语或「了」等成分，「赔偿」后缺少「了」，应说「把顾客的损失赔偿了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次台风造成的损失，由保险公司了赔偿。", "corrected_sentence": "这次台风造成的损失，由保险公司赔偿。", "error_description": "错误：「了」不能放在动词「赔偿」前面，应删去「了」，说「由保险公司赔偿」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
