INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路人是在路上走的、不认识的人。", "primary_collocate": null, "pronunciation": "lù rén", "ipa": "lu˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "一个路人把钱包还给了我。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请路人帮我拍照。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位路人不认识我，却对我笑了笑。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有很多路人，没有一个我认识。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个路人递给她一把伞。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问路人：“火车站怎么走？”", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让路人看到我哭。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路人听见孩子在叫，赶紧过来了。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是路人，以前从没见过。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个路人在雨中站着等车。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "路人甲", "label": "复合"}], "register": "中性", "sense_fingerprint": "在路上走的、素不相识的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7730a907-17d6-4070-8ade-01789c2b16ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“路人”指路上偶然遇到的、不认识的人，能拾到钱包并归还，符合语境。"}, {"text": "失主", "is_correct": false, "explanation": "语义：“失主”是丢东西的人，不会把钱包还给别人。"}, {"text": "电线杆", "is_correct": false, "explanation": "语义：“电线杆”是物体，不能把钱包还给人。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：“还给”的主语须是有意识的人，“钱包”不能作主语。"}], "explanations": {"路人": "正确：“路人”指路上偶然遇到的、不认识的人，能拾到钱包并归还，符合语境。", "失主": "语义：“失主”是丢东西的人，不会把钱包还给别人。", "电线杆": "语义：“电线杆”是物体，不能把钱包还给人。", "钱包": "搭配：“还给”的主语须是有意识的人，“钱包”不能作主语。"}, "sentence_index": 0, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "聚会上来的都是我的路人。", "explanation": "这里应该用〈熟人〉。路人指素不相识的人，与“我的”相矛盾，要用〈熟人〉。"}, {"text": "会场里坐满了路人。", "explanation": "这里应该用〈听众〉。路人不是来听讲座的，坐在会场里听讲的要用〈听众〉。"}, {"text": "车上坐满了路人。", "explanation": "这里应该用〈乘客〉。路人指路上走的人，坐在车上的人要用〈乘客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“路人”指路上不认识的人，可以在这里看到我哭，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不会看东西，不能“看到我哭”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能看见东西，与“看到我哭”不搭。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不会看东西，不能“看到我哭”。"}], "explanations": {"路人": "正确：“路人”指路上不认识的人，可以在这里看到我哭，符合语境。", "桌子": "语义：“桌子”不会看东西，不能“看到我哭”。", "窗户": "语义：“窗户”不能看见东西，与“看到我哭”不搭。", "雨伞": "语义：“雨伞”不会看东西，不能“看到我哭”。"}, "sentence_index": 6, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路人住在我家隔壁。", "explanation": "这里应该用〈邻居〉。路人指在路上走过、与自己无关的人，不会长期住在隔壁，住隔壁的要用〈邻居〉。"}, {"text": "路人正在开车。", "explanation": "这里应该用〈司机〉。路人只是路上走的人，驾驶车辆的人要用〈司机〉。"}, {"text": "路人正在带队训练。", "explanation": "这里应该用〈教练〉。路人不负责带队训练，指导队伍训练的人要用〈教练〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只路人叫住了我，问我去车站怎么走。", "corrected_sentence": "一个路人叫住了我，问我去车站怎么走。", "error_description": "错误：“一只路人”；正确：“一个路人”。“只”用于动物或成对的东西，路人指人，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路人的都主动帮我推开了车门。", "corrected_sentence": "路人都主动帮我推开了车门。", "error_description": "错误：“路人的都”；正确：“路人都”。“路人”作主语后不应加“的”，“都”直接接在主语之后表示总括。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在路上走的人，与自己无关的人。", "primary_collocate": null, "pronunciation": "lù rén", "ipa": "lu˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "路人都停下来看那只小狗。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了一个路人，他告诉我怎么走。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和我无关，我只是个路人。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有路人看见他摔倒了，马上跑过来。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分手后，就像路人一样。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的路人都带着伞。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位路人帮我拍了张照片。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了路人一眼，就走了。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我来说只是一个路人。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路人看着他们吵架，没有人说话。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "路人甲", "label": "复合"}], "register": "中性", "sense_fingerprint": "在路上走的人；与自己没有关系的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7730a907-17d6-4070-8ade-01789c2b16ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“路人”指路上走的人，与“都停下来看小狗”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地方，不会停下来看小狗。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能停下来看东西。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“停下来”的主语须是人，“河流”不能作此主语。"}], "explanations": {"路人": "正确：“路人”指路上走的人，与“都停下来看小狗”的语境相符。", "厨房": "语义：“厨房”是地方，不会停下来看小狗。", "椅子": "语义：“椅子”是家具，不能停下来看东西。", "河流": "搭配：“停下来”的主语须是人，“河流”不能作此主语。"}, "sentence_index": 0, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公交车上坐满了路人。", "explanation": "这里应该用〈乘客〉。路人指路上走的人，坐在车上的人要用〈乘客〉。"}, {"text": "舞台前面坐满了路人。", "explanation": "这里应该用〈观众〉。路人不是来看演出的，台下的看客要用〈观众〉。"}, {"text": "医院的病房里住满了路人。", "explanation": "这里应该用〈病人〉。路人不住院，住在病房里的人要用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“一位路人”指路上不认识的人，可以顺手帮忙拍照，符合语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”还不会拍照，与“帮我拍照”的语境不符。"}, {"text": "幽灵", "is_correct": false, "explanation": "语义：“幽灵”不能拍照，此处应指路上的人。"}, {"text": "雨伞", "is_correct": false, "explanation": "量词：“一位”只用于人，“雨伞”不能用“位”计量，也不会拍照。"}], "explanations": {"路人": "正确：“一位路人”指路上不认识的人，可以顺手帮忙拍照，符合语境。", "婴儿": "语义：“婴儿”还不会拍照，与“帮我拍照”的语境不符。", "幽灵": "语义：“幽灵”不能拍照，此处应指路上的人。", "雨伞": "量词：“一位”只用于人，“雨伞”不能用“位”计量，也不会拍照。"}, "sentence_index": 6, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的路人昨天来看我了。", "explanation": "这里应该用〈朋友〉。路人指不认识、只是路过的人，与“来看我”的熟人关系不符，要用〈朋友〉。"}, {"text": "路口的路人正在卖水果。", "explanation": "这里应该用〈小贩〉。路人指在路上走、与自己无关的人，不会在路口摆摊卖东西，那要用〈小贩〉。"}, {"text": "厨房里的路人正在做饭。", "explanation": "这里应该用〈厨师〉。路人不在厨房工作，做饭的人要用〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只路人帮我捡起了掉在地上的书。", "corrected_sentence": "一个路人帮我捡起了掉在地上的书。", "error_description": "错误：“一只路人”；正确：“一个路人”。“只”用于动物或成对的东西，路人是人，应用“个”或“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路人的都停下来看我。", "corrected_sentence": "路人都停下来看我。", "error_description": "错误：“路人的都”；正确：“路人都”。“路人”作主语后不应加“的”，“都”直接接在主语之后表示总括。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "作为，当着（某种身份）。", "primary_collocate": null, "pronunciation": "shēn wéi", "ipa": "ʂən˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "身为朋友，我不能看着你生病不管。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为客人，你不应该说主人的坏话。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为警察，他必须保护大家的安全。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为村里的老人，爷爷懂得很多事。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为姐姐，她把好吃的让给妹妹。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为歌手，她每天都练习唱歌。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为邻居，我们应该互相帮助。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为球迷，他从不错过一场比赛。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为丈夫，他每天做饭给家人吃。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身为老板，他先问员工累不累。", "target_word": "身为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "身为：以某种身份、角色出现，后面说明这个身份该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身为", "is_correct": true, "explanation": "正确：“身为”后接身份，说明作为朋友应尽的责任，与后半句相符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与后半句表达的关心和责任相矛盾。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负朋友”表示对不起朋友，与后半句“不能看着你生病不管”的关心和责任相矛盾。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”与后半句“不能看着你生病不管”所表达的责任感相矛盾。"}], "explanations": {"身为": "正确：“身为”后接身份，说明作为朋友应尽的责任，与后半句相符。", "讨厌": "语义：“讨厌”表示厌恶，与后半句表达的关心和责任相矛盾。", "辜负": "语义：“辜负朋友”表示对不起朋友，与后半句“不能看着你生病不管”的关心和责任相矛盾。", "欺骗": "语义：“欺骗”与后半句“不能看着你生病不管”所表达的责任感相矛盾。"}, "sentence_index": 0, "correct_answer": "身为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "身为一扇门，它认识很多村民。", "explanation": "这里应该用〈是〉。身为只用于人的身份或角色，门不能身为某种身份，应说“它是一扇门”。"}, {"text": "身为小王，他懂得很多事。", "explanation": "这里应该用〈是〉。身为后面要接身份或角色，“小王”是人名，不表示身份，所以不能用身为；应说“小王是村里的老人”之类。"}, {"text": "爷爷去年身为了村长。", "explanation": "这里应该用〈当上〉。身为只说明已有的身份，不能表示变成某种身份的过程，应说“爷爷去年当上了村长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身为", "is_correct": true, "explanation": "正确：“身为”后接身份，引出邻居之间应有的互助态度，与句意相符。"}, {"text": "怨恨", "is_correct": false, "explanation": "语义：“怨恨”表示仇视，与“我们应该互相帮助”的语境相反。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避邻居”表示不想见邻居，与“我们应该互相帮助”相矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "配价：“放弃”后面要接事情或机会，不能直接接“邻居”。"}], "explanations": {"身为": "正确：“身为”后接身份，引出邻居之间应有的互助态度，与句意相符。", "怨恨": "语义：“怨恨”表示仇视，与“我们应该互相帮助”的语境相反。", "躲避": "语义：“躲避邻居”表示不想见邻居，与“我们应该互相帮助”相矛盾。", "放弃": "配价：“放弃”后面要接事情或机会，不能直接接“邻居”。"}, "sentence_index": 6, "correct_answer": "身为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于身为老板，先问员工累不累。", "explanation": "这里应该用〈当上〉。身为说明现在拥有的身份，不能表示由别的身份变成某种身份的过程，“终于”后要用“当上”。"}, {"text": "身为老王，他先问员工累不累。", "explanation": "这里应该用〈是〉。身为后面要接身份或角色，“老王”是人名，不表示身份，所以不能用身为；应说“老王是老板”之类。"}, {"text": "身为一张桌子，它先问员工累不累。", "explanation": "这里应该用〈是〉。身为说明人拥有的身份或角色，桌子不能身为某种身份，所以不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "身为着司机，他每天都很早起床。", "corrected_sentence": "身为司机，他每天都很早起床。", "error_description": "“身为”后面不能加“着”，“身为”表示现在的身份，不是持续的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "身为了老板，他每天都很早来公司。", "corrected_sentence": "身为老板，他每天都很早来公司。", "error_description": "“身为”后面不能加“了”，“身为”表示现在的身份。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
