INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94580, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94580, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "方言，相比较而言。", "primary_collocate": null, "pronunciation": "jiào bǐ", "ipa": "tɕiɑʊ̯⁵¹ pi²¹⁴", "syllable_count": 2, "sentences": [{"text": "今年冬天较比暖和，不用穿太厚。", "target_word": "较比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜较比便宜，客人很多。", "target_word": "较比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们班，他的个子较比高。", "target_word": "较比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新房子离学校较比近，走路就到。", "target_word": "较比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路晚上较比安静，很少有车。", "target_word": "较比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的话不多，人较比老实。", "target_word": "较比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几种水果里，苹果较比便宜。", "target_word": "较比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近的超市东西较比全。", "target_word": "较比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上坐地铁人较比少，不太挤。", "target_word": "较比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的字较比大，爷爷看得清楚。", "target_word": "较比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "較比", "label": "繁体"}], "register": "方言", "sense_fingerprint": "方言副词，表示相比较而言，相当于“比较”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较比", "is_correct": true, "explanation": "正确：副词，表示相比较而言，与「不用穿太厚」的语境相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去的情况，与「今年冬天」这一当前时段矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」通常与「不」「没」等否定词连用，不能直接修饰「暖和」。"}, {"text": "不", "is_correct": false, "explanation": "语义：「不暖和」与后半句「不用穿太厚」的意思自相矛盾。"}], "explanations": {"较比": "正确：副词，表示相比较而言，与「不用穿太厚」的语境相符。", "曾经": "语义：「曾经」指过去的情况，与「今年冬天」这一当前时段矛盾。", "从来": "搭配：「从来」通常与「不」「没」等否定词连用，不能直接修饰「暖和」。", "不": "语义：「不暖和」与后半句「不用穿太厚」的意思自相矛盾。"}, "sentence_index": 0, "correct_answer": "较比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两队在场上较比，谁也不让谁。", "explanation": "这里应该用〈较量〉。〈较比〉指把事物放在一起对照比较，不表示双方竞争。"}, {"text": "他俩在棋盘前较比，谁也不肯认输。", "explanation": "这里应该用〈对弈〉。〈较比〉指对照比较，不表示下棋时的对抗。"}, {"text": "两家人为了一块地较比，闹得不可开交。", "explanation": "这里应该用〈争执〉。〈较比〉表示对照比较，不表示为利益而争执。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较比", "is_correct": true, "explanation": "正确：副词，表示相比较而言，与「这几种水果里」的比较语境相符。"}, {"text": "都", "is_correct": false, "explanation": "语义：「都」表示全部，不表示相对比较，与「这几种水果里」的比较语境不符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指不久之前，与「这几种水果里」的一般性比较不符。"}, {"text": "正在", "is_correct": false, "explanation": "语义：「正在」表示进行中，「苹果正在便宜」不通，与比较无关。"}], "explanations": {"较比": "正确：副词，表示相比较而言，与「这几种水果里」的比较语境相符。", "都": "语义：「都」表示全部，不表示相对比较，与「这几种水果里」的比较语境不符。", "刚刚": "语义：「刚刚」指不久之前，与「这几种水果里」的一般性比较不符。", "正在": "语义：「正在」表示进行中，「苹果正在便宜」不通，与比较无关。"}, "sentence_index": 6, "correct_answer": "较比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人在市场上较比价钱，谁也不肯让步。", "explanation": "这里应该用〈讨价还价〉。〈较比〉指对照比较，不表示为价钱争执或还价。"}, {"text": "这幅画的较比很强烈，一眼就能看出来。", "explanation": "这里应该用〈对比〉。〈较比〉作名词时不指颜色的对照效果，这里要说〈对比〉。"}, {"text": "这么大的雨，他较比地跑进了屋里。", "explanation": "这里应该用〈快〉。〈较比〉是副词，只表示相对程度，不修饰动作方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的夏天较比得凉快。", "corrected_sentence": "这个城市的夏天较比凉快。", "error_description": "「较比」是副词，后面直接接形容词，应说「较比凉快」；在「较比」和「凉快」之间加「得」不符合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市的牛奶较比了新鲜。", "corrected_sentence": "这家超市的牛奶较比新鲜。", "error_description": "副词「较比」后面不能加「了」，「较比了新鲜」不符合语法，应说「较比新鲜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
