INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94581, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "辛苦是做了很多事，很累。", "primary_collocate": null, "pronunciation": "xīn kǔ", "ipa": "ɕin˥ kʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈今天做了很多饭，真辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你工作一天了，一定很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师每天改作业，非常辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天搬了一天的家，大家都很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个星期我们加班，每个人都很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生做了六个小时的手术，真辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你帮我们做了这么多事，辛苦了。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照顾三个孩子，她每天都很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人做三份工作，所以很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们辛苦了，快坐下来吃点东西吧。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "辛辛苦苦", "label": "重叠"}], "register": "通用", "sense_fingerprint": "辛苦：做了很多事，感到很累", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辛苦", "is_correct": true, "explanation": "正确：辛苦指做了很多事而很累，与“妈妈今天做了很多饭”相符。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示不累，与“做了很多饭”的劳累相反，句意矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼睛，不说“真明亮”来评价做饭的感受。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音，与做饭的忙碌无关，句意不通。"}], "explanations": {"辛苦": "正确：辛苦指做了很多事而很累，与“妈妈今天做了很多饭”相符。", "轻松": "语义：“轻松”表示不累，与“做了很多饭”的劳累相反，句意矛盾。", "明亮": "搭配：“明亮”形容光线或眼睛，不说“真明亮”来评价做饭的感受。", "安静": "语义：“安静”指没有声音，与做饭的忙碌无关，句意不通。"}, "sentence_index": 0, "correct_answer": "辛苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很辛苦，我们一起想想办法。", "explanation": "这里应该用〈艰难〉。辛苦形容人付出劳力，问题这类事物要用艰难。"}, {"text": "这里的办学条件很辛苦，但老师们都很乐观。", "explanation": "这里应该用〈艰苦〉。辛苦形容人身心劳累，条件、环境要用艰苦。"}, {"text": "这碗中药很辛苦，我只喝了一口。", "explanation": "这里应该用〈苦〉。辛苦形容人的劳累，说药的味道要用苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辛苦", "is_correct": true, "explanation": "正确：辛苦指做了很多事而很累，与“谢谢你帮我们做了这么多事”的语境相符。"}, {"text": "可怜", "is_correct": false, "explanation": "语义：“可怜”表示同情，与“谢谢”的感激语境相矛盾。"}, {"text": "满意", "is_correct": false, "explanation": "搭配：“满意”多用于结果或服务，不说“做了这么多事，满意了”。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，与“帮我们做事”的亲近关系矛盾。"}], "explanations": {"辛苦": "正确：辛苦指做了很多事而很累，与“谢谢你帮我们做了这么多事”的语境相符。", "可怜": "语义：“可怜”表示同情，与“谢谢”的感激语境相矛盾。", "满意": "搭配：“满意”多用于结果或服务，不说“做了这么多事，满意了”。", "陌生": "语义：“陌生”指不熟悉，与“帮我们做事”的亲近关系矛盾。"}, "sentence_index": 6, "correct_answer": "辛苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很辛苦，我吃了一口就停了。", "explanation": "这里应该用〈辛辣〉。辛苦形容人身心劳累，形容菜的味道要用辛辣。"}, {"text": "这个结局很辛苦，观众都哭了。", "explanation": "这里应该用〈凄惨〉。辛苦形容人身心劳累，描述结局、情节要用凄惨。"}, {"text": "这座小镇显得很辛苦。", "explanation": "这里应该用〈凄凉〉。辛苦形容人的劳累，不用来形容地方的景象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他辛苦了地工作了一整天。", "corrected_sentence": "他辛苦地工作了一整天。", "error_description": "错误在“了”：“了”不能插在修饰动词的“辛苦”之后。应为“他辛苦地工作了一整天。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谢谢你，你太很辛苦了。", "corrected_sentence": "谢谢你，你太辛苦了。", "error_description": "错误在“很”：应为“太辛苦了”。“太”和“很”都是程度副词，不能叠加使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
