INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94582, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身心劳累；劳苦。", "primary_collocate": null, "pronunciation": "xīn kǔ", "ipa": "ɕin˥ kʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "农民种地很辛苦，天天都要早起。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸一年到头在外面打工，非常辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作又累又辛苦，工资却不高。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一个人带孩子，日子过得很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们辛苦地工作了一整年。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走了一天山路，大家都觉得很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当护士很辛苦，晚上还要上班。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了让家人过得好，他一直很辛苦。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么辛苦的事，你为什么还要做？", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶一辈子很辛苦，现在应该休息了。", "target_word": "辛苦", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "辛辛苦苦", "label": "重叠"}, {"form": "辛苦费", "label": "复合"}], "register": "通用", "sense_fingerprint": "辛苦：身心劳累，生活或工作很劳苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辛苦", "is_correct": true, "explanation": "正确：辛苦指身心劳累，与“农民种地很辛苦，天天都要早起”相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人风趣，与种地的劳累状态无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外表或景色，不用来形容劳作的状态。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”多用于物品或工艺，不说“种地很精致”。"}], "explanations": {"辛苦": "正确：辛苦指身心劳累，与“农民种地很辛苦，天天都要早起”相符。", "幽默": "语义：“幽默”形容人风趣，与种地的劳累状态无关。", "漂亮": "语义：“漂亮”形容外表或景色，不用来形容劳作的状态。", "精致": "搭配：“精致”多用于物品或工艺，不说“种地很精致”。"}, "sentence_index": 0, "correct_answer": "辛苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡很辛苦，我喝不下去。", "explanation": "这里应该用〈苦〉。辛苦形容人身心劳累，说咖啡的味道要用苦。"}, {"text": "这份报告的内容很辛苦，我读了半天没读完。", "explanation": "这里应该用〈晦涩〉。辛苦形容人身心劳累，描述文章难懂要用晦涩。"}, {"text": "这里的环境很辛苦，但大家都很乐观。", "explanation": "这里应该用〈艰苦〉。辛苦形容人身心劳累，环境、条件要用艰苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辛苦", "is_correct": true, "explanation": "正确：辛苦指身心劳累，与“当护士很辛苦，晚上还要上班”相符。"}, {"text": "流利", "is_correct": false, "explanation": "搭配：“流利”形容语言或动作的顺畅，不用于形容职业的状态。"}, {"text": "深刻", "is_correct": false, "explanation": "语义：“深刻”形容印象或道理，与“当护士”的工作状态不符。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：“抽象”指不具体，与描述工作的辛劳无关。"}], "explanations": {"辛苦": "正确：辛苦指身心劳累，与“当护士很辛苦，晚上还要上班”相符。", "流利": "搭配：“流利”形容语言或动作的顺畅，不用于形容职业的状态。", "深刻": "语义：“深刻”形容印象或道理，与“当护士”的工作状态不符。", "抽象": "语义：“抽象”指不具体，与描述工作的辛劳无关。"}, "sentence_index": 6, "correct_answer": "辛苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个火锅很辛苦，我吃得满头大汗。", "explanation": "这里应该用〈辣〉。辛苦形容人身心劳累，形容火锅的味道要用辣。"}, {"text": "这部电影的结局很辛苦。", "explanation": "这里应该用〈凄惨〉。辛苦形容人身心劳累，描述结局、情节要用凄惨。"}, {"text": "这座小镇的夜晚很辛苦。", "explanation": "这里应该用〈凄凉〉。辛苦形容人的劳累，不用来形容地方和夜晚的景象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她辛苦苦把三个孩子养大了。", "corrected_sentence": "她辛辛苦苦把三个孩子养大了。", "error_description": "错误在重叠形式：应为“辛辛苦苦”。“辛苦”的重叠是“辛辛苦苦”，“辛苦苦”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作很辛苦过。", "corrected_sentence": "这份工作很辛苦。", "error_description": "错误在“过”：“很＋形容词”描写状态，后面不能加“过”。应为“这份工作很辛苦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
