INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94583, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钢铁是又硬又重的一种金属。", "primary_collocate": null, "pronunciation": "gāng tiě", "ipa": "kɑŋ˥ tʰie˨˩", "syllable_count": 2, "sentences": [{"text": "钢铁又硬又重，很难弯曲。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是用钢铁造的。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把钢铁运到了工厂。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢铁遇到高温会变软。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的外壳是钢铁做的。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摸了摸冰冷的钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢铁在水里放久了会生锈。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门是钢铁的，很重。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一块钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要很多钢铁来建大楼。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鋼鐵", "label": "繁体"}, {"form": "钢铁厂", "label": "复合词"}], "register": "中性", "sense_fingerprint": "作为硬而重的金属本身的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢铁", "is_correct": true, "explanation": "正确。“钢铁”是又硬又重的金属，句意符合。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花又软又轻，不可能又硬又重，也不会难以弯曲。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“硬”“重”多用来形容物体，不说“声音又硬又重”。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫轻软，不可能又硬又重。"}], "explanations": {"钢铁": "正确。“钢铁”是又硬又重的金属，句意符合。", "棉花": "语义：棉花又软又轻，不可能又硬又重，也不会难以弯曲。", "声音": "搭配：“硬”“重”多用来形容物体，不说“声音又硬又重”。", "泡沫": "语义：泡沫轻软，不可能又硬又重。"}, "sentence_index": 0, "correct_answer": "钢铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人从山里挖出了钢铁。", "explanation": "这里应该用〈铁矿〉。钢铁是加工后的金属，从山里挖出的是未加工的铁矿。"}, {"text": "铜是一种导电的钢铁。", "explanation": "这里应该用〈金属〉。钢铁特指铁和钢，铜不是钢铁，不能这样用。"}, {"text": "这碗面条是用钢铁做的。", "explanation": "这里应该用〈面粉〉。面条要用面粉做，钢铁又硬又重，不能用来做食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢铁", "is_correct": true, "explanation": "正确。钢铁是金属，放在水里久了会生锈，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不会生锈。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“生锈”是金属的变化，不能说“气味生锈”。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是非金属材料，不会生锈。"}], "explanations": {"钢铁": "正确。钢铁是金属，放在水里久了会生锈，符合句意。", "石头": "语义：石头是矿物，不会生锈。", "气味": "搭配：“生锈”是金属的变化，不能说“气味生锈”。", "玻璃": "语义：玻璃是非金属材料，不会生锈。"}, "sentence_index": 6, "correct_answer": "钢铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用钢铁来煮汤。", "explanation": "这里应该用〈水〉。煮汤要用水和食材，钢铁是金属，不能用来煮汤。"}, {"text": "这件衣服是用钢铁做的。", "explanation": "这里应该用〈布料〉。衣服要轻软，钢铁又硬又重，不能用来做衣服。"}, {"text": "我们需要很多钢铁来做糖果。", "explanation": "这里应该用〈糖〉。糖是做糖果的原料，钢铁是金属，不能用来做糖果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只钢铁很结实。", "corrected_sentence": "这块钢铁很结实。", "error_description": "量词错误：钢铁是物质，应该用量词“块”，“只”不能用于钢铁。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "建这座桥用了很多个钢铁。", "corrected_sentence": "建这座桥用了很多钢铁。", "error_description": "量词错误：钢铁是物质名词，不能用“个”来数，直接说“很多钢铁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
