INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "铁和钢的合称，是一种坚硬的金属材料。", "primary_collocate": null, "pronunciation": "gāng tiě", "ipa": "kɑŋ˥ tʰie˨˩", "syllable_count": 2, "sentences": [{"text": "铁和钢合起来叫钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国生产了很多钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在造房子要用大量钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年生产一百万吨钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢铁是现代建筑的重要材料。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢铁价格最近涨了不少。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家出口钢铁到很多地方。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回收旧钢铁可以节约资源。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路的铁轨是用钢铁做的。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了造船，他们买了不少钢铁。", "target_word": "钢铁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鋼鐵", "label": "繁体"}, {"form": "钢铁厂", "label": "复合词"}], "register": "中性", "sense_fingerprint": "铁和钢的合称，作为工业材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢铁", "is_correct": true, "explanation": "正确。“钢铁”就是铁和钢的合称，句意正确。"}, {"text": "生铁", "is_correct": false, "explanation": "语义：生铁是另一种含碳较多的铁，不是铁和钢的合称。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材是树木加工成的材料，不是金属，与“铁和钢”无关。"}, {"text": "铁疙瘩", "is_correct": false, "explanation": "语域：“铁疙瘩”是口语说法，指笨重的铁块，不是正式的合称。"}], "explanations": {"钢铁": "正确。“钢铁”就是铁和钢的合称，句意正确。", "生铁": "语义：生铁是另一种含碳较多的铁，不是铁和钢的合称。", "木材": "语义：木材是树木加工成的材料，不是金属，与“铁和钢”无关。", "铁疙瘩": "语域：“铁疙瘩”是口语说法，指笨重的铁块，不是正式的合称。"}, "sentence_index": 0, "correct_answer": "钢铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铝是一种轻的钢铁。", "explanation": "这里应该用〈金属〉。钢铁特指铁和钢，铝不是铁和钢，不能称为钢铁。"}, {"text": "这家餐馆的菜里放了很多钢铁。", "explanation": "这里应该用〈调料〉。钢铁是工业材料，不能放进菜里当调料。"}, {"text": "这件外套是用钢铁做的，穿着很暖和。", "explanation": "这里应该用〈羊毛〉。外套要保暖轻软，钢铁又硬又重，不能用来做外套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢铁", "is_correct": true, "explanation": "正确。“出口”的货物可以是钢铁，符合句意。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能被出口。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“出口”的对象是货物，不说“出口感情”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以出口的东西。"}], "explanations": {"钢铁": "正确。“出口”的货物可以是钢铁，符合句意。", "地震": "语义：地震是自然灾害，不能被出口。", "感情": "搭配：“出口”的对象是货物，不说“出口感情”。", "感冒": "语义：感冒是一种疾病，不是可以出口的东西。"}, "sentence_index": 6, "correct_answer": "钢铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座矿山挖出了很多钢铁。", "explanation": "这里应该用〈铁矿石〉。钢铁是加工后的金属，矿山里挖出的是未加工的铁矿石。"}, {"text": "这件衬衫是用钢铁做的。", "explanation": "这里应该用〈棉布〉。衬衫要轻软，钢铁又硬又重，不能用来做衬衫。"}, {"text": "我每天早上都喝一杯钢铁。", "explanation": "这里应该用〈牛奶〉。钢铁是金属材料，不能当饮料喝，早上喝的饮料要用牛奶之类的食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座工厂一天能生产几百个钢铁。", "corrected_sentence": "这座工厂一天能生产几百吨钢铁。", "error_description": "量词错误：钢铁按重量计算，应该用量词“吨”，“个”不能用于钢铁。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们为了造船买了三只钢铁。", "corrected_sentence": "他们为了造船买了三吨钢铁。", "error_description": "量词错误：钢铁按重量计算，应该用量词“吨”，“只”不能用于钢铁。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "反义：“集合”指聚到一起，“分散”指散开，二者意思相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞与“集合”之间没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书与“集合”之间没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“集合”之间没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "反义：“集合”指聚到一起，“分散”指散开，二者意思相反。", "跳舞": "跳舞与“集合”之间没有反义关系。", "读书": "读书与“集合”之间没有反义关系。", "跑步": "跑步与“集合”之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
