INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "饲养和繁殖水生或陆生的动植物。", "primary_collocate": null, "pronunciation": "yǎng zhí", "ipa": "jaŋ²¹⁴ ʈʂɻ̩³⁵", "syllable_count": 2, "sentences": [{"text": "他在海边养殖大虾。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子养殖了很多鱼。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家人在山里养殖牛和羊。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养殖鱼需要干净的水。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想在这里养殖珍珠。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后开始养殖蜜蜂。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太脏，不能养殖海带。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把湖水引到池子里养殖螃蟹。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门养殖黑猪。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟哥哥一起养殖了两百只鸡。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "养殖业", "label": "复合"}, {"form": "养殖场", "label": "复合"}, {"form": "养殖了", "label": "体标"}], "register": "中性", "sense_fingerprint": "饲养并繁殖水产、家禽、牲畜等动植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1426ce4-1f9f-4599-b218-e53fd9592105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "养殖", "is_correct": true, "explanation": "正确。养殖指饲养水产等动物，“在海边养殖大虾”合理。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译的对象是语言或文字，不能用于大虾。"}, {"text": "弹奏", "is_correct": false, "explanation": "搭配：弹奏的对象是乐器，不能说弹奏大虾。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫的对象是场所或物品，不能说打扫大虾。"}], "explanations": {"养殖": "正确。养殖指饲养水产等动物，“在海边养殖大虾”合理。", "翻译": "语义：翻译的对象是语言或文字，不能用于大虾。", "弹奏": "搭配：弹奏的对象是乐器，不能说弹奏大虾。", "打扫": "搭配：打扫的对象是场所或物品，不能说打扫大虾。"}, "sentence_index": 0, "correct_answer": "养殖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家在院子里养殖了一只猫。", "explanation": "这里应该用〈养〉。养殖多指成批饲养水产、家禽、牲畜，家里养一只宠物猫要说“养”。"}, {"text": "他们很快养殖了深厚的感情。", "explanation": "这里应该用〈培养〉。养殖针对动植物，感情要用培养。"}, {"text": "他们养殖了三个孩子，照顾得很好。", "explanation": "这里应该用〈抚养〉。养殖只用于动植物，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "养殖", "is_correct": true, "explanation": "正确。养殖可以用于海带这类水生植物，“不能养殖海带”指水太脏的情况。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：演奏的对象是乐曲，不能说演奏海带。"}, {"text": "阅读", "is_correct": false, "explanation": "语义：阅读的对象是文字，海带不能被阅读。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不能说唱海带。"}], "explanations": {"养殖": "正确。养殖可以用于海带这类水生植物，“不能养殖海带”指水太脏的情况。", "演奏": "搭配：演奏的对象是乐曲，不能说演奏海带。", "阅读": "语义：阅读的对象是文字，海带不能被阅读。", "唱": "搭配：唱的对象是歌曲，不能说唱海带。"}, "sentence_index": 6, "correct_answer": "养殖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养殖了一家小餐馆，生意很好。", "explanation": "这里应该用〈经营〉。养殖的对象是动植物，餐馆要用经营。"}, {"text": "她跟哥哥一起养殖了两百个笑话。", "explanation": "这里应该用〈讲〉。养殖的对象是动植物，笑话要用讲。"}, {"text": "农民养殖了一批新稻种。", "explanation": "这里应该用〈培育〉。养殖多指动物，培育新品种要用培育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在池塘里养殖着了很多罗非鱼。", "corrected_sentence": "他们在池塘里养殖了很多罗非鱼。", "error_description": "体标错误：“着”和“了”不能同时用在“养殖”后面，应说“养殖了很多罗非鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他们养殖鱼。", "corrected_sentence": "这是他们养殖的鱼。", "error_description": "语法错误：“这是”后应接名词性成分，动词短语“养殖鱼”需加“的”组成名词短语，应说“这是他们养殖的鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
