INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "马年是十二个属相里，属马的那一年。", "primary_collocate": null, "pronunciation": "mǎ nián", "ipa": "ma˨˩˦ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今年是马年，我属马。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年到了，大家都说新年快乐。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我出生在马年，所以属马。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一个马年是哪一年？", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，他和我都是在马年出生的。", "target_word": "马年", "complexity_tier": "T3", "furigana": "bà ba shuō tā hé wǒ dōu shì zài mǎ nián chū shēng de", "sentence_source": "generated"}, {"text": "马年的春节，家家都挂着马的画。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说她是马年生的。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年出生的人都属马。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二年才有一个马年。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的生日在马年的夏天。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "馬年", "label": "繁体"}], "register": "中性", "sense_fingerprint": "十二属相中属马的那一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7730a907-17d6-4070-8ade-01789c2b16ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "马年", "is_correct": true, "explanation": "“马年”指属马的那一年，与后半句“我属马”相符。"}, {"text": "猴年", "is_correct": false, "explanation": "语义：猴年是属猴的年份，与“我属马”矛盾。"}, {"text": "春节", "is_correct": false, "explanation": "搭配：“是……年”后接的是年份名称，春节是节日，不能用来指年份。"}, {"text": "鼠年", "is_correct": false, "explanation": "语义：鼠年是属鼠的年份，与“我属马”矛盾。"}], "explanations": {"马年": "“马年”指属马的那一年，与后半句“我属马”相符。", "猴年": "语义：猴年是属猴的年份，与“我属马”矛盾。", "春节": "搭配：“是……年”后接的是年份名称，春节是节日，不能用来指年份。", "鼠年": "语义：鼠年是属鼠的年份，与“我属马”矛盾。"}, "sentence_index": 0, "correct_answer": "马年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "十二年里只有一只马年。", "explanation": "这里应该用〈个〉。“只”多用于动物、物品，“马年”是年份，量词要用“个”。"}, {"text": "我是马年，出生在夏天。", "explanation": "这里应该用〈属马〉。说人的生肖要用“属马”，“马年”指年份，不能说“我是马年”。"}, {"text": "我骑着马年在草原上跑。", "explanation": "这里应该用〈骏马〉。“骑”的对象要是动物“马”，“马年”指年份，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "马年", "is_correct": true, "explanation": "“马年”指年份，放在“生的”前表示出生的年份，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：人不能是石头生的，与“奶奶说她是……生的”矛盾。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“……生的”要接表示时间的词，地铁不是时间，不能这样搭配。"}, {"text": "世纪", "is_correct": false, "explanation": "搭配：世纪是很长的时间段，不能指一个具体的出生时间。"}], "explanations": {"马年": "“马年”指年份，放在“生的”前表示出生的年份，与句意相符。", "石头": "语义：人不能是石头生的，与“奶奶说她是……生的”矛盾。", "地铁": "搭配：“……生的”要接表示时间的词，地铁不是时间，不能这样搭配。", "世纪": "搭配：世纪是很长的时间段，不能指一个具体的出生时间。"}, "sentence_index": 6, "correct_answer": "马年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟的属相是马年。", "explanation": "这里应该用〈马〉。“属相”后接动物名，“马年”是年份，不能作属相。"}, {"text": "弟弟的马年在夏天。", "explanation": "这里应该用〈生日〉。“生日”指出生的日子，“马年”指年份，不能代替生日。"}, {"text": "马年是新年的第一天。", "explanation": "这里应该用〈元旦〉。“马年”指一整年，不能指新年的第一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只马年我们全家要去旅行。", "corrected_sentence": "这个马年我们全家要去旅行。", "error_description": "量词错误：“马年”是年份，量词应用“个”，不能用“只”（“只”多用于动物、物品）。错误形式「这只马年」，正确形式「这个马年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有好几个马年出生同学。", "corrected_sentence": "我们班有好几个马年出生的同学。", "error_description": "错误：“马年出生同学”；正确：“马年出生的同学”。动词短语修饰名词时，中间须加结构助词“的”，不能直接相连。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
