INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "农历生肖为马的年份。", "primary_collocate": null, "pronunciation": "mǎ nián", "ipa": "ma˨˩˦ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "农历马年就要到了。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年春节，商店里全是马的玩具。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年的春节，街上很热闹。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年快到了，街上都是红灯笼。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们全家在马年春节回老家过年。", "target_word": "马年", "complexity_tier": "T3", "furigana": "wǒ men quán jiā zài mǎ nián chūn jié huí lǎo jiā guò nián", "sentence_source": "generated"}, {"text": "每到马年，就有很多人买马的画。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年过去以后，就是羊年。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一个马年，我才十二岁。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在上一个马年出生。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年是蛇年，今年是马年。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "馬年", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农历中生肖是马的年份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7730a907-17d6-4070-8ade-01789c2b16ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "马年", "is_correct": true, "explanation": "“马年”指农历生肖为马的年份，与“农历”相符，也能与“就要到了”搭配。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”不是时间，不能说“就要到了”。"}, {"text": "公历年", "is_correct": false, "explanation": "搭配：“公历”与前面的“农历”互相矛盾，不能同时修饰这里的年份。"}, {"text": "去年", "is_correct": false, "explanation": "语义：去年已经过去，与“就要到了”的意思矛盾。"}], "explanations": {"马年": "“马年”指农历生肖为马的年份，与“农历”相符，也能与“就要到了”搭配。", "蛋糕": "语义：“蛋糕”不是时间，不能说“就要到了”。", "公历年": "搭配：“公历”与前面的“农历”互相矛盾，不能同时修饰这里的年份。", "去年": "语义：去年已经过去，与“就要到了”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "马年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座马年是最热闹的一年。", "explanation": "这里应该用〈个〉。“座”多用于山、房屋等，“马年”是年份，量词要用“个”。"}, {"text": "我的属相是马年。", "explanation": "这里应该用〈马〉。“属相”后接动物名“马”，“马年”指年份，不能作属相。"}, {"text": "他的爸爸是马年，爱喝茶。", "explanation": "这里应该用〈属马〉。说人的生肖要用“属马”，“马年”指年份，不能说“他是马年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "马年", "is_correct": true, "explanation": "“马年”是年份，放在“过去以后，就是羊年”的前面，与句意相符。"}, {"text": "猴年", "is_correct": false, "explanation": "语义：猴年之后是鸡年，不是羊年，与“就是羊年”矛盾。"}, {"text": "生肖", "is_correct": false, "explanation": "搭配：“过去以后”后接的是时间，“生肖”不是时间，不能这样搭配。"}, {"text": "狗年", "is_correct": false, "explanation": "语义：狗年之后是猪年，不是羊年，与“就是羊年”矛盾。"}], "explanations": {"马年": "“马年”是年份，放在“过去以后，就是羊年”的前面，与句意相符。", "猴年": "语义：猴年之后是鸡年，不是羊年，与“就是羊年”矛盾。", "生肖": "搭配：“过去以后”后接的是时间，“生肖”不是时间，不能这样搭配。", "狗年": "语义：狗年之后是猪年，不是羊年，与“就是羊年”矛盾。"}, "sentence_index": 6, "correct_answer": "马年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去草原上看马年。", "explanation": "这里应该用〈骏马〉。草原上看的是动物“马”，“马年”指年份，不能用来指动物。"}, {"text": "马年是中国最重要的节日。", "explanation": "这里应该用〈春节〉。“马年”指年份，不能当作节日名称。"}, {"text": "马年是一年的第一天。", "explanation": "这里应该用〈元旦〉。“马年”指一整年，不能指一年中的某一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下一只马年，我们全家要去看海。", "corrected_sentence": "下一个马年，我们全家要去看海。", "error_description": "量词错误：“马年”是年份，量词应用“个”，不能用“只”。错误形式「下一只马年」，正确形式「下一个马年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年是一只马年，后年是羊年。", "corrected_sentence": "明年是一个马年，后年是羊年。", "error_description": "量词错误：“马年”是年份，量词应用“个”，不能用“只”。错误形式「一只马年」，正确形式「一个马年」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
