INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94593, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "予以是给，是给出去的意思。", "primary_collocate": null, "pronunciation": "yǔ yǐ", "ipa": "y˨˩˦ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校对他予以奖励。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司对这个办法予以支持。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师对她的进步予以表扬。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校对他的研究予以认可。", "target_word": "予以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对农民予以帮助。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请对新来的同学予以照顾。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对于好成绩，学校会予以奖励。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们对你的想法予以鼓励。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行对小公司予以支持。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "领导对大家的工作予以肯定。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "给出（奖励、支持、帮助等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以（yǔ yǐ）：给予，正确答案。"}, {"text": "语义", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是语义，与“给予”无关。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，意思是雨衣。"}, {"text": "雨意", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的迹象。"}, {"text": "羽翼", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是羽毛和翅膀。"}], "explanations": {"予以": "予以（yǔ yǐ）：给予，正确答案。", "语义": "yì（第四声）与 yǐ（第三声）声调不同，意思是语义，与“给予”无关。", "雨衣": "yī（第一声）与 yǐ（第三声）声调不同，意思是雨衣。", "雨意": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的迹象。", "羽翼": "yì（第四声）与 yǐ（第三声）声调不同，意思是羽毛和翅膀。"}, "sentence_index": null, "correct_answer": "予以"}, "level_3": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以：给予，对他给出奖励，符合句意。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”与“奖励”意思相反，不能用于同一件好事。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是错误或行为，不能与“奖励”搭配。"}, {"text": "谴责", "is_correct": false, "explanation": "语义：“谴责”是严厉指责，与“奖励”的褒奖义相反。"}], "explanations": {"予以": "予以：给予，对他给出奖励，符合句意。", "惩罚": "语义：“惩罚”与“奖励”意思相反，不能用于同一件好事。", "批评": "搭配：“批评”的对象是错误或行为，不能与“奖励”搭配。", "谴责": "语义：“谴责”是严厉指责，与“奖励”的褒奖义相反。"}, "sentence_index": 0, "correct_answer": "予以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他予以我一个微笑。", "explanation": "这里应该用〈给〉。予以用于抽象的奖励或支持，微笑这种动作不能用予以，应说给。"}, {"text": "老师予以她一朵小红花。", "explanation": "这里应该用〈给〉。予以用于抽象的奖励或支持，不直接带人作间接宾语，送具体的小红花应说给。"}, {"text": "妈妈予以他一本书。", "explanation": "这里应该用〈送〉。予以指给出抽象的奖励或支持，不用于书这类具体物品，应说送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94593, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以（yǔ yǐ）：给予，正确答案。"}, {"text": "辅以", "is_correct": false, "explanation": "fǔ 与 yǔ 声母不同，意思是辅助、补充。"}, {"text": "雨意", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的意思。"}, {"text": "羽衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，意思是羽毛做的衣服。"}], "explanations": {"予以": "予以（yǔ yǐ）：给予，正确答案。", "辅以": "fǔ 与 yǔ 声母不同，意思是辅助、补充。", "雨意": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的意思。", "羽衣": "yī（第一声）与 yǐ（第三声）声调不同，意思是羽毛做的衣服。"}, "sentence_index": null, "correct_answer": "予以"}, "level_3": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以：给予，对好成绩给出奖励，符合句意。"}, {"text": "责备", "is_correct": false, "explanation": "语义：“责备”是指出过错，与“好成绩”的褒奖相矛盾。"}, {"text": "训斥", "is_correct": false, "explanation": "搭配：“训斥”的对象是人或过失，不能与“奖励”搭配。"}, {"text": "查处", "is_correct": false, "explanation": "语义：“查处”针对违规行为，与“好成绩”不相符。"}], "explanations": {"予以": "予以：给予，对好成绩给出奖励，符合句意。", "责备": "语义：“责备”是指出过错，与“好成绩”的褒奖相矛盾。", "训斥": "搭配：“训斥”的对象是人或过失，不能与“奖励”搭配。", "查处": "语义：“查处”针对违规行为，与“好成绩”不相符。"}, "sentence_index": 6, "correct_answer": "予以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府予以他一张证书。", "explanation": "这里应该用〈颁发〉。予以用于抽象的奖励或支持，证书是具体的物品，应说颁发。"}, {"text": "图书馆予以我们一批资料。", "explanation": "这里应该用〈提供〉。予以不用于资料这类具体物品，应说提供。"}, {"text": "他予以我一把钥匙。", "explanation": "这里应该用〈交给〉。予以不用于钥匙这类具体物品，应说交给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id