INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给以，加以（多接双音节动词）。", "primary_collocate": null, "pronunciation": "yǔ yǐ", "ipa": "y˨˩˦ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司对这件事予以处理。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校对错误予以纠正。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理对我的请假予以批准。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不好的行为要予以批评。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结果明天予以公布。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师对这个问题予以解释。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们会对你的意见予以考虑。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府对违法行为予以处罚。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长对此事予以重视。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院对这个案子予以审理。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "后接双音节动词，表示对某事加以处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以（yǔ yǐ）：加以，正确答案。"}, {"text": "语义", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是语义。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，意思是雨衣。"}, {"text": "许以", "is_correct": false, "explanation": "xǔ 与 yǔ 声母不同，意思是许诺、答应。"}, {"text": "羽翼", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是羽毛和翅膀。"}], "explanations": {"予以": "予以（yǔ yǐ）：加以，正确答案。", "语义": "yì（第四声）与 yǐ（第三声）声调不同，意思是语义。", "雨衣": "yī（第一声）与 yǐ（第三声）声调不同，意思是雨衣。", "许以": "xǔ 与 yǔ 声母不同，意思是许诺、答应。", "羽翼": "yì（第四声）与 yǐ（第三声）声调不同，意思是羽毛和翅膀。"}, "sentence_index": null, "correct_answer": "予以"}, "level_3": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以：加以，对这件事进行处理，符合句意。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指感到快乐或得到好处，不能用来表示对事件的处理。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”的宾语应是物或能力，不能说拥有“处理”。"}, {"text": "忍受", "is_correct": false, "explanation": "语义：“忍受”指承受痛苦，与“处理”的行为义不符。"}], "explanations": {"予以": "予以：加以，对这件事进行处理，符合句意。", "享受": "语义：“享受”指感到快乐或得到好处，不能用来表示对事件的处理。", "拥有": "搭配：“拥有”的宾语应是物或能力，不能说拥有“处理”。", "忍受": "语义：“忍受”指承受痛苦，与“处理”的行为义不符。"}, "sentence_index": 0, "correct_answer": "予以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们予以看这份报告。", "explanation": "这里应该用〈审阅〉。予以后面要接双音节动词，单音节的“看”不能跟在“予以”后面，应说“予以审阅”。"}, {"text": "老师予以听学生的意见。", "explanation": "这里应该用〈听取〉。予以后面要接双音节动词，单音节的“听”不能用于“予以”之后，应说“予以听取”。"}, {"text": "公司对这个计划予以改。", "explanation": "这里应该用〈修改〉。“予以”后面要接双音节动词，单音节的“改”不能跟在“予以”后面，应说“予以修改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以（yǔ yǐ）：加以，正确答案。"}, {"text": "许以", "is_correct": false, "explanation": "xǔ 与 yǔ 声母不同，意思是许诺、答应。"}, {"text": "雨意", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的意思。"}, {"text": "羽衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，意思是羽毛做的衣服。"}], "explanations": {"予以": "予以（yǔ yǐ）：加以，正确答案。", "许以": "xǔ 与 yǔ 声母不同，意思是许诺、答应。", "雨意": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的意思。", "羽衣": "yī（第一声）与 yǐ（第三声）声调不同，意思是羽毛做的衣服。"}, "sentence_index": null, "correct_answer": "予以"}, "level_3": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以：加以，对意见加以考虑，符合句意。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归属关系，后面接名词，不能接动作“考虑”。"}, {"text": "来自", "is_correct": false, "explanation": "语义：“来自”表示来源，后面接地点或人，不能说“来自考虑”。"}, {"text": "等于", "is_correct": false, "explanation": "语义：“等于”表示相等，不能与“对……考虑”搭配。"}], "explanations": {"予以": "予以：加以，对意见加以考虑，符合句意。", "属于": "语义：“属于”表示归属关系，后面接名词，不能接动作“考虑”。", "来自": "语义：“来自”表示来源，后面接地点或人，不能说“来自考虑”。", "等于": "语义：“等于”表示相等，不能与“对……考虑”搭配。"}, "sentence_index": 6, "correct_answer": "予以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友予以我一杯水。", "explanation": "这里应该用〈给〉。“予以”用于正式场合，后接双音节动词或抽象事物（如支持、奖励），不用于“一杯水”这类日常具体物品。"}, {"text": "妈妈予以孩子一个拥抱。", "explanation": "这里应该用〈给〉。予以后面接的是双音节动词或抽象的奖励、支持，“拥抱”这样的具体动作不能用予以。"}, {"text": "公司予以员工一个礼物。", "explanation": "这里应该用〈送〉。予以不用于礼物这类具体物品，应说送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
