INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "侵略是坏人带着兵走进别人的国家，抢别人的地方。", "primary_collocate": null, "pronunciation": "qīn lüè", "ipa": "tɕʰin˥ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "很多年前，坏人带着兵侵略了我们的国家。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国王想侵略邻居的国家。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的人都怕别的国家来侵略他们的国家。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们带着很多兵，去侵略别人的土地。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了坏国王侵略小国的故事。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为什么要侵略别人的国家？", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家带着兵侵略别人，抢走了他们的土地。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不喜欢侵略别国的行为。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别的国家来侵略我们，我们要保护家人。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家又来侵略我们的边境了，大家很害怕。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵略了", "label": "体标"}, {"form": "侵略过", "label": "体标"}, {"form": "侵略者", "label": "复合"}, {"form": "侵略战争", "label": "复合"}], "register": "书面语", "sense_fingerprint": "侵略：坏人或坏国王带兵进入别人的国家和土地，抢走别人的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd836b5-fdf8-41b4-a611-31fbc44b07d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：用武力入侵别国，符合“坏人带着兵”的语境。"}, {"text": "保护", "is_correct": false, "explanation": "语义：坏人带兵不会去保护国家，“保护”与“坏人带着兵”矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，不能带“我们的国家”作宾语。"}, {"text": "建设", "is_correct": false, "explanation": "语义：坏人带兵去建设国家与语境矛盾，建设需要的是建设者而不是士兵。"}], "explanations": {"侵略": "侵略：用武力入侵别国，符合“坏人带着兵”的语境。", "保护": "语义：坏人带兵不会去保护国家，“保护”与“坏人带着兵”矛盾。", "出生": "配价：“出生”是不及物动词，不能带“我们的国家”作宾语。", "建设": "语义：坏人带兵去建设国家与语境矛盾，建设需要的是建设者而不是士兵。"}, "sentence_index": 0, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他侵略了我的隐私。", "explanation": "这里应该用〈侵犯〉。侵略只用于国家之间的武力入侵，隐私、权利要用侵犯。"}, {"text": "那个会计侵略了公司的钱。", "explanation": "这里应该用〈侵占〉。侵占用于钱财、财物，侵略只用于国家和领土。"}, {"text": "大哥总是侵略弟弟。", "explanation": "这里应该用〈欺负〉。侵略指国家间的武力入侵，不用于一般的人际冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：用武力入侵别国、抢占土地，与句中“带着兵”和“抢走了土地”相符。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”的对象是建筑或工程，不能说“建造别人”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：带兵抢走别人的土地，不会去“感谢”别人，与语境矛盾。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，不能带“别人”作宾语。"}], "explanations": {"侵略": "侵略：用武力入侵别国、抢占土地，与句中“带着兵”和“抢走了土地”相符。", "建造": "搭配：“建造”的对象是建筑或工程，不能说“建造别人”。", "感谢": "语义：带兵抢走别人的土地，不会去“感谢”别人，与语境矛盾。", "诞生": "配价：“诞生”是不及物动词，不能带“别人”作宾语。"}, "sentence_index": 6, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "强盗侵略了那家银行。", "explanation": "这里应该用〈抢劫〉。侵略指国家用武力侵犯别国领土，强盗抢银行要用抢劫。"}, {"text": "邻居经常侵略我们。", "explanation": "这里应该用〈骚扰〉。侵略只用于国家之间，邻居之间的骚扰不说侵略。"}, {"text": "地主经常侵略农民。", "explanation": "这里应该用〈欺压〉。侵略用于国家之间的武力入侵，地主对农民要用欺压。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家历史上侵略了过邻国。", "corrected_sentence": "这个国家历史上侵略过邻国。", "error_description": "体标错误：“了”和“过”不能同时用在动词后面，应说“侵略过”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个国家从没被侵略过别人。", "corrected_sentence": "那个国家从没侵略过别人。", "error_description": "被字句错误：“侵略”后面已经带了宾语“别人”，不能再加“被”。正确的说法是“那个国家从没侵略过别人”，不说“从没被侵略过别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防御", "is_correct": true, "explanation": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。"}, {"text": "建设", "is_correct": false, "explanation": "建设：指创建、修建，与“侵略”不构成反义关系。"}, {"text": "访问", "is_correct": false, "explanation": "访问：指到某处去看望或了解情况，与“侵略”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指到外地游览，与“侵略”没有反义关系。"}], "correct_answer": "防御", "explanations": {"防御": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。", "建设": "建设：指创建、修建，与“侵略”不构成反义关系。", "访问": "访问：指到某处去看望或了解情况，与“侵略”没有反义关系。", "旅行": "旅行：指到外地游览，与“侵略”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
