INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武力侵犯别国的领土和主权。", "primary_collocate": null, "pronunciation": "qīn lüè", "ipa": "tɕʰin˥ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家用武力侵略邻国的领土。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国反对任何国家侵略别国。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "侵略别国的领土是不对的。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写了他们怎么用武力侵略邻国。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的军队侵略了边境上的小城。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队越过边界，开始侵略邻国。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家一起反对侵略别国的行为。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家想用武力侵略我们的土地。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻说那个国家又开始侵略邻国了。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，用武力侵略别国是错的。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵略了", "label": "体标"}, {"form": "侵略过", "label": "体标"}, {"form": "侵略者", "label": "复合"}, {"form": "侵略战争", "label": "复合"}], "register": "书面语", "sense_fingerprint": "侵略：一国用武力侵犯别国的领土和主权，多见于历史、新闻和政治语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd836b5-fdf8-41b4-a611-31fbc44b07d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：用武力侵犯别国领土，与“用武力”的语境相符。"}, {"text": "交换", "is_correct": false, "explanation": "语义：“用武力”不能用来“交换”领土，两者矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“邻国的领土”作宾语。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”的对象是建筑或工程，不说“建造邻国的领土”。"}], "explanations": {"侵略": "侵略：用武力侵犯别国领土，与“用武力”的语境相符。", "交换": "语义：“用武力”不能用来“交换”领土，两者矛盾。", "游泳": "配价：“游泳”是不及物动词，不能带“邻国的领土”作宾语。", "建造": "搭配：“建造”的对象是建筑或工程，不说“建造邻国的领土”。"}, "sentence_index": 0, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小偷侵略了我的钱包。", "explanation": "这里应该用〈偷〉。侵略指国家用武力侵犯别国领土，小偷拿走钱包要用偷。"}, {"text": "他总是侵略妹妹的零食。", "explanation": "这里应该用〈抢〉。侵略只用于国家的武力侵犯，抢零食不说侵略。"}, {"text": "他侵略了别人的名誉。", "explanation": "这里应该用〈损害〉。侵略针对的是领土和主权，名誉要用损害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：入侵别国，与“反对……的行为”的对象相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“别国”作宾语。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”用于会议、比赛等活动，不能说“举行别国”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“别国”作宾语。"}], "explanations": {"侵略": "侵略：入侵别国，与“反对……的行为”的对象相符。", "睡觉": "配价：“睡觉”是不及物动词，不能带“别国”作宾语。", "举行": "搭配：“举行”用于会议、比赛等活动，不能说“举行别国”。", "散步": "配价：“散步”是不及物动词，不能带“别国”作宾语。"}, "sentence_index": 6, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他侵略了公司的钱。", "explanation": "这里应该用〈侵吞〉。侵略指国家武力入侵，非法占有公司财物要用侵吞。"}, {"text": "同学们在食堂里侵略了别人的位子。", "explanation": "这里应该用〈霸占〉。霸占用于占据别人的位子、房间等，侵略用于国家领土。"}, {"text": "老板侵略了员工的休息时间。", "explanation": "这里应该用〈占用〉。侵略的对象是领土和主权，时间要用占用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用武力的侵略了别国的领土。", "corrected_sentence": "他们用武力侵略了别国的领土。", "error_description": "结构助词错误：“用武力”作状语修饰动词，后面不加“的”。应说“用武力侵略了别国的领土”，不说“用武力的侵略了别国的领土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小国邻国侵略了。", "corrected_sentence": "这个小国被邻国侵略了。", "error_description": "被字句漏字：有施事“邻国”时要用“被”，应说“这个小国被邻国侵略了”，不说“这个小国邻国侵略了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出道是第一次出来做事，开始被大家知道。", "primary_collocate": null, "pronunciation": "chū dào", "ipa": "ʈʂʰu˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他刚出道，对这行的事还不太懂。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥出道很早，二十岁就当了老板。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个年轻人出道不久，已经有了名气。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，出道以后要多学习。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出道那年，才十九岁。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时出道，大家都叫他小李师傅。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚出道的人，工作经验少。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出道后很努力，大家都知道她的名字。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想出道，先得练好本领。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位厨师出道多年，现在有自己的饭店。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出道了", "label": "体标"}], "register": "中性", "sense_fingerprint": "年轻人第一次走上社会做事，开始有人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出道", "is_correct": true, "explanation": "出道：第一次走上社会做事，符合“他刚……，对这行的事还不太懂”的语境。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休后就不再从事这行，与“对这行的事还不太懂”矛盾。"}, {"text": "退役", "is_correct": false, "explanation": "搭配：退役多指军人或运动员，一般行业的人不说退役。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指降生，与“对这行的事还不太懂”的语境不搭。"}], "explanations": {"出道": "出道：第一次走上社会做事，符合“他刚……，对这行的事还不太懂”的语境。", "退休": "语义：退休后就不再从事这行，与“对这行的事还不太懂”矛盾。", "退役": "搭配：退役多指军人或运动员，一般行业的人不说退役。", "出生": "语义：出生指降生，与“对这行的事还不太懂”的语境不搭。"}, "sentence_index": 0, "correct_answer": "出道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天出道，去超市买菜。", "explanation": "这里应该用〈出门〉。出道指第一次出来做事并开始被大家知道，去超市买菜只是日常外出，要说出门。"}, {"text": "我明年出道，去学校报到。", "explanation": "这里应该用〈入学〉。出道指第一次出来做事，去学校报到是入学，不能说出道。"}, {"text": "他下周出道，坐飞机去美国读书。", "explanation": "这里应该用〈出国〉。出道指第一次出来做事并开始被大家知道，去国外读书要说出国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出道", "is_correct": true, "explanation": "出道：开始在行业中公开活动，符合“刚……的人，工作经验少”的语境。"}, {"text": "退隐", "is_correct": false, "explanation": "语义：退隐指离开公众生活，通常以长期经历为前提，与“工作经验少”相矛盾。"}, {"text": "退位", "is_correct": false, "explanation": "搭配：退位指君主让出王位，不用于普通的人。"}, {"text": "退场", "is_correct": false, "explanation": "语义：退场指离开舞台，表示工作已经结束，与“工作经验少”不符。"}], "explanations": {"出道": "出道：开始在行业中公开活动，符合“刚……的人，工作经验少”的语境。", "退隐": "语义：退隐指离开公众生活，通常以长期经历为前提，与“工作经验少”相矛盾。", "退位": "搭配：退位指君主让出王位，不用于普通的人。", "退场": "语义：退场指离开舞台，表示工作已经结束，与“工作经验少”不符。"}, "sentence_index": 6, "correct_answer": "出道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天出道，把家从城东搬到了城西。", "explanation": "这里应该用〈搬家〉。出道指第一次出来做事并开始被大家知道，换地方住要说搬家。"}, {"text": "她上周出道，去医院做了手术。", "explanation": "这里应该用〈住院〉。出道指第一次出来做事并开始被大家知道，治病做手术要说住院。"}, {"text": "他前年高中出道，考上了大学。", "explanation": "这里应该用〈毕业〉。出道指开始在行业中公开活动，说完成学业要用毕业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学毕业后进了一家公司，三年后才正式出道着。", "corrected_sentence": "他大学毕业后进了一家公司，三年后才正式出道。", "error_description": "体标错误：“出道”后面不能接“着”，表示完成或开始的变化应直接用“出道了”或不加体标，“着”与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位年轻人去年了出道，很快就有了自己的客户。", "corrected_sentence": "这位年轻人去年出道，很快就有了自己的客户。", "error_description": "语序错误：“去年”后直接接“出道”，说成“去年了出道”是错误语序，“了”不能放在“出道”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
