INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始在某个行业中公开活动。", "primary_collocate": null, "pronunciation": "chū dào", "ipa": "ʈʂʰu˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "她十八岁就出道，成了一名歌手。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员二十岁出道，拍过很多电影。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是去年出道的新团体。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王出道以后，每天都有很多工作。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩还没出道，已经有很多人喜欢她。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出道十年了，一直在唱歌。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位歌手出道时只有十六岁。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想早点出道，所以每天练习唱歌。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队出道不到一年，就开了演唱会。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出道前在小店里打工，现在是有名的演员。", "target_word": "出道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出道了", "label": "体标"}, {"form": "出道作", "label": "复合"}], "register": "中性", "sense_fingerprint": "在演艺、体育等行业开始公开活动，如歌手、演员出道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出道", "is_correct": true, "explanation": "出道：开始在演艺等行业公开活动，符合“十八岁就……成了一名歌手”的起步义。"}, {"text": "去世", "is_correct": false, "explanation": "语义：去世指人死去，死去的人不能再“成了一名歌手”，句意矛盾。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休指年老后离开工作岗位，十八岁的人不会退休。"}, {"text": "下岗", "is_correct": false, "explanation": "搭配：下岗指国有单位职工失去工作岗位，不能与“成了一名歌手”搭配。"}], "explanations": {"出道": "出道：开始在演艺等行业公开活动，符合“十八岁就……成了一名歌手”的起步义。", "去世": "语义：去世指人死去，死去的人不能再“成了一名歌手”，句意矛盾。", "退休": "语义：退休指年老后离开工作岗位，十八岁的人不会退休。", "下岗": "搭配：下岗指国有单位职工失去工作岗位，不能与“成了一名歌手”搭配。"}, "sentence_index": 0, "correct_answer": "出道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下个月出道，担任公司的财务经理。", "explanation": "这里应该用〈上任〉。出道指开始在演艺、体育等行业公开活动，担任公司职务要说上任。"}, {"text": "他大学毕业后出道做了会计。", "explanation": "这里应该用〈入行〉。出道多用于演艺、体育等行业，做会计这类一般工作不用出道。"}, {"text": "这部新电影在东京出道。", "explanation": "这里应该用〈亮相〉。出道指人开始在行业中活动，电影等作品不说出道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出道", "is_correct": true, "explanation": "出道：开始在行业中公开活动，符合“那位歌手……时只有十六岁”的语境。"}, {"text": "解散", "is_correct": false, "explanation": "搭配：解散多用于乐队、团体等组织，不能说某位歌手解散。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休指年老后离开工作岗位，十六岁的人不会退休。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指降生，不能用来表示歌手开始公开活动的时间，句意说不通。"}], "explanations": {"出道": "出道：开始在行业中公开活动，符合“那位歌手……时只有十六岁”的语境。", "解散": "搭配：解散多用于乐队、团体等组织，不能说某位歌手解散。", "退休": "语义：退休指年老后离开工作岗位，十六岁的人不会退休。", "出生": "语义：出生指降生，不能用来表示歌手开始公开活动的时间，句意说不通。"}, "sentence_index": 6, "correct_answer": "出道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年从大学出道，之后找了工作。", "explanation": "这里应该用〈毕业〉。出道指开始在行业中公开活动，说完成学业要用毕业。"}, {"text": "他十八岁出道，当了国王。", "explanation": "这里应该用〈即位〉。出道用于演艺、体育等行业，不指君主即位。"}, {"text": "她上周出道，已经回家了。", "explanation": "这里应该用〈出院〉。出道指开始在行业中公开活动，病人离开医院要说出院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学毕业后报名参加选秀，很快就出道着。", "corrected_sentence": "他大学毕业后报名参加选秀，很快就出道了。", "error_description": "体标错误：“出道”表示动作已经开始并完成，应接“了”，说成“出道着”表示持续，不符合句意。正确形式是“出道了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个刚出道地歌手很有名。", "corrected_sentence": "一个刚出道的歌手很有名。", "error_description": "结构助词错误：“出道”修饰名词“歌手”时应用“的”，说成“地”是错误。“地”用于修饰动词或形容词，正确形式是“刚出道的歌手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "别说是后面的事情更小，前面的事情更大，连小的也做不到。", "primary_collocate": null, "pronunciation": "bié shuō", "ipa": "pjɛ˧˥ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "别说跑步，我连走路都累。", "target_word": "别说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别说一百块，我连十块都没有。", "target_word": "别说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别说做饭，他连水都不会烧。", "target_word": "别说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别说大海，我连河都没见过。", "target_word": "别说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说大学，我连中学都没读完。", "target_word": "别说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说国外，我连北京都没去过。", "target_word": "别说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说唱歌，我连说话都没有力气了。", "target_word": "别说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别说一天，我连一个小时都等不了。", "target_word": "别说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字太难了，别说写，我连认都认不出来。", "target_word": "别说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说中文书，我连中文电影都看不懂。", "target_word": "别说", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别说：连词，前面的事更大，连后面更小的事也做不到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别说", "is_correct": true, "explanation": "正确：“别说”先提出更难的“跑步”，再用“连……都”带出更小的“走路”，构成递进。"}, {"text": "不管", "is_correct": false, "explanation": "配价：“不管”要接“跑不跑步”之类的选择或疑问项，单独接“跑步”不成句。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二选一，句中没有可选的两项，与“连……都”的递进意思不合。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”呼应，且表示唯一条件，与后句“连走路都累”的递进不搭。"}], "explanations": {"别说": "正确：“别说”先提出更难的“跑步”，再用“连……都”带出更小的“走路”，构成递进。", "不管": "配价：“不管”要接“跑不跑步”之类的选择或疑问项，单独接“跑步”不成句。", "或者": "语义：“或者”表示二选一，句中没有可选的两项，与“连……都”的递进意思不合。", "只有": "搭配：“只有”要与“才”呼应，且表示唯一条件，与后句“连走路都累”的递进不搭。"}, "sentence_index": 0, "correct_answer": "别说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "别说大海，我见过河。", "explanation": "别说要引出做不到的更小的事，并用“连……都”带出。这句没有“连……都”，而且“见过河”本身已经做到，与别说的递进不符。"}, {"text": "别说写字，我连一个字都能写。", "explanation": "别说后面的小事应是做不到的，并用“连……都”带出否定；这里说“能写”，与递进相反，不能用别说。"}, {"text": "别说大学，我已经读完了中学。", "explanation": "别说要先说更大的事，再用“连……都”带出更小的、做不到的事；这句没有“连……都”，前后也不是递进关系，不能用别说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别说", "is_correct": true, "explanation": "正确：“别说”引出更难的“唱歌”，后用“连说话都”带出更小的事，构成递进。"}, {"text": "无论", "is_correct": false, "explanation": "语义：“无论”表示不论什么情况都如此，不表示由大到小的递进，与“连……都”的递进意思不合。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”要与“也”呼应，且后句“没有力气了”说的是已经发生的事实，不是假设。"}, {"text": "然而", "is_correct": false, "explanation": "语域：“然而”偏书面，口语里很少这样放在句首，而且表示转折，这里前后没有对立。"}], "explanations": {"别说": "正确：“别说”引出更难的“唱歌”，后用“连说话都”带出更小的事，构成递进。", "无论": "语义：“无论”表示不论什么情况都如此，不表示由大到小的递进，与“连……都”的递进意思不合。", "即使": "搭配：“即使”要与“也”呼应，且后句“没有力气了”说的是已经发生的事实，不是假设。", "然而": "语域：“然而”偏书面，口语里很少这样放在句首，而且表示转折，这里前后没有对立。"}, "sentence_index": 6, "correct_answer": "别说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不但会说英语，别说会说日语。", "explanation": "这里应该用〈甚至〉。别说要引出更难的事，后面用“连……都”带出更小的事；这句只是肯定地说“会说日语”，没有这种递进，不宜用别说。"}, {"text": "别说昨天下雨，今天也很冷。", "explanation": "别说只用于前后有递进关系的句子，先说更难的事，再用“连……都”带出更小的事；这句的两件事只是并列，没有递进。"}, {"text": "别说汽车，他连飞机都没坐过。", "explanation": "别说要先引出更大、更难的事，再用“连……都”带出更小的事。坐飞机比坐汽车更难得，这句方向颠倒了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别说游泳，我连坐船晕。", "corrected_sentence": "别说游泳，我连坐船都晕。", "error_description": "错误：“连……都”缺少“都”，“我连坐船晕”不成句，应为“我连坐船都晕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别说参加比赛，我连报名没有。", "corrected_sentence": "别说参加比赛，我连报名都没有。", "error_description": "错误形式是“我连报名没有”，正确形式是“我连报名都没有”。“连”要与“都”（或“也”）呼应，缺了“都”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
