INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃请是别人请你去吃饭。", "primary_collocate": null, "pronunciation": "chī qǐng", "ipa": "ʈʂʰɻ̩⁵⁵ tɕʰiŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "他今晚要去朋友家吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老张朋友多，天天在外面吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近一直吃请，都没在家做饭。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天公司的客户请我，我得去吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱吃请，更喜欢在家吃饭。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时亲戚们互相请客，大家轮流吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我去同学家吃请，很晚才回来。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃请吃得太多，胖了不少。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我有两个地方要吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁请客，我就去谁家吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃請", "label": "繁体"}], "register": "口语", "sense_fingerprint": "动词，应别人邀请去对方那里吃饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃请", "is_correct": true, "explanation": "正确：动词，指接受朋友邀请去吃饭，与「去朋友家」的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「去朋友家结婚」与「今晚」的聚餐语境不符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：「去朋友家上学」不是日常的出门活动，与语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「去朋友家考试」与吃饭的语境不符。"}], "explanations": {"吃请": "正确：动词，指接受朋友邀请去吃饭，与「去朋友家」的语境相符。", "结婚": "语义：「去朋友家结婚」与「今晚」的聚餐语境不符。", "上学": "语义：「去朋友家上学」不是日常的出门活动，与语境不符。", "考试": "语义：「去朋友家考试」与吃饭的语境不符。"}, "sentence_index": 0, "correct_answer": "吃请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我请客户吃请，场面很热闹。", "explanation": "这里应该用〈请客〉。〈吃请〉指接受别人邀请去吃饭，不能用来表示自己请人吃饭。"}, {"text": "我昨天一个人在家吃请。", "explanation": "这里应该用〈吃饭〉。〈吃请〉的前提是有人邀请，独自在家不能用〈吃请〉。"}, {"text": "妈妈在厨房里吃请，忙着做了一桌菜。", "explanation": "〈吃请〉不能用于在厨房里忙着做饭的人自己吃饭，这里应该用〈吃饭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃请", "is_correct": true, "explanation": "正确：动词，指接受同学的邀请去吃饭，与「去同学家」的语境相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：「去同学家上班」与「很晚才回来」的语境不符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：「去同学家生病」不是出门的活动，与语境不符。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：「去同学家罚款」与出门做客的语境不符。"}], "explanations": {"吃请": "正确：动词，指接受同学的邀请去吃饭，与「去同学家」的语境相符。", "上班": "语义：「去同学家上班」与「很晚才回来」的语境不符。", "生病": "语义：「去同学家生病」不是出门的活动，与语境不符。", "罚款": "语义：「去同学家罚款」与出门做客的语境不符。"}, "sentence_index": 6, "correct_answer": "吃请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板请客，我没去，只在家里吃请。", "explanation": "这里应该用〈吃饭〉。〈吃请〉要去别人那里吃饭，在家里不能用〈吃请〉。"}, {"text": "他在路上吃请，一边走一边吃面包。", "explanation": "这里应该用〈吃饭〉或〈吃东西〉。〈吃请〉指接受别人邀请去吃饭，不能用于路上随便吃东西。"}, {"text": "这个学生吃请得很认真。", "explanation": "这里〈吃请〉被误用为一般「吃」的意思。〈吃请〉指接受别人的邀请吃饭，应该用〈吃饭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天朋友家吃请了。", "corrected_sentence": "我昨天去朋友家吃请了。", "error_description": "处所「朋友家」前面缺少动词「去」（或介词「在」），不能直接放在「吃请」前；应说「去朋友家吃请」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周六叔叔请我，我去他家把吃请了。", "corrected_sentence": "周六叔叔请我，我去他家吃请了。", "error_description": "「吃请」是不及物动词，不能用「把」字句；「把吃请了」不符合语法，应说「去他家吃请了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
