INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接受别人的宴请。", "primary_collocate": null, "pronunciation": "chī qǐng", "ipa": "ʈʂʰɻ̩⁵⁵ tɕʰiŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "规定说，干部不准吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板请他吃饭，他谢谢了，没有吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员从不吃请，下班后总是自己做饭。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有规定，上班时间不能吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕别人说闲话，所以不吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长一向不收礼，也不吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，学生家长请客，我们不能吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人请他吃饭，他总是推辞，从不吃请。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方再三请客，他只好吃请。", "target_word": "吃请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生们约好，不吃请，不收红包。", "target_word": "吃请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃請", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词，接受他人的宴请，常用于规定或表态的场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃请", "is_correct": true, "explanation": "正确：动词，指接受别人的宴请，与「规定」的语境相符。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：「干部不准写作业」与规定吃请的语境不符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：「干部不准上课」与规定宴请的语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「干部不准考试」与宴请的语境无关。"}], "explanations": {"吃请": "正确：动词，指接受别人的宴请，与「规定」的语境相符。", "写作业": "语义：「干部不准写作业」与规定吃请的语境不符。", "上课": "语义：「干部不准上课」与规定宴请的语境不符。", "考试": "语义：「干部不准考试」与宴请的语境无关。"}, "sentence_index": 0, "correct_answer": "吃请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在办公室吃请，自己带饭。", "explanation": "〈吃请〉要有人邀请，自己带饭不能用〈吃请〉，应说〈吃饭〉。"}, {"text": "我请同事吃请，大家都很开心。", "explanation": "这里应该用〈请客〉。〈吃请〉是接受邀请，不是请别人。"}, {"text": "他一边打电话，一边吃请自己做的饭，很忙。", "explanation": "这里应该用〈吃饭〉。〈吃请〉指接受别人的宴请，不能用于吃自己做的饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃请", "is_correct": true, "explanation": "正确：动词，指接受别人的邀请去吃饭，与「学生家长请客」的语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「我们不能游泳」与「家长请客」的语境不连贯。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「我们不能睡觉」与「家长请客」的语境不连贯。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：「我们不能洗澡」与「家长请客」的语境不连贯。"}], "explanations": {"吃请": "正确：动词，指接受别人的邀请去吃饭，与「学生家长请客」的语境相符。", "游泳": "语义：「我们不能游泳」与「家长请客」的语境不连贯。", "睡觉": "语义：「我们不能睡觉」与「家长请客」的语境不连贯。", "洗澡": "语义：「我们不能洗澡」与「家长请客」的语境不连贯。"}, "sentence_index": 6, "correct_answer": "吃请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请医生吃请，大家都很感谢。", "explanation": "这里应该用〈请客〉。〈吃请〉是接受别人的邀请去吃饭，不是请别人吃饭。"}, {"text": "这顿饭是我请的，我去吃请了。", "explanation": "这里应该用〈吃饭〉或〈请客〉。自己做东时不能说〈吃请〉。"}, {"text": "他在工地上吃请，蹲在地上吃盒饭。", "explanation": "这里应该用〈吃饭〉。〈吃请〉指接受别人的宴请，不用于在工地上随便吃盒饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "文件要求，干部一律不准把吃请。", "corrected_sentence": "文件要求，干部一律不准吃请。", "error_description": "「吃请」是不及物动词，「不准」后直接接「吃请」，中间不能加「把」；应说「不准吃请」，「不准把吃请」不符合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些医生从不吃请了，只按时上班。", "corrected_sentence": "这些医生从不吃请，只按时上班。", "error_description": "「从不」表示一贯的习惯，不能加「了」，应说「从不吃请」，「吃请了」的说法不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
