INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94609, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家政策是国家定下来的、大家要照着做的办法。", "primary_collocate": null, "pronunciation": "guó jiā zhèng cè", "ipa": "kwo˧˥ tɕja˥ ʈʂɤŋ˥˩ tsʰɤ˥˩", "syllable_count": 4, "sentences": [{"text": "国家政策告诉大家应该怎么做。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民都按照国家政策种地。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要照着国家政策办事。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的国家政策对大家都有用。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了今年的国家政策。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开店以前，要先看看国家政策。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家政策定下来以后，大家都要照着做。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天看新闻，了解国家政策。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家政策要求，孩子必须上学。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意不能不管国家政策。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "國家政策", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家定下来、全体人民要遵照执行的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家政策", "is_correct": true, "explanation": "国家政策：国家定下的办法，可以“告诉大家应该怎么做”。"}, {"text": "动物", "is_correct": false, "explanation": "配价：“告诉”要求能发出言语的主体，动物不能告诉人做事。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器皿，没有言语能力，不能告诉大家应该怎么做。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋是穿在脚上的鞋，不能告诉大家应该怎么做。"}], "explanations": {"国家政策": "国家政策：国家定下的办法，可以“告诉大家应该怎么做”。", "动物": "配价：“告诉”要求能发出言语的主体，动物不能告诉人做事。", "花瓶": "语义：花瓶是器皿，没有言语能力，不能告诉大家应该怎么做。", "拖鞋": "语义：拖鞋是穿在脚上的鞋，不能告诉大家应该怎么做。"}, "sentence_index": 0, "correct_answer": "国家政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的国家政策是大家一起参加的。", "explanation": "这里应该用〈赛制〉。国家政策指国家层面定下的办法，不能用来指某一次比赛的规则安排。"}, {"text": "我昨天买了一本国家政策。", "explanation": "量词：政策应该用〈项〉，“本”用于书册，不能用于政策。"}, {"text": "这家饭店的国家政策很好吃。", "explanation": "这里应该用〈菜〉。国家政策指国家定下的办法，不能用来指可以吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家政策", "is_correct": true, "explanation": "国家政策：定下来以后大家都要照着做，句子的语境完全吻合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能定下来让大家照着做。"}, {"text": "日记", "is_correct": false, "explanation": "语义：日记记录个人经历，不是大家要照着做的办法。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是用来唱的，不能让大家照着做，与句意冲突。"}], "explanations": {"国家政策": "国家政策：定下来以后大家都要照着做，句子的语境完全吻合。", "身材": "体貌：身材指人的体形，不能定下来让大家照着做。", "日记": "语义：日记记录个人经历，不是大家要照着做的办法。", "歌曲": "语义：歌曲是用来唱的，不能让大家照着做，与句意冲突。"}, "sentence_index": 6, "correct_answer": "国家政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首国家政策很长，我昨天背了一遍。", "explanation": "量词：“首”用于诗词、歌曲，政策应该用〈项〉。"}, {"text": "他每天都在国家政策里睡觉。", "explanation": "这里应该用〈房间〉。国家政策是办法，不是可以睡觉的地方。"}, {"text": "国家政策今天感冒了，不能上课。", "explanation": "这里应该用〈我〉。国家政策是抽象的办法，不会感冒，句中的主语应该指学生本人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一张国家政策。", "corrected_sentence": "这是一项国家政策。", "error_description": "错误：「一张国家政策」；正确：「一项国家政策」。“张”用于纸张、桌子等平面的物件，“政策”的量词应用“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些国家政策们都很重要。", "corrected_sentence": "这些国家政策都很重要。", "error_description": "错误：「国家政策们」；正确：「国家政策」。“们”只用于指人的名词，不能加在“政策”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
