INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家为实现一定目标而制定的行动准则。", "primary_collocate": null, "pronunciation": "guó jiā zhèng cè", "ipa": "kwo˧˥ tɕja˥ ʈʂɤŋ˥˩ tsʰɤ˥˩", "syllable_count": 4, "sentences": [{"text": "国家政策是为了让大家过得更好。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护环境，国家政策有了新变化。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项国家政策的目标是帮助穷人。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家政策帮助年轻人找到工作。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家政策让农村的孩子也能上好学校。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了少用水，国家政策要求大家节约。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的国家政策能让经济发展得更快。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项国家政策是为了减少污染。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家政策的目的，是让每个人都有房子住。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年出了新的国家政策，目的是鼓励大家生孩子。", "target_word": "国家政策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "國家政策", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家为达到某个目标而定的行动准则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家政策", "is_correct": true, "explanation": "国家政策：为了让大家过得更好而制定，句子的目的吻合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不是为了让大家过得更好而制定的。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：汉字是文字符号，不能说成是为了让大家过得更好而定的。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“为了……”后面接的是行为或措施，“体重”不能作为这样的承担者。"}], "explanations": {"国家政策": "国家政策：为了让大家过得更好而制定，句子的目的吻合。", "天空": "语义：天空是自然景物，不是为了让大家过得更好而制定的。", "汉字": "语义：汉字是文字符号，不能说成是为了让大家过得更好而定的。", "体重": "搭配：“为了……”后面接的是行为或措施，“体重”不能作为这样的承担者。"}, "sentence_index": 0, "correct_answer": "国家政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的国家政策每周都要打扫教室。", "explanation": "这里应该用〈校规〉。国家政策指国家层面制定的行动准则，不能用来指学校内部的日常安排。"}, {"text": "一只国家政策帮助年轻人找到工作。", "explanation": "量词：“只”用于动物，政策应该用〈项〉。"}, {"text": "妈妈每天都让我做国家政策，我很辛苦。", "explanation": "这里应该用〈作业〉。国家政策是国家制定的行动准则，不是孩子每天要做的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家政策", "is_correct": true, "explanation": "国家政策：好的政策能让经济发展得更快，句子语境吻合。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能让经济发展得更快，这样说与句意冲突。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是艺术作品，不能直接让经济发展得更快。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体形特征，与经济发展无关，句子说不通。"}], "explanations": {"国家政策": "国家政策：好的政策能让经济发展得更快，句子语境吻合。", "蔬菜": "语义：蔬菜是食物，不能让经济发展得更快，这样说与句意冲突。", "歌曲": "语义：歌曲是艺术作品，不能直接让经济发展得更快。", "身高": "体貌：身高是人的体形特征，与经济发展无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "国家政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项国家政策很好看，我每天都去欣赏。", "explanation": "这里应该用〈作品〉。国家政策指国家制定的行动准则，不是可供欣赏的艺术作品。"}, {"text": "一棵国家政策让大家明白了道理。", "explanation": "量词：“棵”用于植物，政策应该用〈项〉。"}, {"text": "国家政策每天晚上都在跑步。", "explanation": "这里应该用〈他〉。国家政策是制定的行动准则，不会跑步，句中的动作应该由人来做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台国家政策很有效。", "corrected_sentence": "这项国家政策很有效。", "error_description": "错误：「这台国家政策」；正确：「这项国家政策」。“台”用于机器等物件，“政策”的量词应用“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些国家政策们都很有用。", "corrected_sentence": "这些国家政策都很有用。", "error_description": "错误：「国家政策们」；正确：「国家政策」。“们”不能加在表示事物的“政策”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
