INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94611, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "天啊是遇到吃惊的事时喊出来的话。", "primary_collocate": null, "pronunciation": "tiān a", "ipa": "tʰiɛn˥ a", "syllable_count": 2, "sentences": [{"text": "天啊，你怎么在这里？", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，我的手机不见了！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，这么多人！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到成绩，她大叫：“天啊！”", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，外面下雪了！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，这只猫会开门！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，你的头发怎么变红了？", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，我忘了带钥匙！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就说：“天啊，好漂亮！”", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，现在已经十二点了！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天哪", "label": "异形词"}, {"form": "我的天啊", "label": "复合词"}], "register": "口语", "sense_fingerprint": "遇到吃惊的事时脱口喊出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天啊", "is_correct": true, "explanation": "天啊是遇到吃惊的事时脱口喊出的话，与句中“你怎么在这里”的惊讶相符。"}, {"text": "生日快乐", "is_correct": false, "explanation": "语义：生日快乐是祝福语，与这里的惊讶发问不符。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘是要人安静的声音，接在这句惊讶询问前不通。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：晚安是睡前道别用语，与这里的惊讶发问不符。"}], "explanations": {"天啊": "天啊是遇到吃惊的事时脱口喊出的话，与句中“你怎么在这里”的惊讶相符。", "生日快乐": "语义：生日快乐是祝福语，与这里的惊讶发问不符。", "嘘": "语义：嘘是要人安静的声音，接在这句惊讶询问前不通。", "晚安": "语义：晚安是睡前道别用语，与这里的惊讶发问不符。"}, "sentence_index": 0, "correct_answer": "天啊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天啊，早上好，欢迎你来我家。", "explanation": "“天啊”表示突然的惊讶，不用于向客人打招呼。"}, {"text": "朋友说“谢谢你”，我回答：“天啊，不客气。”", "explanation": "“天啊”表示突然的惊讶，回应别人的道谢时没有这种情绪，不能用它。"}, {"text": "天啊，请各位在十点前提交报告。", "explanation": "“天啊”是口语中的感叹语，不能用于下达正式的要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天啊", "is_correct": true, "explanation": "天啊是遇到吃惊的事时脱口喊出的话，与“你的头发怎么变红了”的惊讶语气相符。"}, {"text": "谢谢", "is_correct": false, "explanation": "语义：谢谢是道谢用语，与这里的惊讶发问不符。"}, {"text": "再见", "is_correct": false, "explanation": "语义：再见是告别用语，与这里的惊讶发问不符。"}, {"text": "呜呼", "is_correct": false, "explanation": "语域：呜呼是文言悲叹，与口语的惊讶不相称。"}], "explanations": {"天啊": "天啊是遇到吃惊的事时脱口喊出的话，与“你的头发怎么变红了”的惊讶语气相符。", "谢谢": "语义：谢谢是道谢用语，与这里的惊讶发问不符。", "再见": "语义：再见是告别用语，与这里的惊讶发问不符。", "呜呼": "语域：呜呼是文言悲叹，与口语的惊讶不相称。"}, "sentence_index": 6, "correct_answer": "天啊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天啊，明天见！", "explanation": "“天啊”只表示突然的惊讶，不能用来道别。"}, {"text": "天啊，今天的天气是晴天。", "explanation": "“天啊”只表示遇到吃惊的事时的惊讶，平淡地报告天气时没有这种情绪，不能用它。"}, {"text": "天啊，请把盐递给我。", "explanation": "“天啊”表示感叹，不能用来向别人提出请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天啊的头发变红了！", "corrected_sentence": "天啊，你的头发变红了！", "error_description": "“天啊的”错误。“天啊”是叹词，不能直接修饰名词“头发”，应说“天啊，你的头发变红了！”，天啊后用逗号隔开。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天啊了，我的电脑坏了！", "corrected_sentence": "天啊，我的电脑坏了！", "error_description": "“天啊了”错误。“天啊”是叹词，后面不能加“了”表示完成，应去掉“了”，说“天啊，我的电脑坏了！”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
