INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94612, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "叹词，表示惊讶、惊叹或无奈。", "primary_collocate": null, "pronunciation": "tiān a", "ipa": "tʰiɛn˥ a", "syllable_count": 2, "sentences": [{"text": "天啊，这座山真高！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，又要加班了。", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，我真不知道怎么办。", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，这个孩子太聪明了！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，作业怎么这么多。", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，他又迟到了。", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，这里的风景太美了！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，她唱得真好听！", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，雨下得这么大，怎么回家？", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天啊，这道题我怎么也不会。", "target_word": "天啊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天哪", "label": "异形词"}, {"form": "我的天啊", "label": "复合词"}], "register": "口语", "sense_fingerprint": "表示惊叹或无奈的感叹语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天啊", "is_correct": true, "explanation": "天啊是遇到吃惊的事时脱口喊出的话，与“这座山真高”的赞叹相符。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示轻蔑或不满，与对山高的赞叹不符。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘是要人安静的声音，与赞叹山高的话不相合。"}, {"text": "呜呼", "is_correct": false, "explanation": "语域：呜呼是文言感叹，与口语的赞叹不相称。"}], "explanations": {"天啊": "天啊是遇到吃惊的事时脱口喊出的话，与“这座山真高”的赞叹相符。", "哼": "语义：哼表示轻蔑或不满，与对山高的赞叹不符。", "嘘": "语义：嘘是要人安静的声音，与赞叹山高的话不相合。", "呜呼": "语域：呜呼是文言感叹，与口语的赞叹不相称。"}, "sentence_index": 0, "correct_answer": "天啊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天啊，小李，请你帮我拿一下书。", "explanation": "“天啊”是感叹词，不能用来呼唤他人。"}, {"text": "天啊，请问去火车站怎么走？", "explanation": "“天啊”表示惊讶、惊叹或无奈，用来礼貌地问路时没有这种情绪，不能用它。"}, {"text": "天啊，本次会议于下周三召开。", "explanation": "“天啊”表示惊讶、惊叹或无奈，用来平淡地通知会议时间时没有这种情绪，不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天啊", "is_correct": true, "explanation": "天啊是遇到吃惊的事时脱口喊出的话，与“这里的风景太美了”的赞叹相符。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示唾弃，与赞美风景的语气相反。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示轻蔑或不满，与赞美风景的语气相反。"}, {"text": "噫", "is_correct": false, "explanation": "语域：噫是文言叹词，与口语的赞叹不相称。"}], "explanations": {"天啊": "天啊是遇到吃惊的事时脱口喊出的话，与“这里的风景太美了”的赞叹相符。", "呸": "语义：呸表示唾弃，与赞美风景的语气相反。", "哼": "语义：哼表示轻蔑或不满，与赞美风景的语气相反。", "噫": "语域：噫是文言叹词，与口语的赞叹不相称。"}, "sentence_index": 6, "correct_answer": "天啊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天啊，我们一起去吃饭吧。", "explanation": "“天啊”只表示感叹，不能用来发出邀请。"}, {"text": "天啊，请问您贵姓？", "explanation": "“天啊”不能用于礼貌地询问别人的姓名。"}, {"text": "天啊，请大家把书翻到第五页。", "explanation": "“天啊”表示惊讶、惊叹或无奈，用来平淡地布置课堂任务时没有这种情绪，不能用它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
