INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94615, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对路是方法对，正好合适。", "primary_collocate": null, "pronunciation": "duì lù", "ipa": "tweɪ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这个办法很对路。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的办法不对路。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的教法对路，我学得很快。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样复习，方法不太对路。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的方法很对路，我的腿好多了。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换了一个办法，这次对路了。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的管理方法对路，大家都愿意干。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做对路吗？", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有方法对路，学习才有效果。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的做法很对路，继续这样做吧。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "對路", "label": "繁体"}], "register": "中性", "sense_fingerprint": "方法对头，正好合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对路", "is_correct": true, "explanation": "对路：方法对头、正好合适，与“办法”搭配，是句中要填的词。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材、体积，不能用来形容办法。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，不说办法热闹。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所或场面冷落，不能描述办法，与“办法”不符。"}], "explanations": {"对路": "对路：方法对头、正好合适，与“办法”搭配，是句中要填的词。", "高大": "体貌：“高大”形容人或物的身材、体积，不能用来形容办法。", "热闹": "语义：“热闹”形容场面或气氛，不说办法热闹。", "冷清": "语义：“冷清”形容场所或场面冷落，不能描述办法，与“办法”不符。"}, "sentence_index": 0, "correct_answer": "对路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很对路，阳光很好。", "explanation": "这里应该用〈晴朗〉。对路指方法、做法合适，不用来形容天气，天气好要用〈晴朗〉。"}, {"text": "他的笑容很对路，大家都觉得亲切。", "explanation": "这里应该用〈灿烂〉。对路指办法、做法合适，不用来形容笑容，笑容好看要用〈灿烂〉。"}, {"text": "他的身材很对路，所以常穿运动装。", "explanation": "这里应该用〈匀称〉。对路指办法、做法合适，形容人的身材好看要用〈匀称〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对路", "is_correct": true, "explanation": "对路：管理方法合适，能让大家愿意干，与“管理方法”搭配。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或颜色，不能用来形容管理方法。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，用来说管理方法不合语境，也与“大家都愿意干”矛盾。"}, {"text": "苦涩", "is_correct": false, "explanation": "搭配：“苦涩”形容味道或滋味，不说管理方法苦涩。"}], "explanations": {"对路": "对路：管理方法合适，能让大家愿意干，与“管理方法”搭配。", "明亮": "体貌：“明亮”形容光线或颜色，不能用来形容管理方法。", "嘈杂": "语义：“嘈杂”形容声音杂乱，用来说管理方法不合语境，也与“大家都愿意干”矛盾。", "苦涩": "搭配：“苦涩”形容味道或滋味，不说管理方法苦涩。"}, "sentence_index": 6, "correct_answer": "对路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小孩子很对路，大家都喜欢他。", "explanation": "这里应该用〈可爱〉。对路用于办法、货物等合乎需要，形容小孩子惹人喜爱要用〈可爱〉。"}, {"text": "他今天的心情很对路，一直在哼歌。", "explanation": "这里应该用〈愉快〉。对路指办法、做法合适，不用来形容心情，心情好要用〈愉快〉。"}, {"text": "她的脸很对路，大家都夸她。", "explanation": "这里应该用〈秀丽〉。对路指办法、做法合适，不用来形容相貌，形容相貌好看要用〈秀丽〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们改了做法，现在的对路了。", "corrected_sentence": "我们改了做法，现在对路了。", "error_description": "错误：“对路”作谓语时前面不加“的”，“的”用于名词修饰语，不能放在谓语形容词前。应说“现在对路了”，不说“现在的对路了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我上周用的那个办法没对路。", "corrected_sentence": "我上周用的那个办法不对路。", "error_description": "否定词错误：“对路”是形容词，否定要用“不”，不能用“没”；应说“不对路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
