INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94616, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合适，符合需要，方向正确。", "primary_collocate": null, "pronunciation": "duì lù", "ipa": "tweɪ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这批货很对路，一天就卖完了。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的产品对路，销量越来越高。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件礼物很对路，妈妈特别喜欢。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送的书不对路，我用不上。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的东西对路，顾客都爱买。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要的是红色的，这批货对路吗？", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作跟他的专业很对路。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批衣服不对路，没有人买。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新产品对路了，生意好起来了。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书正好对路，学生们都抢着买。", "target_word": "对路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "對路", "label": "繁体"}], "register": "中性", "sense_fingerprint": "符合需要，方向正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对路", "is_correct": true, "explanation": "对路：货物符合需要、销路好，与“一天就卖完了”的语境相合。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所或场面冷落，与“一天就卖完了”的销售情况矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不用来形容货物。"}, {"text": "苦涩", "is_correct": false, "explanation": "搭配：“苦涩”形容味道，不用来形容货物。"}], "explanations": {"对路": "对路：货物符合需要、销路好，与“一天就卖完了”的语境相合。", "冷清": "语义：“冷清”形容场所或场面冷落，与“一天就卖完了”的销售情况矛盾。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不用来形容货物。", "苦涩": "搭配：“苦涩”形容味道，不用来形容货物。"}, "sentence_index": 0, "correct_answer": "对路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头发很对路，又黑又密。", "explanation": "这里应该用〈浓密〉。对路指货物、做法合乎需要，不用来形容头发，形容头发多要用〈浓密〉。"}, {"text": "这匹马的步子很对路，跑得很快。", "explanation": "这里应该用〈稳健〉。对路不用来形容步子，形容步伐稳当要用〈稳健〉。"}, {"text": "他的手指很对路，弹钢琴很快。", "explanation": "这里应该用〈灵活〉。对路不用来形容手指，形容手指活动自如要用〈灵活〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对路", "is_correct": true, "explanation": "对路：工作与专业相合、符合需要，与“跟他的专业”搭配。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或颜色，不能用来形容工作与专业的关系。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与“工作”和“专业”不搭。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道，不说工作辛辣或专业辛辣。"}], "explanations": {"对路": "对路：工作与专业相合、符合需要，与“跟他的专业”搭配。", "明亮": "体貌：“明亮”形容光线或颜色，不能用来形容工作与专业的关系。", "清脆": "语义：“清脆”形容声音，与“工作”和“专业”不搭。", "辛辣": "搭配：“辛辣”形容味道，不说工作辛辣或专业辛辣。"}, "sentence_index": 6, "correct_answer": "对路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很对路，看起来很精神。", "explanation": "这里应该用〈红润〉。对路不用来形容脸色，形容脸色好要用〈红润〉。"}, {"text": "他的眉毛很对路，看上去很英俊。", "explanation": "这里应该用〈浓〉。对路不用来形容眉毛，形容眉毛又黑又多要用〈浓〉。"}, {"text": "他的声音很对路，大家都听得很清楚。", "explanation": "这里应该用〈洪亮〉。对路不能用来形容声音，说声音大而清楚要用〈洪亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批货终于的对路了，卖得很快。", "corrected_sentence": "这批货终于对路了，卖得很快。", "error_description": "错误：“对路”作谓语时前面不加“的”，应说“终于对路了”，不说“终于的对路了”。“的”不能插在谓语形容词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们选的书没对路，孩子们都不爱读。", "corrected_sentence": "我们选的书不对路，孩子们都不爱读。", "error_description": "否定词错误：“对路”是形容词，否定要用“不”，不能用“没”；应说“不对路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
