INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94617, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "导师是教你，带你学东西的老师。", "primary_collocate": null, "pronunciation": "dǎo shī", "ipa": "taʊ̯˨˩˦ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "我的导师每周都和我见一次面。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导师教我怎么写论文。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我在公司的导师，教会我很多东西。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请王老师当我的导师。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导师让我先把这本书看完。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很感谢我的导师，他一直帮助我。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学期，导师带我们去山里做研究。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的导师住在北京，我们常常发邮件。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导师说我写得不错，只是有点慢。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事有一位导师，会带他熟悉工作。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "導師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "教你、带你学东西的老师", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7730a907-17d6-4070-8ade-01789c2b16ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94617, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "导师", "is_correct": true, "explanation": "导师（dǎo shī）：指导学习、研究或工作的老师，是正确答案。"}, {"text": "倒是", "is_correct": false, "explanation": "倒是（dào shì）与导师（dǎo shī）两个音节声调都不同，是副词，表示转折或让步。"}, {"text": "到时", "is_correct": false, "explanation": "到时（dào shí）与导师（dǎo shī）两个音节的声调都不同，意思是到了那个时候。"}, {"text": "导视", "is_correct": false, "explanation": "导视（dǎo shì）与导师（dǎo shī）第二个音节声调不同，意思是导向标识。"}, {"text": "道士", "is_correct": false, "explanation": "道士（dào shi）与导师（dǎo shī）第一个音节声调不同，第二个音节读轻声，意思是道教的修行人。"}], "explanations": {"导师": "导师（dǎo shī）：指导学习、研究或工作的老师，是正确答案。", "倒是": "倒是（dào shì）与导师（dǎo shī）两个音节声调都不同，是副词，表示转折或让步。", "到时": "到时（dào shí）与导师（dǎo shī）两个音节的声调都不同，意思是到了那个时候。", "导视": "导视（dǎo shì）与导师（dǎo shī）第二个音节声调不同，意思是导向标识。", "道士": "道士（dào shi）与导师（dǎo shī）第一个音节声调不同，第二个音节读轻声，意思是道教的修行人。"}, "sentence_index": null, "correct_answer": "导师"}, "level_3": {"options": [{"text": "导师", "is_correct": true, "explanation": "导师：指导学习的人，与“每周都和我见一次面”相符，是正确答案。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能与人见面，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“见面”要求有生命的人作主语，窗户无法与“我”见面。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，不会与人见面，句意不通。"}], "explanations": {"导师": "导师：指导学习的人，与“每周都和我见一次面”相符，是正确答案。", "电脑": "语义：电脑是机器，不能与人见面，句意不通。", "窗户": "配价：“见面”要求有生命的人作主语，窗户无法与“我”见面。", "词典": "语义：词典是工具书，不会与人见面，句意不通。"}, "sentence_index": 0, "correct_answer": "导师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导师每天负责给学生发午饭。", "explanation": "这里应该用〈食堂工作人员〉。导师指教你、带你学东西的老师，不指发放饭菜的人。"}, {"text": "这位导师每天给我们送报纸。", "explanation": "这里应该用〈送报员〉。导师指教你、带你学东西的老师，不指送报的人。"}, {"text": "我请了一位导师，帮我修剪花园。", "explanation": "这里应该用〈园丁〉。导师指教你、带你学东西的老师，不指修剪花草的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导师", "is_correct": true, "explanation": "导师：指导学习和研究的人，与“带我们去山里做研究”相符，是正确答案。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是书籍，不能带人去山里做研究，句意不通。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育器材，不能带人去做研究，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“带……去”要求有行动能力的人作主语，冰箱无法带人去山里。"}], "explanations": {"导师": "导师：指导学习和研究的人，与“带我们去山里做研究”相符，是正确答案。", "小说": "语义：小说是书籍，不能带人去山里做研究，句意不通。", "篮球": "语义：篮球是体育器材，不能带人去做研究，句意不通。", "冰箱": "配价：“带……去”要求有行动能力的人作主语，冰箱无法带人去山里。"}, "sentence_index": 6, "correct_answer": "导师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店有一位导师，专门负责做红烧肉。", "explanation": "这里应该用〈厨师〉。导师指指导学习或工作的人，不指做菜的人。"}, {"text": "导师每天给病人量体温。", "explanation": "这里应该用〈护士〉。导师不指护理病人的人，给病人量体温要用护士。"}, {"text": "我家请了一位导师，每周来打扫卫生做饭。", "explanation": "这里应该用〈保姆〉。导师指指导学习或研究的人，不指料理家务的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校的一只导师很受学生欢迎。", "corrected_sentence": "我们学校的一位导师很受学生欢迎。", "error_description": "量词错误：“导师”指人，应用人的量词“位”，不能用动物量词“只”。应说“一位导师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学院的一位导师们很有名。", "corrected_sentence": "我们学院的一位导师很有名。", "error_description": "后缀错误：数量短语“一位”已表示数量，“导师”之后不能再加复数后缀“们”。应说“一位导师”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
