INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94619, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94619, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "尴尬是遇到不好意思的事，不知道怎么办。", "primary_collocate": null, "pronunciation": "gān gà", "ipa": "kan˥ ka˥˩", "syllable_count": 2, "sentences": [{"text": "我叫错了老师的名字，觉得很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大家面前摔倒了，真尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了她的生日，她问我时，我很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问我借钱，我不想借，觉得有点尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电梯里遇到老板，一句话也没说，太尴尬了。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看错了人，上去打招呼，心里很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机在会上响了，我尴尬地关掉了它。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子说错话以后，脸红了，不知道怎么办，很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把别人的杯子拿走了，才发现，真尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我穿错了衣服去参加聚会，别人都看我，真尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尴尬地", "label": "副词形式"}, {"form": "尷尬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人遇到不好意思的事，心里不自在，不知如何是好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbde994-dc07-4f05-b67a-7432fadb09bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尴尬", "is_correct": true, "explanation": "“尴尬”表示遇到不好意思的事、心里不自在，与“叫错了老师的名字”的情境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示开心，叫错老师的名字不会让人高兴。"}, {"text": "自豪", "is_correct": false, "explanation": "语义：“自豪”是因成就而得意，与叫错名字的情况相矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外表，不能用来形容心里的感受。"}], "explanations": {"尴尬": "“尴尬”表示遇到不好意思的事、心里不自在，与“叫错了老师的名字”的情境相符。", "高兴": "语义：“高兴”表示开心，叫错老师的名字不会让人高兴。", "自豪": "语义：“自豪”是因成就而得意，与叫错名字的情况相矛盾。", "漂亮": "体貌：“漂亮”形容外表，不能用来形容心里的感受。"}, "sentence_index": 0, "correct_answer": "尴尬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子看见狗很尴尬，一直往后退。", "explanation": "这里应该用〈害怕〉。尴尬指遇到不好意思的事、心里不自在，不表示害怕的情绪。"}, {"text": "他考了第一名，很尴尬。", "explanation": "这里应该用〈得意〉。尴尬表示心里不自在，不用来形容成功后的洋洋自得。"}, {"text": "妈妈看到女儿进步，很尴尬。", "explanation": "这里应该用〈高兴〉。尴尬表示心里不自在，不用来形容为别人的进步感到开心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尴尬", "is_correct": true, "explanation": "“尴尬地”修饰动作，表示心里不自在地关掉手机，与会上手机响的情境相符。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：“慷慨”指大方地给予，与关掉手机的动作不相符。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容待人的态度，不用来修饰关掉手机的动作。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”是洋洋自得，与会上手机响带来的窘境相矛盾。"}], "explanations": {"尴尬": "“尴尬地”修饰动作，表示心里不自在地关掉手机，与会上手机响的情境相符。", "慷慨": "语义：“慷慨”指大方地给予，与关掉手机的动作不相符。", "热情": "搭配：“热情”形容待人的态度，不用来修饰关掉手机的动作。", "得意": "语义：“得意”是洋洋自得，与会上手机响带来的窘境相矛盾。"}, "sentence_index": 6, "correct_answer": "尴尬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在公园里玩得很尴尬。", "explanation": "这里应该用〈开心〉。尴尬指遇到不好意思的事、心里不自在，不能用来形容玩得快乐。"}, {"text": "比赛获胜后，大家都很尴尬。", "explanation": "这里应该用〈兴奋〉。尴尬表示心里不自在，不用来形容赢了比赛后的激动。"}, {"text": "他听到奶奶去世的消息，很尴尬。", "explanation": "这里应该用〈悲伤〉。尴尬不表示失去亲人的悲痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在会上说错了话，觉得很地尴尬。", "corrected_sentence": "我在会上说错了话，觉得很尴尬。", "error_description": "错误形式：“很地尴尬”。正确形式：“很尴尬”。“很”直接修饰形容词“尴尬”，中间不能加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他笑地尴尬，不知道说什么好。", "corrected_sentence": "他笑得尴尬，不知道说什么好。", "error_description": "错误形式：“笑地尴尬”。正确形式：“笑得尴尬”。“地”用在动词前作状语，不能放在动词“笑”之后；“得”用在动词后引出状态补语，说明“笑”的情况。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "处境为难，神态不自然。", "primary_collocate": null, "pronunciation": "gān gà", "ipa": "kan˥ ka˥˩", "syllable_count": 2, "sentences": [{"text": "他的处境很尴尬，帮谁都不好。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在两个朋友中间，样子很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得很尴尬，不知道说什么好。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个尴尬的问题，大家都不想回答。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他丢了工作，又没有钱，处境十分尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人一见面，脸上的表情都有点尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里很安静，气氛变得尴尬起来。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是老师，也不是学生，身份有点尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听到这个问题，笑容看起来很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，他们在电梯里遇到，场面很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尴尬地", "label": "副词形式"}, {"form": "尷尬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "处境进退两难，或表情神态不自然", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbde994-dc07-4f05-b67a-7432fadb09bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尴尬", "is_correct": true, "explanation": "“处境尴尬”指进退两难，与“帮谁都不好”相符。"}, {"text": "顺利", "is_correct": false, "explanation": "语义：“顺利”表示没有阻碍，与“帮谁都不好”的两难处境矛盾。"}, {"text": "优越", "is_correct": false, "explanation": "语义：“优越”表示条件好，与两难的处境不符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“处境”一般说好、坏、困难，不说“处境热闹”。"}], "explanations": {"尴尬": "“处境尴尬”指进退两难，与“帮谁都不好”相符。", "顺利": "语义：“顺利”表示没有阻碍，与“帮谁都不好”的两难处境矛盾。", "优越": "语义：“优越”表示条件好，与两难的处境不符。", "热闹": "搭配：“处境”一般说好、坏、困难，不说“处境热闹”。"}, "sentence_index": 0, "correct_answer": "尴尬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次合作很尴尬，双方都很满意。", "explanation": "这里应该用〈顺利〉。尴尬表示处境为难或神态不自然，不能用来形容合作顺利、双方满意。"}, {"text": "父母看到孩子进步，感到很尴尬。", "explanation": "这里应该用〈欣慰〉。尴尬表示为难或不自然，不表示满意的心情。"}, {"text": "孩子考了满分，非常尴尬。", "explanation": "这里应该用〈自豪〉。尴尬表示处境为难或神态不自然，不表示骄傲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尴尬", "is_correct": true, "explanation": "“气氛尴尬”表示场面不自然，与“房间很安静”之后气氛的变化相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“气氛”不说“漂亮”，一般说热烈、融洽之类。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体形或物体的大小，不能用来形容气氛。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”指猛烈或凶狠，与安静的房间不相符。"}], "explanations": {"尴尬": "“气氛尴尬”表示场面不自然，与“房间很安静”之后气氛的变化相符。", "漂亮": "搭配：“气氛”不说“漂亮”，一般说热烈、融洽之类。", "高大": "体貌：“高大”形容体形或物体的大小，不能用来形容气氛。", "凶猛": "语义：“凶猛”指猛烈或凶狠，与安静的房间不相符。"}, "sentence_index": 6, "correct_answer": "尴尬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赢了比赛，心里很尴尬。", "explanation": "这里应该用〈得意〉。尴尬指处境为难或神态不自然，不用来形容赢了比赛后的得意。"}, {"text": "球迷听到进球的消息，都很尴尬。", "explanation": "这里应该用〈兴奋〉。尴尬表示为难或神态不自然，不用来描述听到好消息时的激动。"}, {"text": "听到亲人去世的消息，他很尴尬。", "explanation": "这里应该用〈悲伤〉。尴尬不表示失去亲人的悲痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他夹在两家人中间，这种尴尬地处境让他很累。", "corrected_sentence": "他夹在两家人中间，这种尴尬的处境让他很累。", "error_description": "结构助词用错。错误形式是“尴尬地处境”，正确形式是“尴尬的处境”。“尴尬”修饰名词“处境”时要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人见面后，她尴尬了地转过了头。", "corrected_sentence": "两人见面后，她尴尬地转过了头。", "error_description": "错误形式：“尴尬了地转过了头”。正确形式：“尴尬地转过了头”。“了”表示完成，不能插在状语“尴尬”和结构助词“地”之间，这样组合不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
