INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "层次是一层一层排好的样子。", "primary_collocate": null, "pronunciation": "céng cì", "ipa": "tsʰɤŋ³⁵ tsʰɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "这个蛋糕的层次很多，很好看。", "target_word": "层次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画颜色深浅不同，层次很美。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树一层一层，层次很清楚。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发剪得很有层次。", "target_word": "层次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜的味道有层次，先甜后咸。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯田的层次从山下排到山上。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饼一层一层，层次真好。", "target_word": "层次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子的灯光有层次，看起来很舒服。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的花排得很有层次。", "target_word": "层次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这碗汤的层次很丰富，每口都不一样。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "层次感", "label": "复合"}, {"form": "層次", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，东西一层一层排列、看得出前后深浅的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "层次", "is_correct": true, "explanation": "正确。“层次”指一层一层排列出的样子，与“很多，很好看”相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不说“很多，很好看”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：蛋糕不会发出声音，“声音很好看”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：蛋糕没有脾气，无法“很好看”。"}], "explanations": {"层次": "正确。“层次”指一层一层排列出的样子，与“很多，很好看”相合。", "价格": "搭配：“价格”说高低，不说“很多，很好看”。", "声音": "语义：蛋糕不会发出声音，“声音很好看”说不通。", "脾气": "语义：蛋糕没有脾气，无法“很好看”。"}, "sentence_index": 0, "correct_answer": "层次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盒饼干的层次是十二块。", "explanation": "这里应该用〈数量〉。层次指一层一层排好的样子，块数多少要说“数量”。"}, {"text": "这座楼的层次很快，三个月就盖好了。", "explanation": "这里应该用〈速度〉。层次指一层一层排好的样子，建造的快慢要说“速度”。"}, {"text": "这箱苹果的层次是五公斤。", "explanation": "这里应该用〈重量〉。层次指一层一层排好的样子，苹果有多重要说“重量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "层次", "is_correct": true, "explanation": "正确。“层次”指饼一层层排开的样子，与前半句“一层一层”呼应。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人，不用于饼。"}, {"text": "性格", "is_correct": false, "explanation": "语义：饼没有性格，“性格真好”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：饼没有年龄，句子无法成立。"}], "explanations": {"层次": "正确。“层次”指饼一层层排开的样子，与前半句“一层一层”呼应。", "身材": "体貌：“身材”只用于人，不用于饼。", "性格": "语义：饼没有性格，“性格真好”说不通。", "年龄": "语义：饼没有年龄，句子无法成立。"}, "sentence_index": 6, "correct_answer": "层次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的层次是两小时。", "explanation": "这里应该用〈时长〉。层次指一层一层排好的样子，电影的长度要说“时长”。"}, {"text": "这个面包的层次很贵，一个要二十元。", "explanation": "这里应该用〈价格〉。层次指一层一层排好的样子，价钱的高低要说“价格”。"}, {"text": "这位老人的层次是八十岁。", "explanation": "这里应该用〈年龄〉。层次指一层一层排好的样子，人的岁数要说“年龄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块饼有三张层次，很好看。", "corrected_sentence": "这块饼有三个层次，很好看。", "error_description": "“层次”应搭配量词“个”，不能用“张”（“张”用于纸、桌子等平面的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这碗汤很层次，味道很丰富。", "corrected_sentence": "这碗汤很有层次，味道很丰富。", "error_description": "“很有层次”是固定说法，省去“有”就不成立，应说“很有层次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
