INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物按一定顺序排列的级别或阶段。", "primary_collocate": null, "pronunciation": "céng cì", "ipa": "tsʰɤŋ³⁵ tsʰɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "这篇文章的层次很清楚。", "target_word": "层次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里有很多层次的管理人员。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把问题分成三个层次来说。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法有层次，一步一步讲。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的水平有不同的层次。", "target_word": "层次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套练习题有由易到难的几个层次。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学习内容分成几个层次。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很有层次，大家都听得懂。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的消费有高低不同的层次。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者按时间排好文章的层次。", "target_word": "层次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "层次感", "label": "复合"}, {"form": "層次", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，事物或内容按顺序分出的级别、阶段或条理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "层次", "is_correct": true, "explanation": "正确。“层次”指文章内容按顺序分出的条理级别，与“很清楚”搭配。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低、贵贱，不说“很清楚”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：文章没有温度，“温度很清楚”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：文章没有体重，这个句子无法成立。"}], "explanations": {"层次": "正确。“层次”指文章内容按顺序分出的条理级别，与“很清楚”搭配。", "价格": "搭配：“价格”说高低、贵贱，不说“很清楚”。", "温度": "语义：文章没有温度，“温度很清楚”说不通。", "体重": "语义：文章没有体重，这个句子无法成立。"}, "sentence_index": 0, "correct_answer": "层次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项检查的层次是每周一次。", "explanation": "这里应该用〈频率〉。层次指事物的级别或阶段，表示次数多少要说“频率”。"}, {"text": "他说话的层次很快，听的人有点累。", "explanation": "这里应该用〈节奏〉。层次指级别或条理，说话的快慢要说“节奏”。"}, {"text": "他每周去图书馆的层次是三次。", "explanation": "这里应该用〈次数〉。层次指级别或阶段，去图书馆的次数要说“次数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "层次", "is_correct": true, "explanation": "正确。“层次”指学习内容分出的级别，与“分成几个”搭配。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只用于人，不用于学习内容。"}, {"text": "味道", "is_correct": false, "explanation": "语义：学习内容没有味道，“分成几个味道”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：学习内容没有颜色，“分成几个颜色”说不通。"}], "explanations": {"层次": "正确。“层次”指学习内容分出的级别，与“分成几个”搭配。", "身材": "体貌：“身材”只用于人，不用于学习内容。", "味道": "语义：学习内容没有味道，“分成几个味道”说不通。", "颜色": "语义：学习内容没有颜色，“分成几个颜色”说不通。"}, "sentence_index": 6, "correct_answer": "层次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目的层次很快，下周就能完成。", "explanation": "这里应该用〈进度〉。层次指事物的级别或条理，不说快慢；快慢要说“进度”。"}, {"text": "这块布的层次是两米。", "explanation": "这里应该用〈长度〉。层次指事物的级别或条理，布的长短要说“长度”。"}, {"text": "这束花的层次很好闻。", "explanation": "这里应该用〈气味〉。层次指事物的级别或条理，不能“好闻”；花闻起来怎么样要说“气味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告分成三条层次，很清楚。", "corrected_sentence": "这份报告分成三个层次，很清楚。", "error_description": "“层次”应搭配量词“个”，不能用“条”（“条”用于细长的东西，如“一条路”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师讲课很层次。", "corrected_sentence": "这位老师讲课很有层次。", "error_description": "“很有层次”是固定说法，省去“有”就不成立，应说“很有层次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
