INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "常务委员会的成员的简称，指在委员会中负责日常事务、经常履行职责的委员。", "primary_collocate": null, "pronunciation": "cháng wěi", "ipa": "tʂʰɑŋ˧˥ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是常委之一，负责日常工作。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位常委每天都去办公室。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "常委要经常参加会议。", "target_word": "常委", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家选她当常委。", "target_word": "常委", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的常委已经上班了。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位常委刚从北京回来。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "常委们讨论了今年的预算。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年常委，很有经验。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里有十二位常委。", "target_word": "常委", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "常委负责审查每月的报告。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "正式", "sense_fingerprint": "常务委员会中负责日常事务的委员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb53a5c-65d7-4ea3-9d02-709f50e00d34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常委", "is_correct": true, "explanation": "常委是常务委员会中负责日常事务的委员，与“负责日常工作”相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不负责日常工作，与句意矛盾。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是来买东西的人，不负责日常工作。"}, {"text": "鲜花", "is_correct": false, "explanation": "搭配：“鲜花”不指人，不能用于“……之一，负责日常工作”。"}], "explanations": {"常委": "常委是常务委员会中负责日常事务的委员，与“负责日常工作”相符。", "游客": "语义：游客是来参观的人，不负责日常工作，与句意矛盾。", "顾客": "语义：顾客是来买东西的人，不负责日常工作。", "鲜花": "搭配：“鲜花”不指人，不能用于“……之一，负责日常工作”。"}, "sentence_index": 0, "correct_answer": "常委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院的常委给我打了一针。", "explanation": "这里应该用〈护士〉。打针是护士的工作，“常委”是常务委员会的委员。"}, {"text": "这位常委在工地上搬砖，从不管日常事务。", "explanation": "这里应该用〈工人〉。常委负责日常事务、经常履行职责，在工地搬砖是工人的工作，不说〈常委〉。"}, {"text": "这位常委每天在农田里收割庄稼，从不参加会议。", "explanation": "这里应该用〈农民〉。常委常常要参加会议、履行职责，在农田里收割庄稼是农民的劳动，不说〈常委〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常委", "is_correct": true, "explanation": "常委是有决策权的成员，能够讨论预算，与句意相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能讨论预算，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不能讨论预算。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讨论”的主语须是人或群体，“窗户”不能搭配。"}], "explanations": {"常委": "常委是有决策权的成员，能够讨论预算，与句意相符。", "小猫": "语义：小猫不能讨论预算，与句意矛盾。", "石头": "语义：石头是无生命的东西，不能讨论预算。", "窗户": "搭配：“讨论”的主语须是人或群体，“窗户”不能搭配。"}, "sentence_index": 6, "correct_answer": "常委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的常委做的菜很好吃。", "explanation": "这里应该用〈厨师〉。做菜的人是厨师，“常委”是常务委员会的委员。"}, {"text": "常委把信送到了我家门口。", "explanation": "这里应该用〈邮递员〉。送信的人是邮递员，“常委”是常务委员会的委员。"}, {"text": "这瓶药的常委上写着一天吃三次。", "explanation": "这里应该用〈说明书〉。写用法的是说明书，“常委”指人，不是文字材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只常委每周一都要主持例会。", "corrected_sentence": "这位常委每周一都要主持例会。", "error_description": "量词错误：“常委”指人，应用量词“位”，不能用“只”。正确说法是“这位常委”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "常委的们明天都会到齐。", "corrected_sentence": "常委们明天都会到齐。", "error_description": "词语错误：“常委们”是复数，“们”前面不能加“的”。正确说法是“常委们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
