INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94631, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感觉到是身体或心里知道了一件事。", "primary_collocate": null, "pronunciation": "gǎn jué dào", "ipa": "kan˨˩˦ tɕɥe˧˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "我感觉到肚子有点儿疼。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感觉到心里很难过。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟感觉到有点儿饿了。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一进门就感觉到屋里很热。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你感觉到我的心跳了吗？", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈感觉到我今天不开心。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感觉到自己的脸红了。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在海边，我感觉到风很大。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没感觉到哪里不舒服。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人感觉到脚下有点儿凉。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感觉到了", "label": "完成体"}, {"form": "感觉到过", "label": "经历体"}, {"form": "感觉不到", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "身体或心里知道了一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感觉到", "is_correct": true, "explanation": "「感觉到」表示身体察觉到不适，符合“肚子有点儿疼”的句意。"}, {"text": "通知", "is_correct": false, "explanation": "配价：「通知」需要接受通知的人和通知的内容，“肚子有点儿疼”不能作它的宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能与“肚子有点儿疼”这样的身体状态搭配。"}, {"text": "听", "is_correct": false, "explanation": "语义：「听」是通过耳朵接收声音，不能用来察觉身体的疼痛。"}], "explanations": {"感觉到": "「感觉到」表示身体察觉到不适，符合“肚子有点儿疼”的句意。", "通知": "配价：「通知」需要接受通知的人和通知的内容，“肚子有点儿疼”不能作它的宾语。", "喝": "搭配：「喝」不能与“肚子有点儿疼”这样的身体状态搭配。", "听": "语义：「听」是通过耳朵接收声音，不能用来察觉身体的疼痛。"}, "sentence_index": 0, "correct_answer": "感觉到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感觉到了一首诗。", "explanation": "这里应该用〈写出〉。诗是创作出来的，“感觉到”只表示察觉，不能用于创作。"}, {"text": "妈妈感觉到了一顿晚饭。", "explanation": "这里应该用〈做好〉。晚饭要动手做好，“感觉到”不能表示完成某件事。"}, {"text": "同学们感觉到了一场比赛。", "explanation": "这里应该用〈举办〉。比赛是组织举办的，“感觉到”不能表示组织活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感觉到", "is_correct": true, "explanation": "「感觉到」表示察觉到自己的状态，这里是她察觉到自己脸红，符合句意。"}, {"text": "打听", "is_correct": false, "explanation": "语义：「打听」是询问消息，不能表示察觉自己身体的变化。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」需要被修理的对象和动作，“脸红了”不能作它的宾语。"}, {"text": "答应", "is_correct": false, "explanation": "搭配：「答应」需要被接受的请求或事情，“脸红了”不能作为答应的内容。"}], "explanations": {"感觉到": "「感觉到」表示察觉到自己的状态，这里是她察觉到自己脸红，符合句意。", "打听": "语义：「打听」是询问消息，不能表示察觉自己身体的变化。", "修理": "配价：「修理」需要被修理的对象和动作，“脸红了”不能作它的宾语。", "答应": "搭配：「答应」需要被接受的请求或事情，“脸红了”不能作为答应的内容。"}, "sentence_index": 6, "correct_answer": "感觉到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感觉到了一项作业。", "explanation": "这里应该用〈完成〉。作业要靠动手做完，“感觉到”只表示察觉，不能表示完成某件事。"}, {"text": "设计师感觉到了一座楼。", "explanation": "这里应该用〈设计〉。楼房是设计出来的，“感觉到”不能表示设计。"}, {"text": "工人感觉到了一台机器。", "explanation": "这里应该用〈修好〉。机器要靠修理才能修好，“感觉到”只表示察觉，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天半夜我不感觉到窗外的雨。", "corrected_sentence": "昨天半夜我没感觉到窗外的雨。", "error_description": "叙述过去没有察觉到的事要用“没”，不用“不”，这里应说“没感觉到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚才感觉到着一阵头晕。", "corrected_sentence": "我刚才感觉到了一阵头晕。", "error_description": "错误：“感觉到着”。正确：“感觉到了”。表示察觉已经发生，要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
