INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过感官或心理察觉到某种情况或变化。", "primary_collocate": null, "pronunciation": "gǎn jué dào", "ipa": "kan˨˩˦ tɕɥe˧˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "走进房间，我马上感觉到了一阵冷风。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感觉到有人在后面看着他。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我：你感觉到哪里疼吗？", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感觉到天气一天比一天冷了。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在车里，我感觉到车慢慢停下来了。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感觉到了朋友对她的关心。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手一放进水里，他就感觉到水很烫。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有感觉到任何变化。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子感觉到妈妈有点儿不高兴。", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有感觉到地面在动？", "target_word": "感觉到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感觉到了", "label": "完成体"}, {"form": "感觉到过", "label": "经历体"}, {"form": "感觉不到", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "通过感官或心理察觉到情况或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df093371-859c-466c-bce4-6c56d378b3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感觉到", "is_correct": true, "explanation": "「感觉到」表示通过感官察觉到情况，这里是马上察觉到冷风，符合句意。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：「闻到」是通过嗅觉察觉气味，冷风不能靠鼻子闻到。"}, {"text": "拍下", "is_correct": false, "explanation": "配价：「拍下」要求被拍摄的具体对象，「冷风」无法被拍下。"}, {"text": "喝下", "is_correct": false, "explanation": "搭配：「喝下」搭配饮品，不能与“一阵冷风”搭配。"}], "explanations": {"感觉到": "「感觉到」表示通过感官察觉到情况，这里是马上察觉到冷风，符合句意。", "闻到": "语义：「闻到」是通过嗅觉察觉气味，冷风不能靠鼻子闻到。", "拍下": "配价：「拍下」要求被拍摄的具体对象，「冷风」无法被拍下。", "喝下": "搭配：「喝下」搭配饮品，不能与“一阵冷风”搭配。"}, "sentence_index": 0, "correct_answer": "感觉到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长感觉到了一次郊游。", "explanation": "这里应该用〈组织〉。郊游要靠人组织安排，“感觉到”只表示察觉，不能表示组织活动。"}, {"text": "他感觉到了好成绩，非常高兴。", "explanation": "这里应该用〈取得〉。好成绩要靠努力取得，“感觉到”只表示察觉，不能这样用。"}, {"text": "我感觉到了一个好主意。", "explanation": "这里应该用〈想出〉。主意是靠思考想出来的，“感觉到”只表示察觉已经存在的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感觉到", "is_correct": true, "explanation": "「感觉到」表示察觉到情况，这里是手一放进水里就察觉到水很烫，符合句意。"}, {"text": "泼", "is_correct": false, "explanation": "语义：「泼」是倾倒液体的动作，不能表示察觉水的温度。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：「拒绝」需要接受与否的对象，不能带“水很烫”这样的情况作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "配价：「洗」需要被洗的对象，“水很烫”不能作它的宾语。"}], "explanations": {"感觉到": "「感觉到」表示察觉到情况，这里是手一放进水里就察觉到水很烫，符合句意。", "泼": "语义：「泼」是倾倒液体的动作，不能表示察觉水的温度。", "拒绝": "搭配：「拒绝」需要接受与否的对象，不能带“水很烫”这样的情况作宾语。", "洗": "配价：「洗」需要被洗的对象，“水很烫”不能作它的宾语。"}, "sentence_index": 6, "correct_answer": "感觉到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快感觉到了那项任务。", "explanation": "这里应该用〈完成〉。任务要靠做完，“感觉到”只表示察觉，不能表示完成某事。"}, {"text": "工人们感觉到了一座新大楼。", "explanation": "这里应该用〈建造〉。大楼要靠施工建造，“感觉到”不能用来表示建成。"}, {"text": "他感觉到了一篇作文。", "explanation": "这里应该用〈写出〉。作文是动手写出来的，“感觉到”不能表示创作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在路上感觉到着一阵热风。", "corrected_sentence": "我在路上感觉到了一阵热风。", "error_description": "错误：“感觉到着”。正确：“感觉到了”。表示察觉已经发生，要用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天晚上我不感觉到地震。", "corrected_sentence": "昨天晚上我没感觉到地震。", "error_description": "叙述过去没有察觉到的事要用“没”，不用“不”，这里应说“没感觉到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7019ebcb-aba4-4203-b0b0-62de1bc0eaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战败", "is_correct": true, "explanation": "战败与战胜相对，指在比赛或战斗中输掉，与“这支球队战胜了很多强队”构成反义。"}, {"text": "观察", "is_correct": false, "explanation": "观察是仔细看，与战胜没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行是出门游览，与战胜没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息是停下来放松，与战胜没有反义关系。"}], "correct_answer": "战败", "explanations": {"战败": "战败与战胜相对，指在比赛或战斗中输掉，与“这支球队战胜了很多强队”构成反义。", "观察": "观察是仔细看，与战胜没有反义关系。", "旅行": "旅行是出门游览，与战胜没有反义关系。", "休息": "休息是停下来放松，与战胜没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战败", "is_correct": true, "explanation": "战败与战胜相对，指在比赛或战斗中输掉，与“终于战胜了上次的冠军”构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "修理是使损坏的东西恢复正常，与战胜没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是慢慢走路，与战胜没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考是动脑筋想问题，与战胜没有反义关系。"}], "correct_answer": "战败", "explanations": {"战败": "战败与战胜相对，指在比赛或战斗中输掉，与“终于战胜了上次的冠军”构成反义。", "修理": "修理是使损坏的东西恢复正常，与战胜没有反义关系。", "散步": "散步是慢慢走路，与战胜没有反义关系。", "思考": "思考是动脑筋想问题，与战胜没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "战胜是比赛或打仗时，赢了对方。", "primary_collocate": null, "pronunciation": "zhàn shèng", "ipa": "ʈʂan⁵¹ ʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "中国队战胜了日本队。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的比赛，我们班战胜了三班。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明下棋战胜了他的爸爸。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队去年战胜过很多强队。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝队今天又战胜了红队，得了第一。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网球比赛中战胜了对手。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的军队战胜了敌人。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想战胜那个跑得最快的人。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，弟弟战胜了同学小王。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们练了一年，终于战胜了上次的冠军。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "战胜了", "label": "完成体（了）"}, {"form": "战胜过", "label": "经历体（过）"}], "register": "中性", "sense_fingerprint": "战胜：比赛或打仗中赢了对方队伍或敌人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战胜", "is_correct": true, "explanation": "战胜是比赛中赢了对方，与“中国队”和“日本队”的比赛结果相符。"}, {"text": "辅导", "is_correct": false, "explanation": "语义：辅导是帮助学习，与两队比赛的结果不符。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”的对象应是物品或资源，不能拥有另一支队伍。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：欢送是送别，与比赛胜负不相符。"}], "explanations": {"战胜": "战胜是比赛中赢了对方，与“中国队”和“日本队”的比赛结果相符。", "辅导": "语义：辅导是帮助学习，与两队比赛的结果不符。", "拥有": "搭配：“拥有”的对象应是物品或资源，不能拥有另一支队伍。", "欢送": "语义：欢送是送别，与比赛胜负不相符。"}, "sentence_index": 0, "correct_answer": "战胜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中战胜了奖杯。", "explanation": "这里应该用〈赢得〉。战胜的对象是对手，“奖杯”是比赛中赢得的东西，不能被战胜。"}, {"text": "这支球队去年战胜了好成绩。", "explanation": "这里应该用〈取得〉。战胜的对象是对手，“好成绩”是取得的结果，不能被战胜。"}, {"text": "晚会上，他们战胜了一碗汤。", "explanation": "这里应该用〈喝完〉。战胜的对象是对手，“汤”是喝完的东西，不能被战胜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战胜", "is_correct": true, "explanation": "战胜是打败敌人，与“我们的军队”和“敌人”的战斗叙述相符。"}, {"text": "同情", "is_correct": false, "explanation": "语义：同情是怜惜，与军队打败敌人的叙述相反。"}, {"text": "收养", "is_correct": false, "explanation": "语义：收养是领养子女，与战斗的叙述不符。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：驾临是敬辞，用于尊贵的客人，与战斗叙述的语域不符。"}], "explanations": {"战胜": "战胜是打败敌人，与“我们的军队”和“敌人”的战斗叙述相符。", "同情": "语义：同情是怜惜，与军队打败敌人的叙述相反。", "收养": "语义：收养是领养子女，与战斗的叙述不符。", "驾临": "语域：驾临是敬辞，用于尊贵的客人，与战斗叙述的语域不符。"}, "sentence_index": 6, "correct_answer": "战胜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她努力学习，最后战胜了一等奖学金。", "explanation": "这里应该用〈获得〉。“一等奖学金”是获得的东西，不能被战胜。"}, {"text": "老师战胜了一次郊游。", "explanation": "这里应该用〈组织〉。“郊游”是组织的活动，不能被战胜。"}, {"text": "我们战胜了那张旧报纸。", "explanation": "这里应该用〈搬走〉。战胜的对象是对手，“旧报纸”是被搬走的东西，不能被战胜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队在决赛中不战胜了卫冕冠军。", "corrected_sentence": "我们队在决赛中战胜了卫冕冠军。", "error_description": "“不战胜了”错误。这句是肯定的已完成动作，应说“战胜了”；已完成的否定要说“没战胜”，不能用“不战胜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛中，我们班正在战胜过对手。", "corrected_sentence": "比赛中，我们班正在战胜对手。", "error_description": "“正在…战胜过”错误。“过”表示经历，不能与表示进行中的“正在”同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
