INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94634, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在战争或竞赛中打败对手，取得胜利；也指克服困难或不良情绪。", "primary_collocate": null, "pronunciation": "zhàn shèng", "ipa": "ʈʂan⁵¹ ʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "他战胜了病魔，又回到了学校。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她战胜了心里的害怕，上台唱歌了。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一定能战胜这个困难。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师战胜了病痛，回到了课堂。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李战胜了紧张，考试考得很好。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想战胜自己，每天早上六点起床。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用了两年时间战胜了懒惰。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个运动员战胜过伤病，拿到了冠军。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大雪，工人们战胜了寒冷，修好了路。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她战胜了失败的痛苦，又站了起来。", "target_word": "战胜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "战胜了", "label": "完成体（了）"}, {"form": "战胜过", "label": "经历体（过）"}], "register": "中性", "sense_fingerprint": "战胜：打败对手，也指克服病痛、困难、害怕等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战胜", "is_correct": true, "explanation": "战胜是克服病魔的意思，与“又回到了学校”的结果相符。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”需要有生命的伙伴，不能与病魔搭配。"}, {"text": "同情", "is_correct": false, "explanation": "语义：同情是怜惜他人，与“他……病魔”的说法不合。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”的对象应是人，不能说照顾病魔。"}], "explanations": {"战胜": "战胜是克服病魔的意思，与“又回到了学校”的结果相符。", "陪伴": "搭配：“陪伴”需要有生命的伙伴，不能与病魔搭配。", "同情": "语义：同情是怜惜他人，与“他……病魔”的说法不合。", "照顾": "搭配：“照顾”的对象应是人，不能说照顾病魔。"}, "sentence_index": 0, "correct_answer": "战胜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在决赛中战胜了荣誉。", "explanation": "这里应该用〈赢得〉。战胜的对象是对手或困难，“荣誉”是赢得的东西，不能被战胜。"}, {"text": "她在考试中战胜了好成绩。", "explanation": "这里应该用〈取得〉。战胜的对象是对手或困难，“好成绩”是取得的结果，不能被战胜。"}, {"text": "工人们战胜了那台新电梯。", "explanation": "这里应该用〈安装〉。战胜的对象是对手或困难，“电梯”是安装的东西，不能被战胜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战胜", "is_correct": true, "explanation": "战胜是克服懒惰的意思，与“用了两年时间”的叙述相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏是喜爱赞许，与懒惰这种不良习惯相悖。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”的对象是可以选择的东西，懒惰不能被挑选。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象应是人，不能说拜访懒惰。"}], "explanations": {"战胜": "战胜是克服懒惰的意思，与“用了两年时间”的叙述相符。", "欣赏": "语义：欣赏是喜爱赞许，与懒惰这种不良习惯相悖。", "挑选": "搭配：“挑选”的对象是可以选择的东西，懒惰不能被挑选。", "拜访": "搭配：“拜访”的对象应是人，不能说拜访懒惰。"}, "sentence_index": 6, "correct_answer": "战胜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他努力训练，最后战胜了金牌。", "explanation": "这里应该用〈夺得〉。战胜的对象是对手或困难，“金牌”是夺得的奖项，不能被战胜。"}, {"text": "他战胜了那张桌子。", "explanation": "这里应该用〈擦干净〉。战胜的对象是对手或困难，“桌子”是擦干净的东西，不能被战胜。"}, {"text": "他战胜了那杯水。", "explanation": "这里应该用〈喝完〉。战胜的对象是对手或困难，“那杯水”不能被战胜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小张终于不战胜了伤痛，重新开始跑步。", "corrected_sentence": "小张终于战胜了伤痛，重新开始跑步。", "error_description": "“不战胜了”错误。这句是肯定的已完成动作，应说“战胜了”；已完成的否定要说“没战胜”，不能用“不战胜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在努力战胜过心中的恐惧。", "corrected_sentence": "他正在努力战胜心中的恐惧。", "error_description": "“正在…战胜过”错误。“过”表示曾经有过的经历，不能与表示进行中的“正在”同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
