INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94635, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手指是手上长着的五根细细的东西。", "primary_collocate": null, "pronunciation": "shǒu zhǐ", "ipa": "ʂoʊ˨˩˦ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的手指又细又长。", "target_word": "手指", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩数着自己的手指。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只手有五根手指。", "target_word": "手指", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天太冷，我的手指都红了。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指上戴着一个小戒指。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的手指很短。", "target_word": "手指", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把手指放在嘴边，说：“别说话。”", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出两根手指，说自己赢了两次。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里人物的手指画得很细。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的左手有一根手指受伤了。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "手指头", "label": "复合"}], "register": "中性", "sense_fingerprint": "手上长着的五根细长的部分，指外形和数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94635, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手指", "is_correct": true, "explanation": "手指（shǒu zhǐ）：手上长着的细长部分，是本词的正确答案。"}, {"text": "手织", "is_correct": false, "explanation": "手织（shǒu zhī）与手指第二个字声调不同，意思是用手编织。"}, {"text": "手制", "is_correct": false, "explanation": "手制（shǒu zhì）与手指第二个字声调不同，意思是用手工制作。"}, {"text": "收治", "is_correct": false, "explanation": "收治（shōu zhì）两个字的声调都与手指不同，意思是收容并治疗病人。"}, {"text": "守职", "is_correct": false, "explanation": "守职（shǒu zhí）第二个字声调不同，意思是守住自己的职位。"}, {"text": "手执", "is_correct": false, "explanation": "手执（shǒu zhí）第二个字声调不同，意思是用手拿着。"}], "explanations": {"手指": "手指（shǒu zhǐ）：手上长着的细长部分，是本词的正确答案。", "手织": "手织（shǒu zhī）与手指第二个字声调不同，意思是用手编织。", "手制": "手制（shǒu zhì）与手指第二个字声调不同，意思是用手工制作。", "收治": "收治（shōu zhì）两个字的声调都与手指不同，意思是收容并治疗病人。", "守职": "守职（shǒu zhí）第二个字声调不同，意思是守住自己的职位。", "手执": "手执（shǒu zhí）第二个字声调不同，意思是用手拿着。"}, "sentence_index": null, "correct_answer": "手指"}, "level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "手指：手上细长的部分，“又细又长”正好描写它。"}, {"text": "拳头", "is_correct": false, "explanation": "体貌：拳头是握紧的手，粗短而不细长，不能说又细又长。"}, {"text": "手掌", "is_correct": false, "explanation": "体貌：手掌宽而平，不能用“又细又长”来形容。"}, {"text": "手心", "is_correct": false, "explanation": "搭配：“又细又长”多形容手指、胳膊等细长部位，手心不这样搭配。"}], "explanations": {"手指": "手指：手上细长的部分，“又细又长”正好描写它。", "拳头": "体貌：拳头是握紧的手，粗短而不细长，不能说又细又长。", "手掌": "体貌：手掌宽而平，不能用“又细又长”来形容。", "手心": "搭配：“又细又长”多形容手指、胳膊等细长部位，手心不这样搭配。"}, "sentence_index": 0, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的右手有一头手指肿了。", "explanation": "这里应该用〈根〉。“头”多用于大牲畜，手指计量要用“根”。"}, {"text": "我戴着手指出门了。", "explanation": "这里应该用〈手套〉。戴的是手套，手指是手的一部分，不能戴。"}, {"text": "他的手上有一双手指受伤了。", "explanation": "这里应该用〈根〉。“双”用于成对的东西，手指计量要用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94635, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手指", "is_correct": true, "explanation": "手指（shǒu zhǐ）：手上长着的细长部分，是本词的正确答案。"}, {"text": "受制", "is_correct": false, "explanation": "受制（shòu zhì）两个字的声调都与手指不同，意思是受到控制。"}, {"text": "授职", "is_correct": false, "explanation": "授职（shòu zhí）两个字的声调都与手指不同，意思是授予职位。"}, {"text": "收执", "is_correct": false, "explanation": "收执（shōu zhí）两个字的声调都与手指不同，意思是收据或回执。"}], "explanations": {"手指": "手指（shǒu zhǐ）：手上长着的细长部分，是本词的正确答案。", "受制": "受制（shòu zhì）两个字的声调都与手指不同，意思是受到控制。", "授职": "授职（shòu zhí）两个字的声调都与手指不同，意思是授予职位。", "收执": "收执（shōu zhí）两个字的声调都与手指不同，意思是收据或回执。"}, "sentence_index": null, "correct_answer": "手指"}, "level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "手指：把它放在嘴边是常见的“别出声”手势，句意通顺。"}, {"text": "嘴唇", "is_correct": false, "explanation": "语义：嘴唇本身就长在嘴上，不能再把它放在嘴边。"}, {"text": "脚趾", "is_correct": false, "explanation": "搭配：“放在嘴边”的手势要靠手完成，脚趾不搭配。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛长在脸上，不能被单独放到嘴边，句子说不通。"}], "explanations": {"手指": "手指：把它放在嘴边是常见的“别出声”手势，句意通顺。", "嘴唇": "语义：嘴唇本身就长在嘴上，不能再把它放在嘴边。", "脚趾": "搭配：“放在嘴边”的手势要靠手完成，脚趾不搭配。", "眼睛": "语义：眼睛长在脸上，不能被单独放到嘴边，句子说不通。"}, "sentence_index": 6, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天剪手指，把指甲修得很短。", "explanation": "这里应该用〈指甲〉。手指是身体部位，不能剪；要修剪的是指甲。"}, {"text": "他把衬衫的手指扣好了。", "explanation": "这里应该用〈纽扣〉。扣的是纽扣，手指不能扣在衣服上。"}, {"text": "她的手上有一片手指受伤了。", "explanation": "这里应该用〈根〉。“片”多用于平面的东西，手指计量要用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一块手指按下了电梯的按钮。", "corrected_sentence": "他用一根手指按下了电梯的按钮。", "error_description": "量词错误：手指应该用“根”计量，“块”用于块状的东西，正确说法是“一根手指”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子伸出一张手指，告诉我他一岁了。", "corrected_sentence": "孩子伸出一根手指，告诉我他一岁了。", "error_description": "量词错误：“张”用于平而薄的东西，手指应该用“根”计量，正确说法是“一根手指”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
