INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手掌前端能够活动的五个分支，用来抓、拿和触摸东西。", "primary_collocate": null, "pronunciation": "shǒu zhǐ", "ipa": "ʂoʊ˨˩˦ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他用手指拿起一颗小豆子。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲人用手指摸字，就能读书。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手指在键盘上飞快地动着。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝用手指抓住了妈妈的衣服。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹钢琴要用手指一个一个地按。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指碰了碰桌上的花。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手指不灵活，就拿不好筷子。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手指轻轻摸着小猫的头。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手指按了按他的肚子。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手指一动，手机屏幕就亮了。", "target_word": "手指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "手指头", "label": "复合"}], "register": "中性", "sense_fingerprint": "能活动、用来抓拿触摸的手的分支，指功能和动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94636, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手指", "is_correct": true, "explanation": "手指（shǒu zhǐ）：手掌前端能活动的分支，是本词的正确答案。"}, {"text": "手织", "is_correct": false, "explanation": "手织（shǒu zhī）与手指第二个字声调不同，意思是用手编织。"}, {"text": "手制", "is_correct": false, "explanation": "手制（shǒu zhì）与手指第二个字声调不同，意思是用手工制作。"}, {"text": "收治", "is_correct": false, "explanation": "收治（shōu zhì）两个字的声调都与手指不同，意思是收容并治疗病人。"}, {"text": "守职", "is_correct": false, "explanation": "守职（shǒu zhí）第二个字声调不同，意思是守住自己的职位。"}, {"text": "手执", "is_correct": false, "explanation": "手执（shǒu zhí）第二个字声调不同，意思是用手拿着。"}], "explanations": {"手指": "手指（shǒu zhǐ）：手掌前端能活动的分支，是本词的正确答案。", "手织": "手织（shǒu zhī）与手指第二个字声调不同，意思是用手编织。", "手制": "手制（shǒu zhì）与手指第二个字声调不同，意思是用手工制作。", "收治": "收治（shōu zhì）两个字的声调都与手指不同，意思是收容并治疗病人。", "守职": "守职（shǒu zhí）第二个字声调不同，意思是守住自己的职位。", "手执": "手执（shǒu zhí）第二个字声调不同，意思是用手拿着。"}, "sentence_index": null, "correct_answer": "手指"}, "level_3": {"options": [{"text": "手指", "is_correct": true, "explanation": "手指：能抓拿小东西的部位，“用……拿起”正好接它。"}, {"text": "拳头", "is_correct": false, "explanation": "语义：拳头是握紧的手，不能用来拿起小豆子。"}, {"text": "胳膊", "is_correct": false, "explanation": "搭配：拿东西要用手或手指，不说用胳膊拿起小东西。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子不能拿东西，与“拿起”的动作矛盾。"}], "explanations": {"手指": "手指：能抓拿小东西的部位，“用……拿起”正好接它。", "拳头": "语义：拳头是握紧的手，不能用来拿起小豆子。", "胳膊": "搭配：拿东西要用手或手指，不说用胳膊拿起小东西。", "鼻子": "语义：鼻子不能拿东西，与“拿起”的动作矛盾。"}, "sentence_index": 0, "correct_answer": "手指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用手指搂着孩子。", "explanation": "这里应该用〈胳膊〉。搂抱要用胳膊，手指无法完成搂的动作。"}, {"text": "他用手指咬住了面包。", "explanation": "这里应该用〈嘴巴〉。咬东西要用嘴巴，手指不能咬。"}, {"text": "他用一把手指按下了开关。", "explanation": "这里应该用〈根〉。“把”用于有柄的东西，手指计量要用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
