INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接", "is_correct": true, "explanation": "接：伸手承住飞来的东西，与“扔”（抛出去）是反义关系。"}, {"text": "踢", "is_correct": false, "explanation": "踢是用脚撞击，与“扔”没有反义关系。"}, {"text": "推", "is_correct": false, "explanation": "推是用力使物体移动，与“扔”没有反义关系。"}, {"text": "拍", "is_correct": false, "explanation": "拍是用手轻击，与“扔”没有反义关系。"}], "correct_answer": "接", "explanations": {"接": "接：伸手承住飞来的东西，与“扔”（抛出去）是反义关系。", "踢": "踢是用脚撞击，与“扔”没有反义关系。", "推": "推是用力使物体移动，与“扔”没有反义关系。", "拍": "拍是用手轻击，与“扔”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
