INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扔是用手把东西丢出去。", "primary_collocate": null, "pronunciation": "rēng", "ipa": "ɻɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他把球扔给了我。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩把石头扔进河里。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把球扔过来。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我扔了一个球给小狗。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把书包扔在沙发上。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别往窗外扔东西。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用力扔出了那个球。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢扔飞盘玩。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在公园里扔着雪球。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候常在河边扔石头。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔了", "label": "体标"}, {"form": "扔过", "label": "体标"}, {"form": "扔着", "label": "体标"}, {"form": "扔一扔", "label": "重叠"}], "register": "口语", "sense_fingerprint": "用手把东西抛向别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb53a5c-65d7-4ea3-9d02-709f50e00d34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔（rēng）：用手把东西丢出去。"}, {"text": "灯", "is_correct": false, "explanation": "扔 rēng 与 灯 dēng 声母不同（r / d），灯的意思是灯。"}, {"text": "坑", "is_correct": false, "explanation": "扔 rēng 与 坑 kēng 声母不同（r / k），坑的意思是坑洞。"}, {"text": "争", "is_correct": false, "explanation": "扔 rēng 与 争 zhēng 声母不同（r / zh），争的意思是争夺。"}], "explanations": {"扔": "扔（rēng）：用手把东西丢出去。", "灯": "扔 rēng 与 灯 dēng 声母不同（r / d），灯的意思是灯。", "坑": "扔 rēng 与 坑 kēng 声母不同（r / k），坑的意思是坑洞。", "争": "扔 rēng 与 争 zhēng 声母不同（r / zh），争的意思是争夺。"}, "sentence_index": null, "correct_answer": "扔"}, "level_3": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔：把球抛给对方，符合“把球……给了我”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝是把液体咽下去，球不能喝，“把球喝给了我”不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发出声音，不能用于递送球。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，不是把球递给别人。"}], "explanations": {"扔": "扔：把球抛给对方，符合“把球……给了我”的语境。", "喝": "语义：喝是把液体咽下去，球不能喝，“把球喝给了我”不通。", "唱": "语义：唱是发出声音，不能用于递送球。", "咬": "语义：咬是用牙齿夹住，不是把球递给别人。"}, "sentence_index": 0, "correct_answer": "扔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用脚把球扔进了球门。", "explanation": "这里应该用〈踢〉。扔是用手把东西丢出去，用脚把球送进球门要用〈踢〉，不说〈扔〉。"}, {"text": "他把一盆水扔进了河里。", "explanation": "这里应该用〈倒〉。扔是用手把东西丢出去，水是液体，不能用扔，要说〈倒〉。"}, {"text": "他轻轻地把杯子扔在桌上。", "explanation": "这里应该用〈放〉。扔带有用力抛出的动作，“轻轻”放置要用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔（rēng）：用手把东西丢出去。"}, {"text": "哼", "is_correct": false, "explanation": "扔 rēng 与 哼 hēng 声母不同（r / h），哼的意思是哼唱。"}, {"text": "生", "is_correct": false, "explanation": "扔 rēng 与 生 shēng 声母不同（r / sh），生的意思是出生。"}, {"text": "峰", "is_correct": false, "explanation": "扔 rēng 与 峰 fēng 声母不同（r / f），峰的意思是山峰。"}], "explanations": {"扔": "扔（rēng）：用手把东西丢出去。", "哼": "扔 rēng 与 哼 hēng 声母不同（r / h），哼的意思是哼唱。", "生": "扔 rēng 与 生 shēng 声母不同（r / sh），生的意思是出生。", "峰": "扔 rēng 与 峰 fēng 声母不同（r / f），峰的意思是山峰。"}, "sentence_index": null, "correct_answer": "扔"}, "level_3": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔：用力把球抛出去，符合“用力……出了那个球”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“出”连用来表示球被抛出。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热食物，不能用来抛出球。"}, {"text": "眨", "is_correct": false, "explanation": "语义：眨是眼睛的动作，不能用于抛出球。"}], "explanations": {"扔": "扔：用力把球抛出去，符合“用力……出了那个球”的语境。", "吃": "搭配：“吃”不能与“出”连用来表示球被抛出。", "煮": "语义：煮是加热食物，不能用来抛出球。", "眨": "语义：眨是眼睛的动作，不能用于抛出球。"}, "sentence_index": 6, "correct_answer": "扔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我小时候常在河边扔一朵云。", "explanation": "这里应该用〈看〉。扔是用手把东西丢出去，云不能扔，在河边看云要说〈看〉。"}, {"text": "我小时候常在河边扔一头牛。", "explanation": "这里应该用〈牵〉。扔是用手把东西丢出去，牛太大，不能这样扔，要说〈牵〉。"}, {"text": "我小时候常在河边扔一座房子。", "explanation": "这里应该用〈拆〉。扔是用手把东西丢出去，房子不能这样扔，要说〈拆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
