INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扔是把不要的东西丢掉。", "primary_collocate": null, "pronunciation": "rēng", "ipa": "ɻɤŋ˥", "syllable_count": 1, "sentences": [{"text": "这件旧衣服我想扔了。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把垃圾扔在地上。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把坏了的手机扔了。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些东西还有用，别扔。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把没吃完的饭扔了。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把空瓶子扔进垃圾桶。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧书扔了太可惜。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不扔旧东西。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么把我的画扔了？", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过期的牛奶要扔掉。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔了", "label": "体标"}, {"form": "扔过", "label": "体标"}, {"form": "扔掉", "label": "复合"}], "register": "口语", "sense_fingerprint": "把不要的东西丢掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb53a5c-65d7-4ea3-9d02-709f50e00d34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔（rēng）：把不要的东西丢掉。"}, {"text": "灯", "is_correct": false, "explanation": "扔 rēng 与 灯 dēng 声母不同（r / d），灯的意思是灯。"}, {"text": "坑", "is_correct": false, "explanation": "扔 rēng 与 坑 kēng 声母不同（r / k），坑的意思是坑洞。"}, {"text": "争", "is_correct": false, "explanation": "扔 rēng 与 争 zhēng 声母不同（r / zh），争的意思是争夺。"}], "explanations": {"扔": "扔（rēng）：把不要的东西丢掉。", "灯": "扔 rēng 与 灯 dēng 声母不同（r / d），灯的意思是灯。", "坑": "扔 rēng 与 坑 kēng 声母不同（r / k），坑的意思是坑洞。", "争": "扔 rēng 与 争 zhēng 声母不同（r / zh），争的意思是争夺。"}, "sentence_index": null, "correct_answer": "扔"}, "level_3": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔：丢掉，符合“这件旧衣服我想……了”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：衣服不能吃，“想吃了”与句意矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“旧衣服”搭配。"}, {"text": "讲", "is_correct": false, "explanation": "语义：衣服不能讲话，“想讲了”不通。"}], "explanations": {"扔": "扔：丢掉，符合“这件旧衣服我想……了”的语境。", "吃": "语义：衣服不能吃，“想吃了”与句意矛盾。", "喝": "搭配：“喝”不能与“旧衣服”搭配。", "讲": "语义：衣服不能讲话，“想讲了”不通。"}, "sentence_index": 0, "correct_answer": "扔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这块手表扔了，因为我每天都戴着它。", "explanation": "这里应该用〈留着〉。扔是丢掉、不要了，句中却说每天都戴着，前后矛盾，应说〈留着〉。"}, {"text": "我把刚买的新书扔了，因为我很想看它。", "explanation": "这里应该用〈留着〉。扔是丢掉、不要了，句中却说很想看，前后矛盾，应说〈留着〉。"}, {"text": "这些书我想扔掉，因为我还要天天看。", "explanation": "这里应该用〈留着〉。扔是丢弃、不要了，这句话说要丢掉、又说还要天天看，前后矛盾，应说〈留着〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94638, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔（rēng）：把不要的东西丢掉。"}, {"text": "哼", "is_correct": false, "explanation": "扔 rēng 与 哼 hēng 声母不同（r / h），哼的意思是哼唱。"}, {"text": "生", "is_correct": false, "explanation": "扔 rēng 与 生 shēng 声母不同（r / sh），生的意思是出生。"}, {"text": "峰", "is_correct": false, "explanation": "扔 rēng 与 峰 fēng 声母不同（r / f），峰的意思是山峰。"}], "explanations": {"扔": "扔（rēng）：把不要的东西丢掉。", "哼": "扔 rēng 与 哼 hēng 声母不同（r / h），哼的意思是哼唱。", "生": "扔 rēng 与 生 shēng 声母不同（r / sh），生的意思是出生。", "峰": "扔 rēng 与 峰 fēng 声母不同（r / f），峰的意思是山峰。"}, "sentence_index": null, "correct_answer": "扔"}, "level_3": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔：丢掉，符合“旧书……了太可惜”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：书不能唱，“旧书唱了太可惜”不通。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能以“旧书”为主语。"}, {"text": "笑", "is_correct": false, "explanation": "语义：书不会笑，与句意矛盾。"}], "explanations": {"扔": "扔：丢掉，符合“旧书……了太可惜”的语境。", "唱": "语义：书不能唱，“旧书唱了太可惜”不通。", "跳": "搭配：“跳”不能以“旧书”为主语。", "笑": "语义：书不会笑，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "扔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过期的牛奶要扔进冰箱。", "explanation": "这里应该用〈放〉。扔是丢掉或用力抛出，放进冰箱要用〈放〉。"}, {"text": "这些旧书可以扔到邮局寄走。", "explanation": "这里应该用〈寄〉。扔是丢弃或用手抛出，把东西送到邮局寄走要用〈寄〉。"}, {"text": "这块旧布我用来扔在地上当垫子。", "explanation": "这里应该用〈铺〉。扔是丢弃或用力抛出，布铺在地上当垫子要用〈铺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧玩具掉扔了。", "corrected_sentence": "他把旧玩具扔掉了。", "error_description": "复合词语序错误：“扔掉”是动词加结果补语，应说“扔掉了”，不能把“掉”放在“扔”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双旧鞋我已经扔了了。", "corrected_sentence": "这双旧鞋我已经扔了。", "error_description": "体标错误：“扔了”的“了”只用一次，“扔了了”重复了完成体标记。正确说法是“扔了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
