INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因为不满意而在言语中责怪别人或表达不满。", "primary_collocate": null, "pronunciation": "bào yuàn", "ipa": "pɑʊ̯˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "客人抱怨饭菜太咸，服务员马上道歉。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人抱怨这里的路太窄。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对工资不满意，常常抱怨。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抱怨房间太小，晚上睡不好。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "与其抱怨，不如想办法解决。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生抱怨考试太难。", "target_word": "抱怨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从来不抱怨工作累。", "target_word": "抱怨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气这么热，大家都在抱怨。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板听到有人抱怨，就问发生了什么事。", "target_word": "抱怨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抱怨着说，这家店的东西越来越贵了。", "target_word": "抱怨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抱怨了", "label": "体标"}, {"form": "抱怨着", "label": "体标"}, {"form": "抱怨过", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：因不满意而用言语责怪或表达不满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbde994-dc07-4f05-b67a-7432fadb09bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抱怨", "is_correct": true, "explanation": "“抱怨”表示因不满意而说出来，与“饭菜太咸”和后面服务员道歉的情境相符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，饭菜太咸不值得赞美。"}, {"text": "称赞", "is_correct": false, "explanation": "语义：“称赞”是说好，与“太咸”相矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示因受到好处而感激，饭菜太咸不值得感谢。"}], "explanations": {"抱怨": "“抱怨”表示因不满意而说出来，与“饭菜太咸”和后面服务员道歉的情境相符。", "赞美": "语义：“赞美”是称赞，饭菜太咸不值得赞美。", "称赞": "语义：“称赞”是说好，与“太咸”相矛盾。", "感谢": "语义：“感谢”表示因受到好处而感激，饭菜太咸不值得感谢。"}, "sentence_index": 0, "correct_answer": "抱怨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她抱怨那幅画画得很好。", "explanation": "这里应该用〈赞叹〉。抱怨表示不满，不能用来赞叹画得好。"}, {"text": "班长抱怨我的作业写得很认真。", "explanation": "这里应该用〈表扬〉。抱怨表示不满，不能用来夸作业写得认真。"}, {"text": "我抱怨他帮我修好了电脑。", "explanation": "这里应该用〈感谢〉。抱怨表示不满，不能用来说别人的帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抱怨", "is_correct": true, "explanation": "“抱怨”表示因不满而说出来，“从来不……”说明他从不这样说，与“工作累”相符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示以某事为乐，工作累不是可以享受的事。"}, {"text": "庆幸", "is_correct": false, "explanation": "语义：“庆幸”是为好事而高兴，与“工作累”不相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是人或事物，不能带“工作累”这样的状态作宾语。"}], "explanations": {"抱怨": "“抱怨”表示因不满而说出来，“从来不……”说明他从不这样说，与“工作累”相符。", "享受": "语义：“享受”表示以某事为乐，工作累不是可以享受的事。", "庆幸": "语义：“庆幸”是为好事而高兴，与“工作累”不相符。", "欣赏": "搭配：“欣赏”的对象是人或事物，不能带“工作累”这样的状态作宾语。"}, "sentence_index": 6, "correct_answer": "抱怨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们抱怨他考试考得很好。", "explanation": "这里应该用〈祝贺〉。抱怨表示不满，不能用来向别人的好成绩表示祝贺。"}, {"text": "老板抱怨他的方案想得很周到。", "explanation": "这里应该用〈夸奖〉。抱怨表示不满，不能用来夸方案想得周到。"}, {"text": "他抱怨朋友的礼物送得很用心。", "explanation": "这里应该用〈赞美〉。抱怨表示不满，不能用来赞美礼物用心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她往房东抱怨房间太旧。", "corrected_sentence": "她向房东抱怨房间太旧。", "error_description": "错误形式：“往房东抱怨”，介词用错。正确形式：“向房东抱怨”。“向”引出抱怨的对象，“往”表示动作的方向，不用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抱怨地很厉害，大家都听烦了。", "corrected_sentence": "他抱怨得很厉害，大家都听烦了。", "error_description": "错误形式：“抱怨地很厉害”。正确形式：“抱怨得很厉害”。“得”用在动词后引出补语，“地”用在动词前作状语，这里用“地”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be7d62e-0db1-46b6-9471-55a6a7c88968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
