INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94641, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接收是把别人送来的东西拿到手里。", "primary_collocate": null, "pronunciation": "jiē shōu", "ipa": "tɕjɛ⁵⁵ ʂoʊ⁵⁵", "syllable_count": 2, "sentences": [{"text": "快递员把包裹送到家，我接收了。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的保安帮我接收了一个包裹。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在这里签字，然后接收文件。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出门了，邻居替她接收了快递。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师接收了同学们交来的作业。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出双手，接收了朋友送的礼物。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库今天上午接收了一批新货。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不在家，朋友会帮我接收信件。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在接收大家送来的行李。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收件人要亲自接收这封信。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接收了", "label": "完成体"}, {"form": "接收过", "label": "经历体"}, {"form": "接收着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "亲手收下别人送来的实物，如快递、包裹、文件、信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接收", "is_correct": true, "explanation": "正确。“接收”指亲手收下送来的包裹，与前句“送到家”相合。"}, {"text": "寄出", "is_correct": false, "explanation": "语义：“寄出”指把东西发出去，与“包裹送到家”的方向相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃包裹就是不要它，与“送到家”之后的结果不相合。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于音视频，不用于包裹。"}], "explanations": {"接收": "正确。“接收”指亲手收下送来的包裹，与前句“送到家”相合。", "寄出": "语义：“寄出”指把东西发出去，与“包裹送到家”的方向相反。", "放弃": "语义：放弃包裹就是不要它，与“送到家”之后的结果不相合。", "播放": "搭配：“播放”用于音视频，不用于包裹。"}, "sentence_index": 0, "correct_answer": "接收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在家接收了朋友，一起吃了晚饭。", "explanation": "这里应该用〈接待〉。接收指收下别人送来的东西，在家招待朋友要说“接待”。"}, {"text": "他把房间接收得很干净。", "explanation": "这里应该用〈收拾〉。接收指收下送来的东西，整理房间要说“收拾”。"}, {"text": "我在超市接收了一瓶牛奶。", "explanation": "这里应该用〈购买〉。接收指收下别人送来的东西，花钱买东西要说“购买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接收", "is_correct": true, "explanation": "正确。“接收”指仓库收下送来的一批货，与“今天上午”和“新货”相合。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译针对文字，不能用于货物，句子说不通。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：“朗读”的对象是文字，不说朗读货物。"}, {"text": "吃", "is_correct": false, "explanation": "语义：仓库不会吃货物，这个动词无法接“一批新货”。"}], "explanations": {"接收": "正确。“接收”指仓库收下送来的一批货，与“今天上午”和“新货”相合。", "翻译": "语义：翻译针对文字，不能用于货物，句子说不通。", "朗读": "搭配：“朗读”的对象是文字，不说朗读货物。", "吃": "语义：仓库不会吃货物，这个动词无法接“一批新货”。"}, "sentence_index": 6, "correct_answer": "接收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他诚恳地接收了老师的批评。", "explanation": "这里应该用〈接受〉。接收多指收下实物、信息或人员，批评这类抽象内容要说“接受”。"}, {"text": "他把新作品接收给大家。", "explanation": "这里应该用〈展示〉。接收指收下送来的东西，把作品拿给别人看要说“展示”。"}, {"text": "他弯腰接收了地上的书。", "explanation": "这里应该用〈拿起〉。接收指收下送来的东西，弯腰从地上拿书要说“拿起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在门口签了字，然后接收了了包裹。", "corrected_sentence": "我在门口签了字，然后接收了包裹。", "error_description": "“了”重复：一个动词后只用一个“了”，“接收了了包裹”应改为“接收了包裹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经那封信接收了。", "corrected_sentence": "我已经把那封信接收了。", "error_description": "“把”字句中，处置对象前必须有“把”，省去“把”不成立，应说“我已经把那封信接收了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
