INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94642, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收下送来的东西、信息或人员，表示接受。", "primary_collocate": null, "pronunciation": "jiē shōu", "ipa": "tɕjɛ⁵⁵ ʂoʊ⁵⁵", "syllable_count": 2, "sentences": [{"text": "手机正在接收新的信息。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视接收不到信号，屏幕黑了。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校今年接收了两百名新生。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的医院接收了很多病人。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收音机能接收很多电台的节目。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的邮箱每天接收几十封邮件。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方接收过不少外地来的学生。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星把信号送来，地面站负责接收。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文件发到我的邮箱，我马上接收。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司接收了几名外国员工。", "target_word": "接收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接收了", "label": "完成体"}, {"form": "接收过", "label": "经历体"}, {"form": "接收着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "机构或设备收下并接纳信息、信号、邮件、新生、病人等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接收", "is_correct": true, "explanation": "正确。“接收”指设备收下传来的信息，与“手机正在”相合。"}, {"text": "切割", "is_correct": false, "explanation": "语义：手机不能切割信息，“切割”的对象是实物。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪的对象是食物，用在手机和信息上说不通。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于枝叶、头发，不说修剪信息。"}], "explanations": {"接收": "正确。“接收”指设备收下传来的信息，与“手机正在”相合。", "切割": "语义：手机不能切割信息，“切割”的对象是实物。", "烹饪": "语义：烹饪的对象是食物，用在手机和信息上说不通。", "修剪": "搭配：“修剪”多用于枝叶、头发，不说修剪信息。"}, "sentence_index": 0, "correct_answer": "接收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一直接收他的决定。", "explanation": "这里应该用〈接受〉。接收指收下送来的东西、信息或人员，同意别人的决定要说“接受”。"}, {"text": "医生正在接收他的身体。", "explanation": "这里应该用〈检查〉。接收指收下送来的东西、信息或人员，给身体做诊断要说“检查”。"}, {"text": "他一口气接收了三碗饭。", "explanation": "这里应该用〈吃〉。接收指收下送来的东西、信息或人员，吃饭要说“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接收", "is_correct": true, "explanation": "正确。“接收过”表示此地曾收纳过不少外地学生，与句意相合。"}, {"text": "扫除", "is_correct": false, "explanation": "搭配：“扫除”常搭配障碍、污垢，不说扫除学生。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：粉刷的对象是墙面，“粉刷学生”说不通。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：清洁的对象是环境或物体，不用于学生。"}], "explanations": {"接收": "正确。“接收过”表示此地曾收纳过不少外地学生，与句意相合。", "扫除": "搭配：“扫除”常搭配障碍、污垢，不说扫除学生。", "粉刷": "语义：粉刷的对象是墙面，“粉刷学生”说不通。", "清洁": "语义：清洁的对象是环境或物体，不用于学生。"}, "sentence_index": 6, "correct_answer": "接收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们接收了美好的假期。", "explanation": "这里应该用〈享受〉。接收指收下送来的东西、信息或人员，对假期的感受要说“享受”。"}, {"text": "他接收了很大的压力。", "explanation": "这里应该用〈承受〉。接收用于物品、信息或人员，压力、痛苦等要说“承受”。"}, {"text": "她接收干净了桌子。", "explanation": "这里应该用〈擦〉。接收指收下送来的东西、信息或人员，擦桌子要说“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院接收过过很多病人。", "corrected_sentence": "这家医院接收过很多病人。", "error_description": "“过”重复：经历体只用一个“过”，“接收过过很多病人”应改为“接收过很多病人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校正在接收了新生。", "corrected_sentence": "这所学校正在接收新生。", "error_description": "“正在”表示动作正在进行，不能与“了”同用，应去掉“了”，说“正在接收新生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
