INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94644, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94644, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用文字把人物、景物或事情的样子具体生动地表现出来。", "primary_collocate": null, "pronunciation": "miáo xiě", "ipa": "miɑʊ˧˥ ɕiɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这篇小说细致地描写了一位老农民。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老舍把北京的冬天描写得很美。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话生动地描写了春天的景色。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小说里描写了自己的家乡。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中描写战争场面的地方让我很难忘。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家描写人物的心理，常常很细。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们描写一个熟悉的人。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗只用四句话，就描写出了秋天的样子。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他描写得很具体，读的人好像看到了那个小村子。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说开头描写了一场大雨。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "描写了", "label": "体标（了）"}, {"form": "描写过", "label": "体标（过）"}, {"form": "描写着", "label": "体标（着）"}, {"form": "描寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "文学写作中具体生动地刻画人物、景物或场面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描写", "is_correct": true, "explanation": "“细致地描写了一位老农民”指用文字具体刻画人物，符合语境。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说参观一位老农民。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能用于人，不能说修理一位老农民。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：小说是文字作品，不能做出“拒绝”这种有意志的行为，句子不通。"}], "explanations": {"描写": "“细致地描写了一位老农民”指用文字具体刻画人物，符合语境。", "参观": "搭配：“参观”的对象是场所或展览，不能说参观一位老农民。", "修理": "搭配：“修理”的对象是器物，不能用于人，不能说修理一位老农民。", "拒绝": "语义：小说是文字作品，不能做出“拒绝”这种有意志的行为，句子不通。"}, "sentence_index": 0, "correct_answer": "描写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生描写了病人的血型。", "explanation": "这里应该用〈检测〉。血型要靠化验检测，描写是把人或景物的样子用文字刻画出来，不用于此。"}, {"text": "这份说明书描写了机器的用法。", "explanation": "这里应该用〈介绍〉。说明书讲解机器的用法属于介绍，不是文学式的生动刻画，描写不用于此。"}, {"text": "他向老师描写了考试的结果。", "explanation": "这里应该用〈报告〉。向老师汇报考试结果要用报告，描写是生动刻画人或景物的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描写", "is_correct": true, "explanation": "“要求我们描写一个熟悉的人”指用文字刻画人物，符合语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，要求我们煮一个人，句子不通。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”的对象是植物或种子，不能说种一个熟悉的人。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于树枝、草坪、头发，不能说修剪一个人。"}], "explanations": {"描写": "“要求我们描写一个熟悉的人”指用文字刻画人物，符合语境。", "煮": "语义：“煮”的对象是食物，要求我们煮一个人，句子不通。", "种": "搭配：“种”的对象是植物或种子，不能说种一个熟悉的人。", "修剪": "搭配：“修剪”多用于树枝、草坪、头发，不能说修剪一个人。"}, "sentence_index": 6, "correct_answer": "描写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家描写了实验的数据。", "explanation": "这里应该用〈记录〉。实验数据要如实记下，描写用于生动刻画人或景物，不用于数据。"}, {"text": "老师描写了这个词的意思。", "explanation": "这里应该用〈解释〉。词义需要讲解说明，描写不用于抽象的意思。"}, {"text": "这个实验描写了他的想法。", "explanation": "这里应该用〈证明〉。实验用来验证想法的对错，描写只用于刻画人或景物的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者把主人公的童年描写的很生动。", "corrected_sentence": "作者把主人公的童年描写得很生动。", "error_description": "错误在补语标记：“描写得很生动”中应用结构助词“得”引出程度补语，学习者常误用“的”，应改为“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家把大海描写的非常生动。", "corrected_sentence": "这位作家把大海描写得非常生动。", "error_description": "错误：“描写的非常生动”。正确：“描写得非常生动”。动词“描写”后引出程度补语要用结构助词“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
