INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "春天是天气变暖、花开草绿的时候。", "primary_collocate": null, "pronunciation": "chūn tiān", "ipa": "ʈʂʰwən⁵⁵ tʰjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "春天到了，花都开了，草也绿了。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的公园里，花开得很漂亮。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天风很轻，不冷也不热。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，小鸟在树上唱歌。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，外面的草绿了，是春天了。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的雨下着，地里的草长出来了。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们春天去山上看花吧。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天里，到处都是绿色。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的太阳暖暖的，很舒服。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的春天很短，花很快就谢了。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个春天", "label": "量词"}, {"form": "春季", "label": "复合"}], "register": "中性", "sense_fingerprint": "天气变暖、花开草绿的时节及其景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冬天", "is_correct": false, "explanation": "语义：冬天草木凋零，不会出现“花都开了，草也绿了”的景象。"}, {"text": "春天", "is_correct": true, "explanation": "正确：指天气变暖、花开草绿的时节，与句中景象相符。"}, {"text": "秋天", "is_correct": false, "explanation": "语义：秋天草木变黄、落叶，不会出现“花都开了，草也绿了”的景象。"}, {"text": "春汛", "is_correct": false, "explanation": "语域：“春汛”是水文专业词，不用于描写花草的日常语境。"}], "explanations": {"冬天": "语义：冬天草木凋零，不会出现“花都开了，草也绿了”的景象。", "春天": "正确：指天气变暖、花开草绿的时节，与句中景象相符。", "秋天": "语义：秋天草木变黄、落叶，不会出现“花都开了，草也绿了”的景象。", "春汛": "语域：“春汛”是水文专业词，不用于描写花草的日常语境。"}, "sentence_index": 0, "correct_answer": "春天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在公园里看见了一只春天。", "explanation": "量词用错：〈只〉用于动物或成件的小物品，不用于季节或时段。“春天”应说“一个春天”。"}, {"text": "我们春天一起吃年夜饭。", "explanation": "这里应该用〈春节〉。“年夜饭”是春节的习俗，“春天”只表示季节，不能代替节日。"}, {"text": "春天吹过脸颊，让人很舒服。", "explanation": "这里应该用〈春风〉。拂过脸颊的风要说“春风”，“春天”指季节，不能作“吹”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春风", "is_correct": false, "explanation": "语义：“春风”指轻柔的风，不是时段名词，不能作“去”的时间状语。"}, {"text": "春天", "is_correct": true, "explanation": "正确：指季节，与“去山上看花”的时间相符。"}, {"text": "春运", "is_correct": false, "explanation": "语义：春运是春节前后的交通运输期，不是用来赏花的时节。"}, {"text": "春色", "is_correct": false, "explanation": "搭配：“去”前面的时间状语应是时段名词，“春色”指景象，不能这样作时间。"}], "explanations": {"春风": "语义：“春风”指轻柔的风，不是时段名词，不能作“去”的时间状语。", "春天": "正确：指季节，与“去山上看花”的时间相符。", "春运": "语义：春运是春节前后的交通运输期，不是用来赏花的时节。", "春色": "搭配：“去”前面的时间状语应是时段名词，“春色”指景象，不能这样作时间。"}, "sentence_index": 6, "correct_answer": "春天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的春天招生从三月开始。", "explanation": "这里应该用〈春季〉。“春季招生”是固定说法，“春天”作“招生”的修饰语不自然。"}, {"text": "她在老家度过了一座春天。", "explanation": "量词用错：〈座〉用于山、楼房等大型固定物，不用于季节。“春天”应说“一个春天”。"}, {"text": "春天是一年中的最后一个季节。", "explanation": "语义错误：春天是一年四季中的第一个季节，最后一个季节是〈冬天〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座春天，燕子也回来了。", "corrected_sentence": "这个春天，燕子也回来了。", "error_description": "量词错误：「春天」是时段，应配〈个〉（这个春天）；〈座〉用于山、楼房等大型固定物，不能用于时段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条春天特别暖和，我们常常去郊外散步。", "corrected_sentence": "这个春天特别暖和，我们常常去郊外散步。", "error_description": "量词错误：「春天」应配〈个〉（这个春天），〈条〉用于细长的东西，不能用于时段。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
