INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年四季中的第一个季节，气候由冷转暖，万物生长。", "primary_collocate": null, "pronunciation": "chūn tiān", "ipa": "ʈʂʰwən⁵⁵ tʰjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "一年有四个季节，春天是第一个。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天过去了，夏天马上就要来了。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的春天比冬天暖和很多。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的季节是春天。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的春天是从三月到五月。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年春天我们搬到了新家。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，天气慢慢变暖。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天以后就是夏天，天气会更热。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年春天都开运动会。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天走了，春天就来了。", "target_word": "春天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个春天", "label": "量词"}, {"form": "春季", "label": "复合"}], "register": "中性", "sense_fingerprint": "四季中排在第一的季节，与夏天、冬天相对而言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd175452-6fce-49e7-ac8e-f0834ea62e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夏天", "is_correct": false, "explanation": "语义：夏天在四季中排第二，不能是“第一个”。"}, {"text": "春天", "is_correct": true, "explanation": "正确：指一年中排在第一位的季节，与“一年有四个季节”相符。"}, {"text": "春秋", "is_correct": false, "explanation": "语域：“春秋”多用于书面或历史语境，指“年岁”或“春秋时代”，不是普通的季节名称。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天是四季中的最后一个，与“第一个”相冲突。"}], "explanations": {"夏天": "语义：夏天在四季中排第二，不能是“第一个”。", "春天": "正确：指一年中排在第一位的季节，与“一年有四个季节”相符。", "春秋": "语域：“春秋”多用于书面或历史语境，指“年岁”或“春秋时代”，不是普通的季节名称。", "冬天": "语义：冬天是四季中的最后一个，与“第一个”相冲突。"}, "sentence_index": 0, "correct_answer": "春天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的春天学期从二月开始。", "explanation": "这里应该用〈春季〉。固定说法是“春季学期”，“春天”不作“学期”的修饰语。"}, {"text": "去年我过了一只很暖和的春天。", "explanation": "量词用错：〈只〉不用于季节或时段，“春天”应配〈个〉，即“一个很暖和的春天”。"}, {"text": "春天吹过来，让人很舒服。", "explanation": "这里应该用〈春风〉。风吹拂要说“春风”，“春天”指季节，不能作“吹”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "盛夏", "is_correct": false, "explanation": "语义：盛夏本已炎热，“天气慢慢变暖”与之矛盾。"}, {"text": "春天", "is_correct": true, "explanation": "正确：指季节，“来了”之后天气慢慢变暖，与春天相符。"}, {"text": "秋天", "is_correct": false, "explanation": "语义：秋天来了天气逐渐变凉，与“慢慢变暖”相反。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚来临时天气转凉，不会“慢慢变暖”。"}], "explanations": {"盛夏": "语义：盛夏本已炎热，“天气慢慢变暖”与之矛盾。", "春天": "正确：指季节，“来了”之后天气慢慢变暖，与春天相符。", "秋天": "语义：秋天来了天气逐渐变凉，与“慢慢变暖”相反。", "夜晚": "语义：夜晚来临时天气转凉，不会“慢慢变暖”。"}, "sentence_index": 6, "correct_answer": "春天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天是一年中最热的季节。", "explanation": "语义错误：春天气候由冷转暖，一年中最热的季节是〈夏天〉。"}, {"text": "我们在山上捡到一块春天。", "explanation": "量词用错：〈块〉用于块状的东西，不用于季节或时段。“春天”应配〈个〉，即“一个春天”。"}, {"text": "医生说，春天流感在三月最多。", "explanation": "这里应该用〈春季〉。“春季流感”是固定说法，“春天”不作“流感”的修饰语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年这只春天我们过得很开心。", "corrected_sentence": "去年这个春天我们过得很开心。", "error_description": "量词错误：「春天」是时段，量词应用“个”（这个春天），不能用“只”（这只春天）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块春天过去以后，天气就热起来了。", "corrected_sentence": "这个春天过去以后，天气就热起来了。", "error_description": "量词错误：「春天」是时段，应配〈个〉（这个春天）；〈块〉用于块状的东西，不能用于时段。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71a433e7-00dd-4be7-a8b5-e777dacf5514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
