INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94651, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违抗", "is_correct": true, "explanation": "正确：“违抗”指故意不听从、反对命令，与“服从”意思相反。"}, {"text": "迎接", "is_correct": false, "explanation": "与“服从”没有反义关系：迎接是迎上去接待。"}, {"text": "观察", "is_correct": false, "explanation": "与“服从”没有反义关系：观察是仔细察看，不表示对立。"}, {"text": "散步", "is_correct": false, "explanation": "与“服从”没有反义关系：散步是随意走走，与听从无关。"}], "correct_answer": "违抗", "explanations": {"违抗": "正确：“违抗”指故意不听从、反对命令，与“服从”意思相反。", "迎接": "与“服从”没有反义关系：迎接是迎上去接待。", "观察": "与“服从”没有反义关系：观察是仔细察看，不表示对立。", "散步": "与“服从”没有反义关系：散步是随意走走，与听从无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
