INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94651, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "服从是听别人的话，照着去做。", "primary_collocate": null, "pronunciation": "fú cóng", "ipa": "fu˧˥ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小狗很服从主人的指挥。", "target_word": "服从", "complexity_tier": "T3", "furigana": "xiǎo gǒu hěn fú cóng zhǔ rén de zhǐ huī", "sentence_source": "generated"}, {"text": "孩子要学会服从老师。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不服从妈妈的安排。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵必须服从队长。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生都服从老师的决定。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一向服从爸爸的命令。", "target_word": "服从", "complexity_tier": "T3", "furigana": "tā yí xiàng fú cóng bà ba de mìng lìng", "sentence_source": "generated"}, {"text": "小明从来不服从大人。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马很服从骑马的人。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要服从大家的决定。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想再服从别人了。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服从了", "label": "体标（了）"}, {"form": "服从过", "label": "体标（过）"}, {"form": "服从性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "服从：听别人的话，按别人说的去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服从", "is_correct": true, "explanation": "正确：“服从”是听从、照着去做，符合小狗听主人指挥的情况。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美需要有判断能力的人作主语，小狗不能赞美主人的指挥。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”的对象是方案或作品，不能说设计指挥。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评要有判断和表达能力，小狗不能批评主人的指挥。"}], "explanations": {"服从": "正确：“服从”是听从、照着去做，符合小狗听主人指挥的情况。", "赞美": "语义：赞美需要有判断能力的人作主语，小狗不能赞美主人的指挥。", "设计": "搭配：“设计”的对象是方案或作品，不能说设计指挥。", "批评": "语义：批评要有判断和表达能力，小狗不能批评主人的指挥。"}, "sentence_index": 0, "correct_answer": "服从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他服从了自己的错误，向大家道歉。", "explanation": "这里应该用〈承认〉。服从是听别人的话去做，表示认下自己的错误要说承认。"}, {"text": "这次他输了比赛，心里却很不服从。", "explanation": "这里应该用〈服气〉。服气指心里认输或佩服，输了比赛后的心理要说不服气；服从是听从，不表示认输。"}, {"text": "这件衣服很服从我的身材。", "explanation": "这里应该用〈合身〉。服从不能形容衣服与身材相合，衣服大小合适要说合身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服从", "is_correct": true, "explanation": "正确：“服从”表示听从大人的话，符合“小明从来不___大人”的语境。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”多用于养育子女，与“大人”搭配不当。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，说小明从来不吃大人是荒谬的。"}, {"text": "生", "is_correct": false, "explanation": "配价：“生”要求子女作宾语，小明不能生大人。"}], "explanations": {"服从": "正确：“服从”表示听从大人的话，符合“小明从来不___大人”的语境。", "抚养": "搭配：“抚养”多用于养育子女，与“大人”搭配不当。", "吃": "语义：“吃”的对象是食物，说小明从来不吃大人是荒谬的。", "生": "配价：“生”要求子女作宾语，小明不能生大人。"}, "sentence_index": 6, "correct_answer": "服从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很服从他的才华。", "explanation": "这里应该用〈佩服〉。服从指听从命令，对别人的才能表示钦佩要用佩服。"}, {"text": "医生让他每天服从两次药。", "explanation": "这里应该用〈服药〉。服从表示听从，吃药要说服药。"}, {"text": "这件毛衣他服从了三年。", "explanation": "这里应该用〈穿〉。服从是听从，不表示穿着衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子服从这张桌子。", "corrected_sentence": "这个孩子服从父母的管教。", "error_description": "错误：“服从”的对象应是人、命令或规定，不能是桌子；应说“服从父母的管教”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
