INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94652, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听从并遵照命令、规则或他人的意志去行动。", "primary_collocate": null, "pronunciation": "fú cóng", "ipa": "fu˧˥ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工作中要服从公司的规定。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵必须服从上级的命令。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数人应该服从多数人的决定。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机要服从交通规则。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在比赛中，选手都服从裁判。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他服从组织的安排，去了山区。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都服从学校的新规定。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人应该服从医生的治疗方案。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不肯服从老板的要求，坚持按自己的方式做。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客要服从工作人员的指挥。", "target_word": "服从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服从了", "label": "体标（了）"}, {"form": "服从过", "label": "体标（过）"}, {"form": "绝对服从", "label": "复合词"}], "register": "中性", "sense_fingerprint": "服从：遵照命令、规则或他人意志行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
