INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服从", "is_correct": true, "explanation": "正确：“服从”表示遵照规定去做，符合“大家都___学校的新规定”的语境。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品或场所，不能说装饰规定。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆、飞机等，不能说驾驶规定。"}, {"text": "喂养", "is_correct": false, "explanation": "配价：“喂养”要求动物或幼儿作宾语，规定不能被喂养。"}], "explanations": {"服从": "正确：“服从”表示遵照规定去做，符合“大家都___学校的新规定”的语境。", "装饰": "搭配：“装饰”的对象是物品或场所，不能说装饰规定。", "驾驶": "搭配：“驾驶”的对象是车辆、飞机等，不能说驾驶规定。", "喂养": "配价：“喂养”要求动物或幼儿作宾语，规定不能被喂养。"}, "sentence_index": 6, "correct_answer": "服从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很服从我的口味。", "explanation": "这里应该用〈符合〉。服从指听从命令或规定，菜合口味要说符合。"}, {"text": "他穿的服从很漂亮。", "explanation": "这里应该用〈服装〉。服从是听从的意思，衣服要说服装，服从不能作名词。"}, {"text": "医生让他每天服从三次药。", "explanation": "这里应该用〈服药〉。服从是听从，吃药要说服药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
