INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94659, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "江是又长又宽的大水路。", "primary_collocate": null, "pronunciation": "jiāng", "ipa": "tɕjɑŋ˥", "syllable_count": 1, "sentences": [{"text": "江又长又宽，船可以在上面走。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家前面有一条江。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐小船过江去买东西。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江上的风很大，我把帽子拿在手里。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条江有很多鱼，爸爸常常去钓。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江的对面是另一个城市。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船慢慢地在江上走着。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥在江上，走过去要十分钟。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子站在桥上，看江里的船。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条江很长，走一天也走不完。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条江", "label": "量词"}, {"form": "江水", "label": "复合"}, {"form": "江边", "label": "复合"}], "register": "中性", "sense_fingerprint": "又长又宽的大水路，船能行走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd836b5-fdf8-41b4-a611-31fbc44b07d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94659, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "江", "is_correct": true, "explanation": "江（jiāng）指又长又宽的大水路，船能行走。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。"}, {"text": "降", "is_correct": false, "explanation": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是降低。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 jiāng 声母不同（x 与 j），意思是香气。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng 与 jiāng 声母不同（q 与 j），意思是枪。"}], "explanations": {"江": "江（jiāng）指又长又宽的大水路，船能行走。", "讲": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。", "降": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是降低。", "香": "xiāng 与 jiāng 声母不同（x 与 j），意思是香气。", "枪": "qiāng 与 jiāng 声母不同（q 与 j），意思是枪。"}, "sentence_index": null, "correct_answer": "江"}, "level_3": {"options": [{"text": "江", "is_correct": true, "explanation": "江指又长又宽的大水路，船可以在上面走，符合句意。"}, {"text": "山", "is_correct": false, "explanation": "语义：山不是能让船在上面行走的水路，“船可以在上面走”与山不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能让船在上面行走，句子说的是水路。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“又长又宽”能形容脸，但船不能在脸上走。"}], "explanations": {"江": "江指又长又宽的大水路，船可以在上面走，符合句意。", "山": "语义：山不是能让船在上面行走的水路，“船可以在上面走”与山不符。", "桌子": "语义：桌子不能让船在上面行走，句子说的是水路。", "脸": "体貌：“又长又宽”能形容脸，但船不能在脸上走。"}, "sentence_index": 0, "correct_answer": "江"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条江很窄，我们一步就能跨过去。", "explanation": "这里应该用〈小水沟〉。江指又长又宽的大水路，很窄、一步就能跨过去的水道要用〈小水沟〉。"}, {"text": "我家前面有一根江。", "explanation": "这里应该用〈条〉。江的量词是「条」，「根」用于细长的棍子、绳子等，不用于江。"}, {"text": "这条江又圆又小，里面养着几条金鱼。", "explanation": "这里应该用〈池塘〉。江指又长又宽的大水路，不能用来形容又圆又小、用于养鱼的水面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94659, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "江", "is_correct": true, "explanation": "江（jiāng）指又长又宽的大水路，船能行走。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖励。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱。"}, {"text": "相", "is_correct": false, "explanation": "xiāng 与 jiāng 声母不同（x 与 j），意思是互相。"}], "explanations": {"江": "江（jiāng）指又长又宽的大水路，船能行走。", "奖": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖励。", "酱": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱。", "相": "xiāng 与 jiāng 声母不同（x 与 j），意思是互相。"}, "sentence_index": null, "correct_answer": "江"}, "level_3": {"options": [{"text": "江", "is_correct": true, "explanation": "江是能让船行走的大水路，“在江上走着”指小船在水面上行驶，符合句意。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是架在水上供人或车通过的建筑，小船不会在桥上走，与句意不符。"}, {"text": "草地", "is_correct": false, "explanation": "语义：小船不能在草地上行驶，草地与水路无关。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“在……上走着”说公路时多指人或车，与“小船”不搭。"}], "explanations": {"江": "江是能让船行走的大水路，“在江上走着”指小船在水面上行驶，符合句意。", "桥": "语义：桥是架在水上供人或车通过的建筑，小船不会在桥上走，与句意不符。", "草地": "语义：小船不能在草地上行驶，草地与水路无关。", "公路": "搭配：“在……上走着”说公路时多指人或车，与“小船”不搭。"}, "sentence_index": 6, "correct_answer": "江"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条江只有一个水洼那么大，里面盛着几片落叶。", "explanation": "这里应该用〈水洼〉。江指又长又宽的大水路，只有一个水洼那么大的积水不能叫江。"}, {"text": "这条江只有几米宽，孩子们在里面蹚水。", "explanation": "这里应该用〈小溪〉。江指又长又宽的大水路，只有几米宽的水要用〈小溪〉。"}, {"text": "这条江绕一圈只要五分钟，我们常在边上散步。", "explanation": "这里应该用〈池塘〉。江指又长又宽的大水路，绕一圈只要几分钟、可以在边上散步的水面要用〈池塘〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近有一座江，夏天很热闹。", "corrected_sentence": "我家附近有一条江，夏天很热闹。", "error_description": "量词错误：江的量词应为「条」，「座」用于山、桥等，不用于江。应说「一条江」，不能说「一座江」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在那座江边玩，很开心。", "corrected_sentence": "孩子们在那条江边玩，很开心。", "error_description": "量词错误：江的量词应为「条」，「座」用于山、桥等，不用于江。应说「那条江边」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
