INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岩石风化破碎形成的细小颗粒，常见于河滩、海边和沙漠。", "primary_collocate": null, "pronunciation": "shā", "ipa": "ʂa˥", "syllable_count": 1, "sentences": [{"text": "海边的沙又细又软，很舒服。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水退了以后，河滩上留下了很多沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片地方没有草，只有黄色的沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风雨把山上的石头慢慢变成了沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边的沙上走了很久。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把远处的沙吹到了城里。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的沙是黄色的，那边的沙是白色的。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水带来了很多沙，堆在岸边。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河底的沙很干净，水也很清。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边的沙上写下了名字。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层沙", "label": "量词"}, {"form": "一堆沙", "label": "量词"}, {"form": "沙子", "label": "复合"}, {"form": "沙漠", "label": "复合"}], "register": "中性", "sense_fingerprint": "岩石风化形成的细小颗粒，河滩海边沙漠常见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd836b5-fdf8-41b4-a611-31fbc44b07d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。"}, {"text": "撒", "is_correct": false, "explanation": "sā 与 shā 声母不同（s／sh），意思是撒开、撒种。"}, {"text": "扎", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh／sh），意思是扎进。"}], "explanations": {"沙": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。", "傻": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。", "撒": "sā 与 shā 声母不同（s／sh），意思是撒开、撒种。", "扎": "zhā 与 shā 声母不同（zh／sh），意思是扎进。"}, "sentence_index": null, "correct_answer": "沙"}, "level_3": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙：细小颗粒，质地细软，与“海边”搭配，只有它合适。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“又细又软”，细软说的是颗粒或质地。"}, {"text": "海水", "is_correct": false, "explanation": "搭配：“海水”不说“又细又软”，这种形容只用于颗粒或质地。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能“又细又软”，“海边的树很舒服”说不通。"}], "explanations": {"沙": "沙：细小颗粒，质地细软，与“海边”搭配，只有它合适。", "石头": "语义：石头不会“又细又软”，细软说的是颗粒或质地。", "海水": "搭配：“海水”不说“又细又软”，这种形容只用于颗粒或质地。", "树": "语义：树不能“又细又软”，“海边的树很舒服”说不通。"}, "sentence_index": 0, "correct_answer": "沙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河里的沙很清，可以直接喝。", "explanation": "这里应该用〈水〉。沙是石头颗粒，不能喝，“清”说的是水。"}, {"text": "那片沙很肥，适合种庄稼。", "explanation": "这里应该用〈土地〉。沙缺少养分，不能说“很肥”。"}, {"text": "他每天早上喝一杯沙，很提神。", "explanation": "这里应该用〈茶〉。沙不能喝，“喝一杯”应该用饮品，如茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。"}, {"text": "啥", "is_correct": false, "explanation": "shá（第二声）与 shā（第一声）声调不同，意思是什么。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 shā 声母不同（ch／sh），意思是插入。"}, {"text": "渣", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh／sh），意思是渣滓。"}], "explanations": {"沙": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。", "啥": "shá（第二声）与 shā（第一声）声调不同，意思是什么。", "插": "chā 与 shā 声母不同（ch／sh），意思是插入。", "渣": "zhā 与 shā 声母不同（zh／sh），意思是渣滓。"}, "sentence_index": null, "correct_answer": "沙"}, "level_3": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙：细小颗粒，有颜色之分，与“黄色的”“白色的”搭配。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有颜色，不能说“黄色的声音”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能是黄色的，“这里的味道是黄色的”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有颜色，不能说“这里的名字是黄色的”。"}], "explanations": {"沙": "沙：细小颗粒，有颜色之分，与“黄色的”“白色的”搭配。", "声音": "语义：声音没有颜色，不能说“黄色的声音”。", "味道": "语义：味道不能是黄色的，“这里的味道是黄色的”说不通。", "名字": "语义：名字没有颜色，不能说“这里的名字是黄色的”。"}, "sentence_index": 6, "correct_answer": "沙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气太热了，我想喝一杯冰沙水。", "explanation": "这里应该用〈冰〉。沙是石头颗粒，不能放进水里喝来解渴。"}, {"text": "春天到了，沙开了一片。", "explanation": "这里应该用〈花〉。“开”搭配花，沙不会开。"}, {"text": "我每天吃一碗沙，很饱。", "explanation": "这里应该用〈饭〉。沙不能吃，“吃一碗”应该是饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河边的沙们又细又软，很舒服。", "corrected_sentence": "河边的沙又细又软，很舒服。", "error_description": "错误：“沙们”，正确：“沙”。沙是不可数名词，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从鞋里倒出了一个沙。", "corrected_sentence": "他从鞋里倒出了一些沙。", "error_description": "量词误用：沙是不可数的细小颗粒，不能用「一个」，应说「一些沙」或「一把沙」。错误：「一个沙」，正确：「一些沙」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加", "is_correct": true, "explanation": "加与减是算术中的一对反义词。"}, {"text": "看", "is_correct": false, "explanation": "看与减没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑与减没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写与减没有反义关系。"}], "correct_answer": "加", "explanations": {"加": "加与减是算术中的一对反义词。", "看": "看与减没有反义关系。", "跑": "跑与减没有反义关系。", "写": "写与减没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
