INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "算术中的减法：从一个数里去掉另一个数。", "primary_collocate": null, "pronunciation": "jiǎn", "ipa": "tɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "十减三等于七。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八减五是多少？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我，二十减六等于几？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五十减八，答案是四十二。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百减三十，还剩七十。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九减四，你算对了吗？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先加三，再减二，最后是几？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只会加，不会减。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用十五减七，得到八。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二减五比十二加五小得多。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "減", "label": "繁体"}, {"form": "减了", "label": "体标"}, {"form": "减过", "label": "体标"}, {"form": "减去", "label": "复合"}, {"form": "减少", "label": "复合"}], "register": "中性", "sense_fingerprint": "算术中的减法，从一个数里拿走另一个数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd836b5-fdf8-41b4-a611-31fbc44b07d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从数里拿走一部分，是算术中的减法。"}, {"text": "件", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。"}, {"text": "见", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是尖锐。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}], "explanations": {"减": "减（jiǎn）指从数里拿走一部分，是算术中的减法。", "件": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。", "见": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。", "尖": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是尖锐。", "奖": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示算术中的减法，“十减三等于七”成立。"}, {"text": "剩", "is_correct": false, "explanation": "配价：“剩”只带一个宾语，不能连接两个数字，“十剩三”不成立。"}, {"text": "加", "is_correct": false, "explanation": "语义：“十加三”得十三，与“等于七”不符。"}, {"text": "乘", "is_correct": false, "explanation": "语义：“十乘三”得三十，与“等于七”不符。"}], "explanations": {"减": "减表示算术中的减法，“十减三等于七”成立。", "剩": "配价：“剩”只带一个宾语，不能连接两个数字，“十剩三”不成立。", "加": "语义：“十加三”得十三，与“等于七”不符。", "乘": "语义：“十乘三”得三十，与“等于七”不符。"}, "sentence_index": 0, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把十块钱减给了妹妹，妹妹很高兴。", "explanation": "这里应该用〈给〉。减是算术动作，不能表示把钱交给别人。"}, {"text": "他往杯子里减了两勺糖。", "explanation": "这里应该用〈放〉。减表示拿走或变少，往杯子里加东西要用〈放〉，不能用「减」。"}, {"text": "她一边做饭，一边减着歌。", "explanation": "这里应该用〈唱〉。减是算术动作，不能用来表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从数里拿走一部分，是算术中的减法。"}, {"text": "建", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}], "explanations": {"减": "减（jiǎn）指从数里拿走一部分，是算术中的减法。", "建": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。", "间": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。", "讲": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示算术中的减法，“先加三，再减二”是正确的运算步骤。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”不是运算，“再买二”与算术题不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，不是运算，与算式不符。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”后接数字缺少量词，“再拿二”不成立。"}], "explanations": {"减": "减表示算术中的减法，“先加三，再减二”是正确的运算步骤。", "买": "语义：“买”不是运算，“再买二”与算术题不符。", "扔": "语义：“扔”表示丢弃，不是运算，与算式不符。", "拿": "配价：“拿”后接数字缺少量词，“再拿二”不成立。"}, "sentence_index": 6, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子每天减一首钢琴曲，很辛苦。", "explanation": "这里应该用〈弹〉。减是算术动作，不能用来表示弹奏乐曲。"}, {"text": "妈妈减下了一个女儿。", "explanation": "这里应该用〈生〉。减是算术中的减法，不能用来说生孩子。"}, {"text": "他在湖边减了一阵笑声。", "explanation": "这里应该用〈听到〉。减是算术中的减法，不能用来说听见声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二十减了六等于十四。", "corrected_sentence": "二十减六等于十四。", "error_description": "体标误用：算式里的「减」后直接接数字，不加「了」。「减了六」表示已完成的减少，不用于算式。错误形式是「减了」，正确形式是「减」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先加五，减再三，结果是多少？", "corrected_sentence": "我先加五，再减三，结果是多少？", "error_description": "语序错误：“再”应放在“减”之前，“减再三”不成立，应为“再减三”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加", "is_correct": true, "explanation": "加与减意思相反：减是降低、减少，加是增多（如加价、加工资）。"}, {"text": "唱", "is_correct": false, "explanation": "唱与减没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "跳与减没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗与减没有反义关系。"}], "correct_answer": "加", "explanations": {"加": "加与减意思相反：减是降低、减少，加是增多（如加价、加工资）。", "唱": "唱与减没有反义关系。", "跳": "跳与减没有反义关系。", "洗": "洗与减没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加", "is_correct": true, "explanation": "加与减意思相反：减是降低、减少，加是增多（如加盐、加价）。"}, {"text": "睡", "is_correct": false, "explanation": "睡与减没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "站与减没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画与减没有反义关系。"}], "correct_answer": "加", "explanations": {"加": "加与减意思相反：减是降低、减少，加是增多（如加盐、加价）。", "睡": "睡与减没有反义关系。", "站": "站与减没有反义关系。", "画": "画与减没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从总数里去掉一部分；也指降低、减少。", "primary_collocate": null, "pronunciation": "jiǎn", "ipa": "tɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这件衣服太贵了，老板给我减了五十块。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里的货减了十箱，还剩九十箱。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租太高，房东答应每月减三百。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作少了，这个月的工资也减了。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把每个人的奖金减了一半。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加的人减了三个，只剩十个人。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买两件就减二十块，很便宜。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月花钱太多，下个月要减一点。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把糖减了一半，咖啡就不那么甜了。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜太咸，盐要减一点。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "減", "label": "繁体"}, {"form": "减了", "label": "体标"}, {"form": "减过", "label": "体标"}, {"form": "减去", "label": "复合"}, {"form": "减少", "label": "复合"}], "register": "中性", "sense_fingerprint": "从总数里去掉一部分，降低或减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd836b5-fdf8-41b4-a611-31fbc44b07d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从总数里去掉一部分，或降低、减少。"}, {"text": "建", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}], "explanations": {"减": "减（jiǎn）指从总数里去掉一部分，或降低、减少。", "建": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。", "间": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。", "讲": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示降低、减少，“老板给我减了五十块”指降价五十元，符合句意。"}, {"text": "加", "is_correct": false, "explanation": "语义：太贵的时候老板不会给我加价，与“太贵了”的语境冲突。"}, {"text": "赚", "is_correct": false, "explanation": "配价：“赚”的收益者是老板，不能说“给我赚”。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”的宾语应是图画，“给我画了五十块”与降价无关。"}], "explanations": {"减": "减表示降低、减少，“老板给我减了五十块”指降价五十元，符合句意。", "加": "语义：太贵的时候老板不会给我加价，与“太贵了”的语境冲突。", "赚": "配价：“赚”的收益者是老板，不能说“给我赚”。", "画": "语义：“画”的宾语应是图画，“给我画了五十块”与降价无关。"}, "sentence_index": 0, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们店今年进了五百件新货，把库存减进了仓库。", "explanation": "这里应该用〈搬〉。减表示去掉一部分或降低，把货物搬进仓库要用〈搬〉，不能用「减」。"}, {"text": "老师让我把这篇文章减成英文。", "explanation": "这里应该用〈翻译〉。减表示去掉一部分或降低，把文章改换成另一种语言要用〈翻译〉，不能用「减」。"}, {"text": "黑板上的字，他用湿布减干净了。", "explanation": "这里应该用〈擦〉。减表示数量或价格的减少，不用于擦掉字迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从总数里去掉一部分，或降低、减少。"}, {"text": "件", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。"}, {"text": "见", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}], "explanations": {"减": "减（jiǎn）指从总数里去掉一部分，或降低、减少。", "件": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。", "见": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。", "奖": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示降低价格，“买两件就减二十块”指优惠二十块，符合句意。"}, {"text": "赔", "is_correct": false, "explanation": "语义：赔是亏损或赔偿，与“很便宜”的语境冲突。"}, {"text": "涨", "is_correct": false, "explanation": "语义：涨是提高价格，与“很便宜”矛盾。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”的宾语应是文字，不能说“写二十块”。"}], "explanations": {"减": "减表示降低价格，“买两件就减二十块”指优惠二十块，符合句意。", "赔": "语义：赔是亏损或赔偿，与“很便宜”的语境冲突。", "涨": "语义：涨是提高价格，与“很便宜”矛盾。", "写": "配价：“写”的宾语应是文字，不能说“写二十块”。"}, "sentence_index": 6, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上减到了老朋友。", "explanation": "这里应该用〈遇到〉。减表示去掉一部分或降低，在路上碰见熟人要用〈遇到〉，不能用「减」。"}, {"text": "他把旧玩具减给了弟弟。", "explanation": "这里应该用〈送〉。减表示去掉一部分或降低，把东西转交给别人要用〈送〉，不能用「减」。"}, {"text": "他把脏衣服减干净了。", "explanation": "这里应该用〈洗〉。减表示数量或价格的减少，不用于清洗衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的房租了减两百块。", "corrected_sentence": "这个月的房租减了两百块。", "error_description": "「了」的位置错误：「了」应放在动词之后，正确为「减了两百块」，「了减」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把孩子的零食减着一半。", "corrected_sentence": "我把孩子的零食减了一半。", "error_description": "体标误用：减少一半是已经完成的变化，要用「了」，不能用表示持续的「着」。错误：「减着」，正确：「减了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ed9b24e-b9fc-495a-8a99-72006d9139ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
