INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汤是吃饭时可以喝的、带食材味道的热液体。", "primary_collocate": null, "pronunciation": "tāng", "ipa": "tʰɑŋ˥", "syllable_count": 1, "sentences": [{"text": "我喜欢喝热汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了一碗鸡蛋汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候，我先喝汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤太烫了，慢慢喝。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的汤很好喝。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，喝点热汤吧。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天都给我做汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顿饭有菜，有肉，还有汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里有鸡蛋和青菜。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把汤喝完了。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鸡汤", "label": "复合"}, {"form": "湯", "label": "繁体"}], "register": "口语", "sense_fingerprint": "饭桌上可以喝的热汤水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cfb271-6cf6-4e2e-932c-d240c0e07ed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94667, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汤", "is_correct": true, "explanation": "汤（tāng）：吃饭时可以喝的、带食材味道的热液体。"}, {"text": "糖", "is_correct": false, "explanation": "táng（第二声）与 tāng（第一声）声调不同，意思是糖。"}, {"text": "烫", "is_correct": false, "explanation": "tàng（第四声）与 tāng（第一声）声调不同，意思是烫。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng（第三声）与 tāng（第一声）声调不同，意思是躺下。"}, {"text": "滩", "is_correct": false, "explanation": "tān 与 tāng 韵母不同（an/ang），意思是海滩。"}], "explanations": {"汤": "汤（tāng）：吃饭时可以喝的、带食材味道的热液体。", "糖": "táng（第二声）与 tāng（第一声）声调不同，意思是糖。", "烫": "tàng（第四声）与 tāng（第一声）声调不同，意思是烫。", "躺": "tǎng（第三声）与 tāng（第一声）声调不同，意思是躺下。", "滩": "tān 与 tāng 韵母不同（an/ang），意思是海滩。"}, "sentence_index": null, "correct_answer": "汤"}, "level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料或汤水，不能说“喝热饭”。"}, {"text": "汤", "is_correct": true, "explanation": "“汤”是可以喝的热汤水，与“我喜欢喝热”搭配。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包不能用来喝，“喝热面包”不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来喝，句子在语义上不成立。"}], "explanations": {"饭": "搭配：“喝”的对象是饮料或汤水，不能说“喝热饭”。", "汤": "“汤”是可以喝的热汤水，与“我喜欢喝热”搭配。", "面包": "搭配：面包不能用来喝，“喝热面包”不通。", "书": "语义：书不能用来喝，句子在语义上不成立。"}, "sentence_index": 0, "correct_answer": "汤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天给花浇汤。", "explanation": "这里应该用〈水〉。给花浇水用水，汤是有油脂和味道的食物，不能用来浇花。"}, {"text": "天冷了，我穿上了一件汤。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣服，汤是喝的食物，不能穿。"}, {"text": "我用汤洗了手。", "explanation": "这里应该用〈热水〉。汤是有汤料的食物，不能用来洗手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34477288-21e6-408a-8b0d-1fdaaebe13de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94667, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "汤", "is_correct": true, "explanation": "汤（tāng）：吃饭时可以喝的、带食材味道的热液体。"}, {"text": "堂", "is_correct": false, "explanation": "táng（第二声）与 tāng（第一声）声调不同，意思是厅堂。"}, {"text": "趟", "is_correct": false, "explanation": "tàng（第四声）与 tāng（第一声）声调不同，意思是一趟（量词）。"}, {"text": "摊", "is_correct": false, "explanation": "tān 与 tāng 韵母不同（an/ang），意思是摊子。"}], "explanations": {"汤": "汤（tāng）：吃饭时可以喝的、带食材味道的热液体。", "堂": "táng（第二声）与 tāng（第一声）声调不同，意思是厅堂。", "趟": "tàng（第四声）与 tāng（第一声）声调不同，意思是一趟（量词）。", "摊": "tān 与 tāng 韵母不同（an/ang），意思是摊子。"}, "sentence_index": null, "correct_answer": "汤"}, "level_3": {"options": [{"text": "电话", "is_correct": false, "explanation": "搭配：“做”不能与“电话”搭配，应说“打电话”。"}, {"text": "汤", "is_correct": true, "explanation": "“汤”是奶奶每天为我做的汤，与“给我做”搭配。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“做”不能与“声音”搭配，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被做出来，与“给我做”的意思矛盾。"}], "explanations": {"电话": "搭配：“做”不能与“电话”搭配，应说“打电话”。", "汤": "“汤”是奶奶每天为我做的汤，与“给我做”搭配。", "声音": "搭配：“做”不能与“声音”搭配，句子不通。", "月亮": "语义：月亮不能被做出来，与“给我做”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "汤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我榨了一杯汤。", "explanation": "这里应该用〈果汁〉。榨出来的是果汁，汤不能用“榨”来做。"}, {"text": "他用汤擦了桌子。", "explanation": "这里应该用〈水〉。擦桌子一般用水，汤是有油脂和味道的食物，不能用来擦桌子。"}, {"text": "我每天用汤刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙用牙膏，汤不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34477288-21e6-408a-8b0d-1fdaaebe13de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我盛了一只热汤。", "corrected_sentence": "妈妈给我盛了一碗热汤。", "error_description": "错误在“汤”的量词。“只”不能用来计量汤，应改为“一碗热汤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34477288-21e6-408a-8b0d-1fdaaebe13de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶熬了一条鸡汤，全家都喝了。", "corrected_sentence": "奶奶熬了一锅鸡汤，全家都喝了。", "error_description": "错误在量词“一条”。“条”不能用来计量汤，应改为“一锅鸡汤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34477288-21e6-408a-8b0d-1fdaaebe13de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
