INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94673, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活方式是一个人每天怎样过日子。", "primary_collocate": null, "pronunciation": "shēng huó fāng shì", "ipa": "ʂɤŋ˥ xuo˧˥ faŋ˥ ʂɨ˥˩", "syllable_count": 4, "sentences": [{"text": "他的生活方式很简单。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想改变自己的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早睡早起是一种好的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在山里的人生活方式和城市人不一样。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天跑步，生活方式很健康。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的生活方式不同，常常有问题。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在年轻人的生活方式跟以前很不一样。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢安静的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了工作，生活方式也变了。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢这种慢慢过日子的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人每天过日子的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca225a9-f261-4012-915b-1e8f99594883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的数值，不能用“很简单”来形容。"}, {"text": "生活方式", "is_correct": true, "explanation": "正确：生活方式指过日子的习惯与方式，可以说“很简单”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“他的”不能领属天气，天气也不能说“很简单”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的数值，不能说“很简单”。"}], "explanations": {"身高": "语义：身高是身体的数值，不能用“很简单”来形容。", "生活方式": "正确：生活方式指过日子的习惯与方式，可以说“很简单”。", "天气": "搭配：“他的”不能领属天气，天气也不能说“很简单”。", "体温": "语义：体温是身体的数值，不能说“很简单”。"}, "sentence_index": 0, "correct_answer": "生活方式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年农村的生活方式涨价了很多。", "explanation": "这里应该用〈物价〉。涨价说的是商品或物价，生活方式是过日子的习惯，不能涨价。"}, {"text": "他的生活方式很高，大家都很羡慕他。", "explanation": "这里应该用〈收入〉。收入指钱的多少，可以说高；生活方式指过日子的习惯，不能说很高。"}, {"text": "他的生活方式很开朗，喜欢交朋友。", "explanation": "这里应该用〈性格〉。性格可以说开朗；生活方式指过日子的习惯，不能用开朗形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是年轻人的生活习惯，句子不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：雨伞不能用“跟以前很不一样”来描述年轻人的特点，搭配不当。"}, {"text": "生活方式", "is_correct": true, "explanation": "正确：生活方式指年轻人过日子的习惯，可以“跟以前很不一样”。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，不能描述年轻人的习惯。"}], "explanations": {"石头": "语义：石头不是年轻人的生活习惯，句子不通。", "雨伞": "搭配：雨伞不能用“跟以前很不一样”来描述年轻人的特点，搭配不当。", "生活方式": "正确：生活方式指年轻人过日子的习惯，可以“跟以前很不一样”。", "海拔": "语义：海拔是地理高度，不能描述年轻人的习惯。"}, "sentence_index": 6, "correct_answer": "生活方式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "超市里有很多生活方式，大家都在挑选。", "explanation": "这里应该用〈生活用品〉。生活方式指习惯和方式，不能在超市里挑选。"}, {"text": "每个月的生活方式不够用，我很着急。", "explanation": "这里应该用〈生活费〉。生活方式不是钱，不能说“不够用”。"}, {"text": "这份工作的生活方式很大，我有点累。", "explanation": "这里应该用〈压力〉。生活方式不能用“很大”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把生活方式调整来过了。", "corrected_sentence": "他终于把生活方式调整过来了。", "error_description": "补语语序错误：“调整”后的趋向补语应说〈调整过来〉，不能说〈调整来过〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一张健康的生活方式。", "corrected_sentence": "这是一种健康的生活方式。", "error_description": "量词错误：生活方式应说〈一种〉，〈张〉用于纸张、桌子等平面的东西，不能修饰生活方式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
