INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们在日常生活中吃住行、工作、休息和娱乐等方面的习惯和方式。", "primary_collocate": null, "pronunciation": "shēng huó fāng shì", "ipa": "ʂɤŋ˥ xuo˧˥ faŋ˥ ʂɨ˥˩", "syllable_count": 4, "sentences": [{"text": "吃得健康、睡得够，这是好的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，坏的生活方式会让人生病。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活方式是白天工作，晚上玩游戏。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少吃肉，多运动，是很多人选的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该养成健康的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她经常熬夜，这种生活方式对身体不好。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里人的生活方式和农村人有很多不同。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络改变了人们的生活方式。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的生活方式一般比较有规律。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭、睡觉、工作都有时间，他的生活方式很规律。", "target_word": "生活方式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们在吃住行、工作、休息、娱乐等方面的习惯和方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca225a9-f261-4012-915b-1e8f99594883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午餐", "is_correct": false, "explanation": "语义：午餐是一顿饭，不是吃住习惯，句意不通。"}, {"text": "枕头", "is_correct": false, "explanation": "搭配：“这是好的……”评价的应是习惯方式，枕头不能与之搭配。"}, {"text": "生活方式", "is_correct": true, "explanation": "正确：生活方式指饮食、作息等习惯，符合“吃得健康、睡得够”的句意。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不能作为吃睡习惯的评价对象。"}], "explanations": {"午餐": "语义：午餐是一顿饭，不是吃住习惯，句意不通。", "枕头": "搭配：“这是好的……”评价的应是习惯方式，枕头不能与之搭配。", "生活方式": "正确：生活方式指饮食、作息等习惯，符合“吃得健康、睡得够”的句意。", "电话": "语义：电话是通讯工具，不能作为吃睡习惯的评价对象。"}, "sentence_index": 0, "correct_answer": "生活方式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个月的生活方式要省着花，不能超支。", "explanation": "这里应该用〈生活费〉。生活方式是习惯，不是钱，不能说“省着花”。"}, {"text": "他的生活方式很大，已经六十岁了。", "explanation": "这里应该用〈年龄〉。年龄可以说大；生活方式指过日子的习惯，不能说很大。"}, {"text": "这种食物的生活方式很高，所以大家都爱吃。", "explanation": "这里应该用〈营养〉。食物的高低用营养来说，生活方式不能说“很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是人，不能与“和农村人有很多不同”比较。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人群，句子不通。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：“和农村人有很多不同”要求比较人的习惯，字典不能与之搭配。"}, {"text": "生活方式", "is_correct": true, "explanation": "正确：生活方式指人们的生活习惯，城里人和农村人可以有很多不同。"}], "explanations": {"海洋": "语义：海洋不是人，不能与“和农村人有很多不同”比较。", "河流": "语义：河流不是人群，句子不通。", "字典": "搭配：“和农村人有很多不同”要求比较人的习惯，字典不能与之搭配。", "生活方式": "正确：生活方式指人们的生活习惯，城里人和农村人可以有很多不同。"}, "sentence_index": 6, "correct_answer": "生活方式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月的生活方式很高，大家都很羡慕。", "explanation": "这里应该用〈工资〉。生活方式是习惯，不能用每个月的数额来说“很高”。"}, {"text": "这件衣服的生活方式很低，我就买了它。", "explanation": "这里应该用〈价格〉。生活方式不能用“很低”来说，衣服的高低用价格。"}, {"text": "他的生活方式很高，超过了一米八。", "explanation": "这里应该用〈身高〉。生活方式不能用“很高”描述人的高矮，应说身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他决定换一本健康的生活方式。", "corrected_sentence": "他决定换一种健康的生活方式。", "error_description": "量词错误：生活方式应说〈一种〉，〈本〉用于书籍等，不能修饰生活方式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把生活方式调整很规律。", "corrected_sentence": "他把生活方式调整得很规律。", "error_description": "补语标记错误：程度补语前要用“得”，应说〈调整得很规律〉，不能省去〈得〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
