INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生活资料是人们每天过日子要用的东西。", "primary_collocate": null, "pronunciation": "shēng huó zī liào", "ipa": "ʂɤŋ˥ xuo˧˥ tsɹ̩˥ liaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "搬到新城市以后，我先买了生活资料。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每周去超市买家里的生活资料。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给山区孩子送来了生活资料。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活资料有米、油、盐和衣服。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪前，大家都准备好了生活资料。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些生活资料够我们用一个月。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在店里挑选了一些生活资料。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的生活资料由儿女来送。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的生活资料比村里的贵。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，我带了很多生活资料。", "target_word": "生活资料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活資料", "label": "繁体"}], "register": "书面", "sense_fingerprint": "每天过日子要用的东西，如米、油、盐、衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4d8750f-33e3-4d0a-afc2-fdce50ccbd55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活资料", "is_correct": true, "explanation": "正确：“生活资料”是人们每天过日子要用的东西，可以在店里买，符合“搬到新城市以后，我先买了”的语境。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”不是可以购买的东西，与“买了”的语境不合。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：“阳光”无法购买，与“买了”的语境不合。"}, {"text": "信任", "is_correct": false, "explanation": "搭配：“买”不能与“信任”搭配，信任要靠相处慢慢建立，不能买。"}], "explanations": {"生活资料": "正确：“生活资料”是人们每天过日子要用的东西，可以在店里买，符合“搬到新城市以后，我先买了”的语境。", "故事": "语义：“故事”不是可以购买的东西，与“买了”的语境不合。", "阳光": "语义：“阳光”无法购买，与“买了”的语境不合。", "信任": "搭配：“买”不能与“信任”搭配，信任要靠相处慢慢建立，不能买。"}, "sentence_index": 0, "correct_answer": "生活资料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂用生活资料生产机器。", "explanation": "这里应该用〈钢材〉。生活资料是供人消费的物品，不是生产机器的材料。"}, {"text": "他用生活资料修理自行车。", "explanation": "这里应该用〈工具〉。生活资料不是修理用的工具，修车要用工具。"}, {"text": "我昨晚做完了生活资料。", "explanation": "这里应该用〈作业〉。生活资料是物品，不能用“做完”来表示完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活资料", "is_correct": true, "explanation": "正确：“生活资料”是可以在店里挑选的日常物品，符合“他在店里挑选了一些”的语境。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”不能在店里挑选，与“店里”的语境不合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”不能在店里挑选，与“店里”的语境不合。"}, {"text": "回忆", "is_correct": false, "explanation": "搭配：“挑选”的对象是可以选购的东西，“回忆”不能挑选。"}], "explanations": {"生活资料": "正确：“生活资料”是可以在店里挑选的日常物品，符合“他在店里挑选了一些”的语境。", "星星": "语义：“星星”不能在店里挑选，与“店里”的语境不合。", "雨": "语义：“雨”不能在店里挑选，与“店里”的语境不合。", "回忆": "搭配：“挑选”的对象是可以选购的东西，“回忆”不能挑选。"}, "sentence_index": 6, "correct_answer": "生活资料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们看着生活资料找路。", "explanation": "这里应该用〈地图〉。生活资料不能用来看着找路，找路要用地图。"}, {"text": "他骑生活资料上班。", "explanation": "这里应该用〈自行车〉。生活资料是供人消费的物品，不能用来骑。"}, {"text": "他昨天参加了生活资料。", "explanation": "这里应该用〈考试〉。“参加”搭配的是活动或考试，生活资料不能被参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些生活资料很高兴地搬进了仓库。", "corrected_sentence": "这些生活资料很快就被搬进了仓库。", "error_description": "语义错误：“生活资料”是物，不能“很高兴地”做事，应改为“很快就被搬进了仓库”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把生活资料们都装进了箱子。", "corrected_sentence": "他们把生活资料都装进了箱子。", "error_description": "后缀错误：“生活资料”是集合概念，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e670b2a-e0a2-4afb-9146-df6b910d981b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
