INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女子的男性恋爱对象，男朋友的简称。", "primary_collocate": null, "pronunciation": "nán yǒu", "ipa": "nan˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她的男友是一位医生。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和男友已经谈了三年恋爱。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把男友介绍给自己的父母。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男友过生日，她送了他一块手表。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和男友吵架了，心情不好。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小林的男友在北京工作，她很想他。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟男友说好明年结婚。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的男友每天晚上都给我打电话。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是情人节，男友送给她一束花。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她男友很会照顾人，大家都喜欢他。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "前男友", "label": "复合"}], "register": "中性", "sense_fingerprint": "男朋友的简称，女子的恋爱对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca225a9-f261-4012-915b-1e8f99594883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "男友", "is_correct": true, "explanation": "正确：男友指女子的男性恋爱对象，读作 nán yǒu。"}, {"text": "篮友", "is_correct": false, "explanation": "lán 与 nán 声母不同（l 与 n），篮友指一起打篮球的朋友。"}, {"text": "难友", "is_correct": false, "explanation": "第一个音节声调不同（nàn 第四声与 nán 第二声），难友指一同受难的人。"}, {"text": "南游", "is_correct": false, "explanation": "第二个音节声调不同（yóu 第二声与 yǒu 第三声），南游指到南方游历。"}], "explanations": {"男友": "正确：男友指女子的男性恋爱对象，读作 nán yǒu。", "篮友": "lán 与 nán 声母不同（l 与 n），篮友指一起打篮球的朋友。", "难友": "第一个音节声调不同（nàn 第四声与 nán 第二声），难友指一同受难的人。", "南游": "第二个音节声调不同（yóu 第二声与 yǒu 第三声），南游指到南方游历。"}, "sentence_index": null, "correct_answer": "男友"}, "level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户不可能是医生，句意荒谬。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是人，不能“是一位医生”。"}, {"text": "男友", "is_correct": true, "explanation": "正确：男友是女子的恋爱对象，可以“是一位医生”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“是一位医生”要求人作主语，冰箱不能与之搭配。"}], "explanations": {"窗户": "语义：窗户不可能是医生，句意荒谬。", "闹钟": "语义：闹钟不是人，不能“是一位医生”。", "男友": "正确：男友是女子的恋爱对象，可以“是一位医生”。", "冰箱": "搭配：“是一位医生”要求人作主语，冰箱不能与之搭配。"}, "sentence_index": 0, "correct_answer": "男友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和男友结婚十年了，他每天早上给我做早饭。", "explanation": "这里应该用〈老公〉。男友指还没有结婚的恋爱对象，已经结婚就用老公。"}, {"text": "幼儿园里有一个男友，刚学会说话。", "explanation": "这里应该用〈小男孩〉。男友指恋爱对象，幼儿园里的小孩不能称为男友。"}, {"text": "我男友和我是一个妈妈生的，我们长得很像。", "explanation": "这里应该用〈兄弟〉。男友指恋爱对象，有血缘关系的兄弟不能称为男友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是人，不能说“跟海洋说好明年结婚”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“说好结婚”要求有意识的人作对象，石头不能与之搭配。"}, {"text": "男友", "is_correct": true, "explanation": "正确：男友是恋爱对象，可以和她约定结婚。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能和人约定结婚，句意荒谬。"}], "explanations": {"海洋": "语义：海洋不是人，不能说“跟海洋说好明年结婚”。", "石头": "搭配：“说好结婚”要求有意识的人作对象，石头不能与之搭配。", "男友": "正确：男友是恋爱对象，可以和她约定结婚。", "雨伞": "语义：雨伞不能和人约定结婚，句意荒谬。"}, "sentence_index": 6, "correct_answer": "男友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和男友在公司只是点头之交，平时很少说话。", "explanation": "这里应该用〈同事〉。男友指恋爱对象，公司里的普通同事不能称男友。"}, {"text": "路上有个男友，偷走了一位老人的钱包。", "explanation": "这里应该用〈小偷〉。男友指恋爱对象，偷东西的陌生人不能这样称呼。"}, {"text": "我的男友是我爸爸的小儿子。", "explanation": "这里应该用〈弟弟〉。男友指恋爱对象，家人不能称为男友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐上个月有了一张男友。", "corrected_sentence": "姐姐上个月有了一个男友。", "error_description": "量词错误：男友指人，应说〈一个男友〉；〈张〉用于平面的东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的男友的很温柔，大家都喜欢他。", "corrected_sentence": "她的男友很温柔，大家都喜欢他。", "error_description": "结构错误：〈男友〉后面不应再加〈的〉，应说〈她的男友很温柔〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
