INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "发想是脑子里想出来的新办法。", "primary_collocate": null, "pronunciation": "fā xiǎng", "ipa": "fa˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个广告的发想很新，大家都喜欢。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发想总是和别人不一样。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸这个设计的发想很特别。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的发想来自一个梦。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的发想不一定要花很多钱。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的发想写在本子上。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司需要有新发想的年轻人。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发想很有趣，可是不容易做到。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家都说了自己的发想。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛看的是谁的发想更好。", "target_word": "发想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "脑子里想出来的新办法、新主意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3101b179-ea35-4787-b575-d3c8af1182ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94681, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发想", "is_correct": true, "explanation": "正确答案。“发想”指脑子里想出来的新办法。"}, {"text": "分享", "is_correct": false, "explanation": "fēn 与 fā 韵母不同，意思是与别人一起拥有或享用。"}, {"text": "发行", "is_correct": false, "explanation": "xíng 与 xiǎng 韵母和声调不同，意思是公开发售或发布。"}, {"text": "发笑", "is_correct": false, "explanation": "xiào 与 xiǎng 韵母和声调不同，意思是引人发笑。"}, {"text": "发现", "is_correct": false, "explanation": "xiàn 与 xiǎng 韵母和声调不同，意思是觉察到、找到。"}], "explanations": {"发想": "正确答案。“发想”指脑子里想出来的新办法。", "分享": "fēn 与 fā 韵母不同，意思是与别人一起拥有或享用。", "发行": "xíng 与 xiǎng 韵母和声调不同，意思是公开发售或发布。", "发笑": "xiào 与 xiǎng 韵母和声调不同，意思是引人发笑。", "发现": "xiàn 与 xiǎng 韵母和声调不同，意思是觉察到、找到。"}, "sentence_index": null, "correct_answer": "发想"}, "level_3": {"options": [{"text": "发想", "is_correct": true, "explanation": "正确。“发想”指新的主意、创意，可以说“很新”，与“大家都喜欢”也相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，不能说“很新”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气候状况，不能用“很新”来形容广告的内容。"}, {"text": "预算", "is_correct": false, "explanation": "搭配：“预算”是钱的安排，不说“很新”。"}], "explanations": {"发想": "正确。“发想”指新的主意、创意，可以说“很新”，与“大家都喜欢”也相符。", "价格": "语义：“价格”指价钱，不能说“很新”。", "天气": "语义：“天气”是气候状况，不能用“很新”来形容广告的内容。", "预算": "搭配：“预算”是钱的安排，不说“很新”。"}, "sentence_index": 0, "correct_answer": "发想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想到了一只好发想。", "explanation": "这里应该用〈个〉。“发想”是抽象的想法，量词用“个”；“只”多用于动物，不能用来数“发想”。"}, {"text": "这部作品很富有发想。", "explanation": "这里应该用〈创意〉。“富有”后接“创意、想象力”等，不说“富有发想”。"}, {"text": "他每天早上都要吃一碗发想。", "explanation": "这里应该用〈面条〉。“发想”是想法，不能“吃”，也不能用“碗”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94681, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发想", "is_correct": true, "explanation": "正确答案。“发想”指脑子里想出来的新办法。"}, {"text": "发奖", "is_correct": false, "explanation": "jiǎng 与 xiǎng 声母不同，意思是颁发奖品。"}, {"text": "发小", "is_correct": false, "explanation": "xiǎo 与 xiǎng 韵母不同，意思是从小一起长大的朋友。"}, {"text": "发祥", "is_correct": false, "explanation": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是兴起、发源（如“发祥地”）。"}], "explanations": {"发想": "正确答案。“发想”指脑子里想出来的新办法。", "发奖": "jiǎng 与 xiǎng 声母不同，意思是颁发奖品。", "发小": "xiǎo 与 xiǎng 韵母不同，意思是从小一起长大的朋友。", "发祥": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是兴起、发源（如“发祥地”）。"}, "sentence_index": null, "correct_answer": "发想"}, "level_3": {"options": [{"text": "发想", "is_correct": true, "explanation": "正确。“新发想”指新的创意，“需要有新……的年轻人”说的是有新主意的年轻人。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能说“新”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是年数，不能说“新”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说增加或减少，不说“新体重”。"}], "explanations": {"发想": "正确。“新发想”指新的创意，“需要有新……的年轻人”说的是有新主意的年轻人。", "身高": "体貌：“身高”是身体特征，不能说“新”。", "年龄": "语义：“年龄”是年数，不能说“新”。", "体重": "搭配：“体重”说增加或减少，不说“新体重”。"}, "sentence_index": 6, "correct_answer": "发想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他花了一个月的时间制订发想。", "explanation": "这里应该用〈计划〉。“制订”多接“计划、方案”，发想是想出来的新办法，不能说“制订发想”。"}, {"text": "这个新发想已经安装好了。", "explanation": "这里应该用〈设备〉。“安装”接设备、软件等具体的东西，发想是想法，不能说“安装好了”。"}, {"text": "老师帮我们解决了发想。", "explanation": "这里应该用〈问题〉。“解决”接问题、矛盾等，不能说“解决发想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她想出了一只很好的发想。", "corrected_sentence": "她想出了一个很好的发想。", "error_description": "量词用错：“发想”是抽象的想法，应说“一个”，不能说“一只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她提出了一张新的发想。", "corrected_sentence": "她提出了一个新的发想。", "error_description": "量词用错：“发想”应说“一个”，不能说“一张”（“张”多用于纸、桌子等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16f75cd7-34c5-4e6d-8efa-ea9e49b7dc17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
