INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94683, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尽力是用上所有的力气去做。", "primary_collocate": null, "pronunciation": "jìn lì", "ipa": "tɕin˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他尽力跑到了终点。", "target_word": "尽力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会尽力帮你找工作。", "target_word": "尽力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛时，大家都尽力了。", "target_word": "尽力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈尽力把家里弄得干净。", "target_word": "尽力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尽力搬起了那个大箱子。", "target_word": "尽力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经尽力了，真的搬不动。", "target_word": "尽力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说只要尽力就好。", "target_word": "尽力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他尽力把球扔得很远。", "target_word": "尽力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你尽力跑，不要停下来。", "target_word": "尽力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她尽力拉着弟弟的手。", "target_word": "尽力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尽了力", "label": "体标"}, {"form": "尽过力", "label": "体标"}, {"form": "尽力而为", "label": "复合"}], "register": "中性", "sense_fingerprint": "尽力：动词，用上全部力气去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尽力", "is_correct": true, "explanation": "正确答案：尽力（jìn lì），意思是用尽全部力量去做。"}, {"text": "精力", "is_correct": false, "explanation": "jīng（第一声）与 jìn（第四声）韵母不同（ing 与 in），意思是精神和体力。"}, {"text": "警力", "is_correct": false, "explanation": "jǐng（第三声）与 jìn（第四声）韵母和声调都不同（ing 与 in），意思是警察的人力。"}, {"text": "净利", "is_correct": false, "explanation": "jìng（第四声）与 jìn 韵母不同（ing 与 in），意思是扣除成本后的利润。"}], "explanations": {"尽力": "正确答案：尽力（jìn lì），意思是用尽全部力量去做。", "精力": "jīng（第一声）与 jìn（第四声）韵母不同（ing 与 in），意思是精神和体力。", "警力": "jǐng（第三声）与 jìn（第四声）韵母和声调都不同（ing 与 in），意思是警察的人力。", "净利": "jìng（第四声）与 jìn 韵母不同（ing 与 in），意思是扣除成本后的利润。"}, "sentence_index": null, "correct_answer": "尽力"}, "level_3": {"options": [{"text": "尽力", "is_correct": true, "explanation": "正确：“尽力”表示用尽力气去跑，与“跑到了终点”的努力相合。"}, {"text": "未能", "is_correct": false, "explanation": "语法：“未能”表示没有做到，后面不能接“了”，且与“跑到了终点”的完成之意相反，句子不成立。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”要接持续或不变的状态，不与带“了”的一次性完成动作搭配。"}, {"text": "肆意", "is_correct": false, "explanation": "语域：“肆意”书面色彩重，且含放纵的贬义，不适合用来描述跑步到终点。"}], "explanations": {"尽力": "正确：“尽力”表示用尽力气去跑，与“跑到了终点”的努力相合。", "未能": "语法：“未能”表示没有做到，后面不能接“了”，且与“跑到了终点”的完成之意相反，句子不成立。", "始终": "搭配：“始终”要接持续或不变的状态，不与带“了”的一次性完成动作搭配。", "肆意": "语域：“肆意”书面色彩重，且含放纵的贬义，不适合用来描述跑步到终点。"}, "sentence_index": 0, "correct_answer": "尽力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他尽力摔倒了，膝盖都擦破了。", "explanation": "尽力表示有意识地用力去做，“摔倒”是无意发生的，不能用尽力来修饰。"}, {"text": "我尽力是一名学生。", "explanation": "这里误把尽力用在“是”字判断句里。尽力表示用尽力气去做动作，不能表示身份或判断，应说“我是一名学生”。"}, {"text": "妈妈尽力感到很幸福。", "explanation": "尽力用于可以用力去做的动作；“感到幸福”是心理状态，不能用尽力去感到，应说“努力让自己幸福”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽力", "is_correct": true, "explanation": "正确：“只要尽力就好”是老师的安慰语，与“只要……就好”的句式相合。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“只要放弃就好”与老师鼓励的语气相反，句意不通。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：“只要偷懒就好”与鼓励努力的语境相反，不符合老师的意思。"}, {"text": "打破", "is_correct": false, "explanation": "配价：“打破”要带宾语，如纪录、常规，单独用“只要打破就好”不成句。"}], "explanations": {"尽力": "正确：“只要尽力就好”是老师的安慰语，与“只要……就好”的句式相合。", "放弃": "语义：“只要放弃就好”与老师鼓励的语气相反，句意不通。", "偷懒": "语义：“只要偷懒就好”与鼓励努力的语境相反，不符合老师的意思。", "打破": "配价：“打破”要带宾语，如纪录、常规，单独用“只要打破就好”不成句。"}, "sentence_index": 6, "correct_answer": "尽力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子尽力长高了一米。", "explanation": "“长高”是身体自然发生的变化，不是用力去做的动作，不能用尽力。"}, {"text": "我尽力听见了门铃声。", "explanation": "尽力表示用力去做，“听见”是感官自然产生的结果，不能用尽力。"}, {"text": "他尽力遇到了一位老朋友。", "explanation": "尽力表示用尽力气去做，“遇到”是偶然发生的，不能用尽力来修饰，这里应说“偶然遇到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他尽力而为修好了那辆旧自行车。", "corrected_sentence": "他尽力修好了那辆旧自行车。", "error_description": "错误形式是“尽力而为修好了”，正确形式是“尽力修好了”。“尽力而为”是固定的复合词，不能直接接动词作状语，这里只用“尽力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她尽力了帮我一把。", "corrected_sentence": "她尽力帮了我一把。", "error_description": "错误形式是“尽力了帮”，正确形式是“尽力帮了”。“了”应放在动词后面表示完成，不能插在“尽力”和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
