INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "监视是一直看着，不让对方走开或做坏事。", "primary_collocate": null, "pronunciation": "jiān shì", "ipa": "tɕjɛn˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "警察一直监视着那个小偷。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕妻子乱花钱，天天监视她。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在后面监视着工人干活，不让他们休息。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个警察监视着坐在地上的人，不让他跑。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想让我走，所以一直监视我。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别监视我，我不会做坏事的。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安监视着门口，不让陌生人进来。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥监视着弟弟，不让他玩手机。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把他关在房间里，还派人监视他。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狱警一直监视着那个犯人，怕他逃跑。", "target_word": "监视", "complexity_tier": "T3", "furigana": "yù jǐng yì zhí jiān shì zhe nà ge fàn rén, pà tā táo pǎo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "监视着", "label": "体标"}, {"form": "监视了", "label": "体标"}, {"form": "监视过", "label": "体标"}, {"form": "监视器", "label": "复合"}], "register": "书面", "sense_fingerprint": "一直盯着对方，不让他走开或做坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dca225a9-f261-4012-915b-1e8f99594883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着对方，不让他走开或做坏事。"}, {"text": "监制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是监督制作，常用于影视、产品。"}, {"text": "家事", "is_correct": false, "explanation": "jiā 与 jiān 韵母不同（少一个 n），意思是家里的事情。"}, {"text": "简史", "is_correct": false, "explanation": "jiǎn shǐ 与 jiān shì 声调不同（第三声与第一声、第三声与第四声），意思是简要的历史。"}], "explanations": {"监视": "监视：一直看着对方，不让他走开或做坏事。", "监制": "zhì 与 shì 声母不同（zh 与 sh），意思是监督制作，常用于影视、产品。", "家事": "jiā 与 jiān 韵母不同（少一个 n），意思是家里的事情。", "简史": "jiǎn shǐ 与 jiān shì 声调不同（第三声与第一声、第三声与第四声），意思是简要的历史。"}, "sentence_index": null, "correct_answer": "监视"}, "level_3": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着，不让对方走开，与“抓小偷”的语境相合。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”表示陪同做伴，与警察抓小偷的语境相反。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”用于远处的景物，不能用于近距离盯着一个人。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”表示良好的祝愿，与小偷的语境不合。"}], "explanations": {"监视": "监视：一直看着，不让对方走开，与“抓小偷”的语境相合。", "陪伴": "语义：“陪伴”表示陪同做伴，与警察抓小偷的语境相反。", "眺望": "搭配：“眺望”用于远处的景物，不能用于近距离盯着一个人。", "祝福": "语义：“祝福”表示良好的祝愿，与小偷的语境不合。"}, "sentence_index": 0, "correct_answer": "监视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在剧院监视了一场精彩的演出。", "explanation": "这里应该用〈观看〉。监视针对需要防止走开或作恶的人，看演出要用观看。"}, {"text": "他们在湖边监视美妙的音乐。", "explanation": "这里应该用〈聆听〉。音乐不会走开或作恶，听音乐要用聆听。"}, {"text": "他蹲在河边监视鱼儿游来游去，看得入迷。", "explanation": "这里应该用〈观赏〉。监视是为了防止走开或作恶而一直看着，为欣赏鱼儿游动而看，要用观赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '806ae7b5-dadc-4dc7-a914-0fef1f8fe816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
